    q('[data-ccc-library-backup-import]').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;const status=q('[data-ccc-library-backup-status]');try{if(file.size>1024*1024)throw new Error('Library backup is larger than 1 MB.');const backup=JSON.parse(await file.text());if(!backup||backup.format!=='curioid-personal-library'||Number(backup.schemaVersion)!==2||!backup.entries||typeof backup.entries!=='object'||Array.isArray(backup.entries))throw new Error('This is not a supported CURIOID personal library backup.');const known=libraryProjectMap(),entries={...libraryState.entries};let imported=0;for(const [id,value] of Object.entries(backup.entries).slice(0,LIBRARY_MAX_ENTRIES)){if(!known.has(id))continue;const incoming=cleanLibraryEntry(value),current=cleanLibraryEntry(entries[id]);entries[id]=cleanLibraryEntry({saved:current.saved||incoming.saved,favorite:current.favorite||incoming.favorite,note:incoming.note||current.note,tags:[...current.tags,...incoming.tags],lastOpenedAt:Math.max(current.lastOpenedAt,incoming.lastOpenedAt),launchCount:Math.max(current.launchCount,incoming.launchCount)});imported++;}libraryState={schemaVersion:2,entries};if(!saveLibraryState())throw new Error('The imported collection could not be saved. Check browser storage availability.');status.textContent=`Imported or merged ${imported} application records. No application code was installed.`;renderLibrary();}catch(error){status.textContent=error.message||'Could not import this library backup.';}finally{event.target.value='';}});
    function renderEvents(){q('[data-ccc-events]').innerHTML=eventRows.map(item=>`<article class="ccc-event"><b>${escHtml(item.type)}</b><small>${escHtml(item.sourceExperienceId)} · ${escHtml(item.timestamp)}</small></article>`).join('')||'<p class="ccc-empty">No Connect events captured in this session yet.</p>';}
