    js:`const status=document.querySelector('#status');document.querySelector('#save').addEventListener('click',async()=>{try{await CurioidOS.storage.set('thought',document.querySelector('#thought').value);status.textContent='Saved in this OS local vault.';}catch(error){status.textContent=error.message;}});document.querySelector('#list').addEventListener('click',async()=>{const value=await CurioidOS.storage.get('thought');status.textContent=value||'No saved thought yet.';});CurioidOS.onCapability(({id,input})=>({message:'Hello from this local OS',capability:id,received:input}));CurioidOS.onExport(async()=>[{type:'my-world/thought',title:'My saved thought',data:{text:(await CurioidOS.storage.get('thought'))||''}}]);CurioidOS.onImport(async({payload})=>{if(payload?.text!==undefined)await CurioidOS.storage.set('thought',String(payload.text).slice(0,12000));return{imported:true};});`
