  function curioidOsBuildHybridSource(simple,addons={}){
    if(!simple||typeof simple!=='object')throw new Error('Hybrid mode needs a valid Basic OS source.');
    const htmlAddon=String(addons.html||''),cssAddon=String(addons.css||''),workerAddon=String(addons.workerJs||'');
    if(htmlAddon.length>60000||cssAddon.length>80000||workerAddon.length>64000)throw new Error('Hybrid additions exceed their individual size limits.');
    let html=String(simple.html||''),css=String(simple.css||''),workerJs=String(simple.workerJs||'');
    if(htmlAddon.trim()){
      const close=html.toLowerCase().lastIndexOf('</main>');
      if(close<0)throw new Error('The generated Basic OS does not contain its expected extension area.');
      html=html.slice(0,close)+'<section class="simple-extension-panel" aria-label="Custom hybrid additions">'+htmlAddon+'</section>'+html.slice(close);
    }
    if(cssAddon.trim())css+='\n/* Hybrid CSS additions */\n'+cssAddon;
    if(workerAddon.trim()){
      const finalClose=workerJs.lastIndexOf('})();');
      if(finalClose<0||workerJs.slice(finalClose+5).trim())throw new Error('The generated Basic OS Worker has an unexpected structure; custom logic was not attached.');
      workerJs=workerJs.slice(0,finalClose)+'\n/* Hybrid Worker additions */\n'+workerAddon+'\n'+workerJs.slice(finalClose);
    }
    if(html.length>CURIOID_OS_SOURCE_LIMITS.html||css.length>CURIOID_OS_SOURCE_LIMITS.css||workerJs.length>CURIOID_OS_SOURCE_LIMITS.workerJs)throw new Error('The combined Hybrid OS exceeds a source-size limit. Remove some additions and try again.');
    return{...simple,html,css,js:'',workerJs};
  }

