      const viewLeft = Math.max(0, Number(viewport?.offsetLeft) || 0);
      const viewTop = Math.max(0, Number(viewport?.offsetTop) || 0);
      const viewRight = viewLeft + Math.max(1, Number(viewport?.width) || window.innerWidth || 1);
      const viewBottom = viewTop + Math.max(1, Number(viewport?.height) || window.innerHeight || 1);
      const leftEdge = Math.max(shellRect.left, viewLeft);
      const rightEdge = Math.min(shellRect.right, viewRight);
      const topEdge = Math.max(shellRect.top, viewTop) + 6;
      const bottomEdge = Math.min(shellRect.bottom, taskbarRect?.height > 0 ? taskbarRect.top - 6 : shellRect.bottom, viewBottom) - 6;
      const availableWidth = Math.max(1, rightEdge - leftEdge - 12);
      const availableHeight = Math.max(1, bottomEdge - topEdge);
      const width = Math.min(1020, availableWidth);
      const height = Math.min(860, availableHeight);
