      dialog.style.left = `${Math.max(viewLeft, leftEdge + (availableWidth - width) / 2)}px`;
      dialog.style.top = `${Math.max(viewTop, topEdge + (availableHeight - height) / 2)}px`;
      dialog.style.width = `${width}px`;
      dialog.style.height = `${height}px`;
      dialog.style.maxWidth = `${availableWidth}px`;
      dialog.style.maxHeight = `${availableHeight}px`;
      dialog.style.minWidth = '0';
      dialog.style.minHeight = '0';
      dialog.style.margin = '0';
