      trigger.setAttribute('aria-label', inboxUnread ? `Open CURIOID Exchange, ${inboxUnread} new messages` : 'Open CURIOID Exchange');
      trigger.title = inboxUnread ? `CURIOID Exchange · ${inboxUnread} new message${inboxUnread === 1 ? '' : 's'}` : 'CURIOID Exchange · Shared folders, messages and file handoffs';
