    function resize(){const r=canvas.getBoundingClientRect(),nw=Math.max(1,r.width||canvas.clientWidth||1),nh=Math.max(1,r.height||canvas.clientHeight||1),nd=Math.min(1.5,window.devicePixelRatio||1);w=nw;h=nh;dpr=nd;const pw=Math.max(1,Math.round(w*dpr)),ph=Math.max(1,Math.round(h*dpr));if(canvas.width!==pw)canvas.width=pw;if(canvas.height!==ph)canvas.height=ph;ctx.setTransform(dpr,0,0,dpr,0,0);draw(performance.now());}const stopResize=observeResize(canvas,resize);
