    function burst(x,y,color,count=14){for(let i=0;i<count;i++){const a=rand(0,Math.PI*2),v=rand(.05,.32);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.25,.8),max:.8,color});}}
