      for(let i=0;i<150;i++){const sx=(i*97%997)/997*w,sy=(i*173%991)/991*h;ctx.globalAlpha=.14+(i%7)*.055;ctx.fillStyle=i%11===0?'#ff9cba':'#dbe8ff';ctx.fillRect(sx,sy,i%17===0?2:1,i%17===0?2:1);}ctx.globalAlpha=1;
      ctx.strokeStyle='rgba(186,167,255,.12)';ctx.lineWidth=1;for(let r=28;r<Math.max(w,h);r+=35){ctx.beginPath();ctx.ellipse(w*.48,h*.5,r,r*.6,Math.sin(now*.00015)*.12,0,Math.PI*2);ctx.stroke();}
      wells.forEach(z=>{const x=z.x*w+Math.sin(now*.00032+z.p)*w*.015,y=z.y*h+Math.cos(now*.0004+z.p)*h*.018,R=z.r*w*2;const g=ctx.createRadialGradient(x,y,1,x,y,R);g.addColorStop(0,'#08070d');g.addColorStop(.35,'#171020');g.addColorStop(.7,'rgba(128,72,133,.25)');g.addColorStop(1,'rgba(125,91,170,0)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,R,0,Math.PI*2);ctx.fill();ctx.strokeStyle='rgba(195,153,230,.5)';ctx.lineWidth=1.3;ctx.beginPath();ctx.ellipse(x,y,z.r*w*(1.15+Math.sin(now*.001+z.p)*.08),z.r*w*.62,now*.0002+z.p,0,Math.PI*2);ctx.stroke();});
      shards.forEach(s=>{if(s.got)return;const x=s.x*w,y=s.y*h,a=now*.002+s.spin;ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.shadowColor='#d6ff69';ctx.shadowBlur=18;ctx.fillStyle='#d6ff69';ctx.beginPath();ctx.moveTo(0,-9);ctx.lineTo(7,0);ctx.lineTo(0,9);ctx.lineTo(-7,0);ctx.closePath();ctx.fill();ctx.restore();});
