  function curioidDoors98DriveQuotaError(records) {
    if (!Array.isArray(records)) return 'C: storage data is invalid. Export a backup before continuing.';
    if (records.length > CURIOID_DOORS98_MAX_CDRIVE_ITEMS) return `C: supports up to ${CURIOID_DOORS98_MAX_CDRIVE_ITEMS.toLocaleString()} active and returned keys. Empty Key Return or remove unused keys before adding more.`;
    const ids = new Set();
    let total = 0;
    for (const record of records) {
      if (!record || typeof record.id !== 'string' || !record.id || ids.has(record.id)) return 'C: contains an invalid or duplicate key identifier. No changes were saved.';
      ids.add(record.id);
      const rawSize = record.blob && Number.isFinite(record.blob.size) ? record.blob.size : Number(record.size);
      const size = Number.isFinite(rawSize) && rawSize >= 0 ? Math.floor(rawSize) : new Blob([String(record.content || '')]).size;
      if (size > CURIOID_DOORS98_MAX_CDRIVE_BYTES) return 'A single C: key exceeds the 512 MB safety limit.';
      if (!record.blob && typeof record.content === 'string' && new Blob([record.content]).size > CURIOID_DOORS98_MAX_TEXT_KEY_BYTES) return 'Text keys are limited to 32 MB to protect browser memory. Split the document or save it as an exported file.';
      total += size;
      if (!Number.isSafeInteger(total) || total > CURIOID_DOORS98_MAX_CDRIVE_BYTES) return 'C: has reached its 512 MB total storage limit, including Key Return. Export a backup or empty Key Return before adding more files.';
    }
    return '';
  }

  function curioidDoors98DriveMergePlan(baseline, actualRecords, targetRecords, fingerprint) {
    const base = baseline instanceof Map ? baseline : new Map(baseline || []);
    const actualMap = new Map((actualRecords || []).map(record => [record.id, record]));
    const actualFingerprints = new Map((actualRecords || []).map(record => [record.id, fingerprint(record, record._state === 'returned' || record.deletedAt ? 'returned' : 'active')]));
    const targetMap = new Map((targetRecords || []).map(record => [record.id, record]));
    const puts = [], deletes = [], conflicts = [];
    for (const record of targetRecords || []) {
      const id = record.id, desired = fingerprint(record, record._state), expected = base.get(id), actual = actualFingerprints.get(id);
      if (expected === desired) continue;
      if (expected === undefined && actual !== undefined) {
        if (actual === desired) continue; // Same initial seed written by another tab.
        conflicts.push(`C: key identifier collision for ${id}. Reload Doors98 and retry.`);
        continue;
      }
      if (expected !== actual) {
        conflicts.push(`C: key "${String(record.name || id).slice(0, 80)}" changed in another tab. Reload Doors98 to avoid overwriting newer work.`);
        continue;
      }
      puts.push(record);
    }
    for (const [id, expected] of base) {
      if (targetMap.has(id)) continue;
      const actual = actualFingerprints.get(id);
      if (expected !== actual) conflicts.push(`C: key ${id} changed in another tab and was not deleted.`);
      else deletes.push(id);
    }
    if (conflicts.length) return { puts: [], deletes: [], mergedMap: new Map(actualMap), error: conflicts[0], conflicts };
    const mergedMap = new Map(actualMap);
    for (const record of puts) mergedMap.set(record.id, record);
    for (const id of deletes) mergedMap.delete(id);
    return { puts, deletes, mergedMap, error: '', conflicts: [] };
  }

