          if(tooLarge)throw new Error(`${tooLarge.name} is larger than the 250 MB per-file import limit.`);
          const total=chosen.reduce((sum,file)=>sum+file.size,0);
          if(total>512*1024*1024)throw new Error('This batch exceeds the 512 MB safety limit. Copy fewer or smaller files.');
