        const buildVectorSvg=(labels,values,min,max,kind,label)=>{const w=900,h=480,left=75,right=30,top=88,base=405,plotH=base-top,span=max-min||1,scale=v=>base-(v-min)/span*plotH;let marks='';for(let i=0;i<5;i++){const y=top+i*plotH/4,v=max-i*span/4;marks+=`<line x1="${left}" y1="${y}" x2="${w-right}" y2="${y}" stroke="#bdc7b7"/><text x="${left-10}" y="${y+4}" text-anchor="end" font-size="11" fill="#66766a">${Number(v.toFixed(2))}</text>`;}if(kind==='bar'){const step=(w-left-right)/values.length,bw=Math.max(2,step*.62);values.forEach((v,i)=>{const bh=(v-min)/span*plotH,x=left+i*step+(step-bw)/2,y=scale(v);marks+=`<rect x="${x.toFixed(2)}" y="${y.toFixed(2)}" width="${bw.toFixed(2)}" height="${Math.max(0,bh).toFixed(2)}" fill="#637d6b"/><text x="${(x+bw/2).toFixed(2)}" y="${base+17}" transform="rotate(-45 ${(x+bw/2).toFixed(2)} ${base+17})" font-size="11" fill="#526457">${esc(labels[i].slice(0,18))}</text>`;});}else{const pts=values.map((v,i)=>({x:left+i*(w-left-right)/Math.max(1,values.length-1),y:scale(v)}));marks+=`<polyline points="${pts.map(p=>`${p.x.toFixed(2)},${p.y.toFixed(2)}`).join(' ')}" fill="none" stroke="#637d6b" stroke-width="4" stroke-linejoin="round"/>`;pts.forEach((p,i)=>{marks+=`<circle cx="${p.x.toFixed(2)}" cy="${p.y.toFixed(2)}" r="6" fill="#bb7657"/><text x="${p.x.toFixed(2)}" y="${base+22}" text-anchor="middle" font-size="10" fill="#526457">${esc(labels[i].slice(0,12))}</text>`;});}return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><title>${esc(label)}</title><rect width="100%" height="100%" fill="#f3f1e6"/><text x="44" y="42" font-family="Arial,sans-serif" font-size="24" font-weight="700" fill="#3a5145">${esc(label.slice(0,64))}</text>${marks}<text x="60" y="465" font-family="monospace" font-size="12" fill="#6e7b6d">MIN ${Math.min(...values)}   MAX ${Math.max(...values)}   N ${values.length}</text></svg>`;};
