        try{if(rawHabits.length>MAX_FILE)throw new Error('Saved habit data exceeds the safe 1 MB limit.');const parsed=JSON.parse(rawHabits);if(!Array.isArray(parsed)||parsed.length>MAX_HABITS)throw new Error('Saved habit data has an invalid format or too many habits.');habits=parsed.map(item=>{if(!item||typeof item!=='object'||Array.isArray(item)||typeof item.name!=='string'||!Array.isArray(item.days))throw new Error('A saved habit contains invalid data.');const days=[...new Set(item.days.filter(validDate))].slice(-MAX_DAYS);return{name:item.name.replace(/[\u0000-\u001f\u007f]/g,' ').trim().slice(0,100),days};});}catch(error){loadError=error.message||'Saved habit data could not be read safely.';recovery.hidden=false;status.textContent=loadError+' Your original data has not been changed.';}
