        const dateFor=i=>{const d=new Date(weekStart);d.setDate(d.getDate()+i);return d;},dayKey=i=>{const d=dateFor(i);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
