        try{rawSessions=String(safeGet(key,'[]'));if(rawSessions.length>MAX_FILE)throw new Error('The saved time log exceeds the safe 1 MB limit.');const parsed=JSON.parse(rawSessions);if(!Array.isArray(parsed)||parsed.length>MAX_SESSIONS)throw new Error('The saved time log has an invalid format or exceeds 500 sessions.');sessions=parsed.map(x=>{if(!x||typeof x!=='object'||Array.isArray(x)||typeof x.project!=='string'||typeof x.start!=='string'||typeof x.end!=='string'||!Number.isFinite(x.duration)||x.duration<0||x.duration>366*86400000||!Number.isFinite(Date.parse(x.start))||!Number.isFinite(Date.parse(x.end)))throw new Error('A saved time session contains invalid dates or duration.');return{project:x.project.slice(0,120),start:new Date(x.start).toISOString(),end:new Date(x.end).toISOString(),duration:Math.round(x.duration)};});}catch(error){loadError=error.message||'The saved time log could not be read safely.';}
