  // 30 - Shape Composer: extreme but composed generative poster geometry.
  function shapeComposerMarkup(){return projectFrame('Creative tool / 12','Shape Composer','Make a graphic system from geometry, density and controlled disorder. Push the composition to the edge, then keep the useful accident.',`<canvas class="shape-composer-canvas" width="1080" height="760" aria-label="Generative geometric composition"></canvas><div class="tool-button-row">${action('New composition','shape-new',true)}${action('Go extreme','shape-extreme')}${action('Save PNG to Vault','shape-export')}</div><p class="tool-small" data-shape-seed>COMPOSITION / 000001</p>`,panel('Composition rules',select('Visual language','shape-style',[['cut','Cut paper'],['technical','Technical drawing'],['soft','Soft sculpture'],['signal','Signal geometry'],['brutal','Brutalist blocks']])+select('Palette','shape-palette',[['mineral','Mineral'],['bruise','Bruise'],['dusk','Dusk'],['sterile','Ceramic'],['signal','Signal']])+range('Elements','shape-count',8,150,88)+range('Symmetry','shape-symmetry',1,16,5)+range('Disorder','shape-chaos',0,100,86)+range('Surface noise','shape-grain',0,100,26)),'The output is original procedural vector-like art rendered locally to Canvas. Export a high-resolution PNG.');}
  function bindShapeComposer(root){const canvas=$('.shape-composer-canvas',root),ctx=canvas.getContext('2d');let seed=319;function draw(target=canvas,high=false){const c=target.getContext('2d'),w=target.width,h=target.height,style=$('[data-select="shape-style"]',root).value,pal=palettes[$('[data-select="shape-palette"]',root).value]||palettes.signal,count=+$('[data-range="shape-count"]',root).value,sym=+$('[data-range="shape-symmetry"]',root).value,chaos=+$('[data-range="shape-chaos"]',root).value/100,grain=+$('[data-range="shape-grain"]',root).value/100;let state=seed>>>0;const r=()=>{state=(Math.imul(state,1664525)+1013904223)>>>0;return state/4294967296;};c.fillStyle='#12141b';c.fillRect(0,0,w,h);const bg=c.createLinearGradient(0,0,w,h);bg.addColorStop(0,pal[0]);bg.addColorStop(1,'#12141b');c.globalAlpha=.72;c.fillStyle=bg;c.fillRect(0,0,w,h);c.globalAlpha=1;c.save();c.translate(w/2,h/2);const maxR=Math.min(w,h)*.47;for(let i=0;i<count;i++){const sector=i%sym,angle=sector*Math.PI*2/sym+(r()-.5)*chaos*.6,radius=maxR*(.08+r()*.92),size=Math.min(w,h)*(.018+r()*.13)*(1+chaos*.8),x=Math.cos(angle)*radius+(r()-.5)*chaos*maxR*.28,y=Math.sin(angle)*radius+(r()-.5)*chaos*maxR*.28,rot=r()*Math.PI*2; c.save();c.translate(x,y);c.rotate(rot);const color=pal[Math.floor(r()*pal.length)];c.globalAlpha=.25+r()*.72;c.fillStyle=color;c.strokeStyle=style==='technical'?color:'#11131a';c.lineWidth=1+r()*5;if(style==='technical'){c.beginPath();c.arc(0,0,size*.5,0,Math.PI*2);c.stroke();c.beginPath();c.moveTo(-size*1.4,0);c.lineTo(size*1.4,0);c.moveTo(0,-size*1.4);c.lineTo(0,size*1.4);c.stroke();}else if(style==='soft'){c.beginPath();c.ellipse(0,0,size*.7,size*(.35+r()),r()*Math.PI,0,Math.PI*2);c.fill();}else if(style==='brutal'){c.fillRect(-size*.5,-size*.5,size*(.4+r()*1.2),size*(.4+r()*1.2));}else{c.beginPath();const sides=style==='signal'?Math.floor(3+r()*6):Math.floor(3+r()*7);for(let j=0;j<sides;j++){const a=j*Math.PI*2/sides,rr=size*(.35+r()*.9);j?c.lineTo(Math.cos(a)*rr,Math.sin(a)*rr):c.moveTo(Math.cos(a)*rr,Math.sin(a)*rr);}c.closePath();c.fill();}if(style==='cut'&&r()<.38){c.globalCompositeOperation='destination-out';c.beginPath();c.arc(size*.2,size*.15,size*.22,0,Math.PI*2);c.fill();c.globalCompositeOperation='source-over';}c.restore();}c.restore();if(grain){let s=seed;for(let i=0;i<w*h*grain*.008;i++){s=(Math.imul(s,1664525)+1013904223)>>>0;const x=s/4294967296*w;s=(Math.imul(s,1664525)+1013904223)>>>0;const y=s/4294967296*h;c.fillStyle=(s&1)?'rgba(255,255,255,.12)':'rgba(0,0,0,.22)';c.fillRect(x,y,1,1);}}c.strokeStyle='rgba(255,255,255,.22)';c.lineWidth=2;c.strokeRect(18,18,w-36,h-36);}
    function redraw(){draw();}$('[data-action="shape-new"]',root).addEventListener('click',()=>{seed=Math.floor(Math.random()*9999999);$('[data-shape-seed]',root).textContent='COMPOSITION / '+String(seed).padStart(6,'0');redraw();});$('[data-action="shape-extreme"]',root).addEventListener('click',()=>{seed=Math.floor(Math.random()*9999999);$('[data-range="shape-count"]',root).value='150';$('[data-range="shape-chaos"]',root).value='100';$('[data-range="shape-grain"]',root).value='88';$('[data-range="shape-symmetry"]',root).value='13';$('[data-select="shape-style"]',root).value=pick(['cut','signal','brutal']);redraw();});['shape-count','shape-symmetry','shape-chaos','shape-grain'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',redraw));['shape-style','shape-palette'].forEach(k=>$(`[data-select="${k}"]`,root).addEventListener('change',redraw));$('[data-action="shape-export"]',root).addEventListener('click',()=>{const out=document.createElement('canvas');out.width=1800;out.height=1267;draw(out,true);saveCanvas(out,'curioid-shape-composition.png');});redraw();return()=>{};}

  // 31 - Icon Set Studio: a family of consistent original SVG icons.
  function iconSetMarkup(){return projectFrame('Creative tool / 13','Icon Set Studio','Generate a distinct family of original interface symbols. Each family shares a visual grammar, but the shapes, cuts, joints and little irregularities change with the seed.',`<div class="icon-set-grid" data-icon-grid></div><div class="tool-button-row">${action('Generate new icon family','icons-random',true)}${action('Save SVG sprite to Vault','icons-export')}${action('Copy symbol usage','icons-copy')}</div><p class="tool-small" data-icon-status>12 original symbols · seed 0007</p>`,panel('Icon construction',select('Visual language','icon-style',[['round','Rounded instrument'],['square','Technical / modular'],['solid','Solid stamps'],['double','Double-line'],['organic','Organic cutouts'],['architectural','Architectural']])+range('Stroke weight','icon-stroke',1,5,2,' px')+range('Shape complexity','icon-complexity',1,10,6)+range('Irregularity','icon-irregularity',0,100,38,'%')+range('Grid size','icon-grid-size',20,48,32)+`<label class="tool-control"><span>Ink color</span><input type="color" data-icon-color value="#d6ff69"></label><label class="tool-check"><input type="checkbox" data-icon-background checked> Show icon tile backgrounds</label>`),'Every regenerate action creates a new set of original vector shapes. Download the sprite and reuse individual symbols in your own interface.');}
  function bindIconSet(root){
    const grid=$('[data-icon-grid]',root),names=['threshold','hinge','witness','orbit','relay','seed-vault','fold','drift','signal','well','archive','passage'];let seed=7,generated=[];
    function randomFactory(start){let s=start>>>0;return()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};}
    function shape(name,index,r,style,complex,irregular){const cx=12+(r()-.5)*irregular*4,cy=12+(r()-.5)*irregular*4,rot=(r()-.5)*irregular*80,points=4+Math.round(complex*.85),base=4+r()*2,outer=8+r()*3,pts=[];for(let i=0;i<points*2;i++){const a=i/(points*2)*Math.PI*2-Math.PI/2,rad=i%2?base:outer*(.7+r()*.35);pts.push(`${(12+Math.cos(a)*rad).toFixed(2)},${(12+Math.sin(a)*rad).toFixed(2)}`);}const poly=pts.join(' '),cut=`<path d="M${(cx-outer).toFixed(1)} ${cy.toFixed(1)}h${outer*2}"/>`,stroke=style==='solid'?'none':(style==='double'?'#baa7ff':'currentColor'),fill=style==='solid'?'currentColor':'none',cap=style==='square'?'square':'round',join=style==='square'?'miter':'round';
      const forms=[
        `<polygon points="${poly}"/><circle cx="${cx.toFixed(1)}" cy="${cy.toFixed(1)}" r="${base*.42}"/>`,
        `<path d="M4 20V${4+r()*5}Q12 ${-1+r()*5} 20 ${4+r()*5}V20 M7 20V10Q12 5 17 10V20"/><path d="M12 8v9"/>`,
        `<path d="M3 ${cy}Q${cx} ${-2+r()*6} 21 ${cy}Q${cx} ${26-r()*5} 3 ${cy}Z"/><path d="M${cx} 5v14"/><circle cx="${cx}" cy="${cy}" r="${base*.55}"/>`,
        `<ellipse cx="12" cy="12" rx="${outer}" ry="${base+2}" transform="rotate(${rot} 12 12)"/><ellipse cx="12" cy="12" rx="${base+2}" ry="${outer}" transform="rotate(${-rot} 12 12)"/><circle cx="12" cy="12" r="${base*.33}"/>`,
        `<path d="M3 7Q8 2 12 8T21 7 M3 17Q8 22 12 16T21 17"/><path d="M${cx} 3v18"/>`,
        `<path d="M12 2C5 7 4 15 12 22C20 15 19 7 12 2Z"/><path d="M12 5v14M7 12h10"/>`,
        `<path d="M4 4h16v16H4z"/><path d="M4 12h16M12 4v16"/><path d="M7 7l10 10"/>`,
        `<path d="M3 18Q5 4 12 8T21 5M3 21Q11 16 21 18"/><circle cx="${cx}" cy="${cy}" r="${base*.55}"/>`,
        `<path d="M4 19V9l8-6 8 6v10z"/><path d="M8 19v-6h8v6M12 3v7"/>`,
        `<circle cx="12" cy="12" r="${outer}"/><path d="M12 3v18M3 12h18"/><circle cx="12" cy="12" r="${base*.6}"/>`,
        `<path d="M3 6h18v4H3zM5 10v11h14V10M9 14h6"/><path d="M${cx} 3v3"/>`,
        `<path d="M4 21V4h8q7 0 7 6t-7 6H9v5"/><path d="M14 16l6 5"/>`
      ];let adorn='';for(let i=0;i<Math.ceil(complex/2);i++){const a=r()*Math.PI*2,rad=4+r()*7,x=12+Math.cos(a)*rad,y=12+Math.sin(a)*rad;adorn+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${.35+r()*1.2}" fill="currentColor"/>`;}const notch=irregular>.35&&r()<irregular?`<path d="M${(2+r()*5).toFixed(1)} 3l${(6+r()*4).toFixed(1)} 4" stroke="#15151c" stroke-width="${1+irregular*3}"/>`:'';return `<g transform="rotate(${rot.toFixed(1)} 12 12)" fill="${fill}" stroke="${stroke}" stroke-width="${style==='solid'?0:1+complex*.22}" stroke-linecap="${cap}" stroke-linejoin="${join}">${forms[index%forms.length]}${adorn}${notch}</g>`;
    }
    function build(){const style=$('[data-select="icon-style"]',root).value,weight=+$('[data-range="icon-stroke"]',root).value,complex=+$('[data-range="icon-complexity"]',root).value,irregular=+$('[data-range="icon-irregularity"]',root).value/100,size=+$('[data-range="icon-grid-size"]',root).value,color=$('[data-icon-color]',root).value,bg=$('[data-icon-background]',root).checked,r=randomFactory(seed);generated=names.map((name,i)=>shape(name,i,r,style,complex,irregular));grid.innerHTML=names.map((name,i)=>`<div class="icon-set-item" style="${bg?'':'background:transparent;border-color:transparent'}"><svg viewBox="0 0 24 24" role="img" aria-label="${esc(name)}" style="color:${esc(color)};width:min(100%,${size*1.45}px)">${generated[i].replace(/stroke-width="[^"]*"/g,`stroke-width="${weight}"`)}</svg><small>${name}</small></div>`).join('');$('[data-icon-status]',root).textContent=`12 original symbols · seed ${String(seed).padStart(6,'0')} · ${style} · irregularity ${Math.round(irregular*100)}%`;}
    ['icon-style','icon-color','icon-background','icon-stroke','icon-grid-size','icon-complexity','icon-irregularity'].forEach(k=>{const el=k==='icon-style'?$(`[data-select="${k}"]`,root):k==='icon-stroke'||k==='icon-grid-size'||k==='icon-complexity'||k==='icon-irregularity'?$(`[data-range="${k}"]`,root):k==='icon-color'?$('[data-icon-color]',root):$('[data-icon-background]',root);el.addEventListener('input',build);el.addEventListener('change',build);});
    $('[data-action="icons-random"]',root).addEventListener('click',()=>{seed=Math.floor(Math.random()*999999);$('[data-icon-color]',root).value=pick(['#d6ff69','#baa7ff','#ff9cba','#85e6da','#f0d7a8','#ff784f']);$('[data-select="icon-style"]',root).value=pick(['round','square','solid','double','organic','architectural']);$('[data-range="icon-complexity"]',root).value=String(Math.floor(rand(4,10)));$('[data-range="icon-irregularity"]',root).value=String(Math.floor(rand(22,90)));build();});
    $('[data-action="icons-export"]',root).addEventListener('click',()=>{const color=$('[data-icon-color]',root).value,sprite=`<svg xmlns="http://www.w3.org/2000/svg"><defs>${names.map((n,i)=>`<symbol id="curioid-${n}" viewBox="0 0 24 24"><g color="${color}">${generated[i].replace(/stroke-width="[^"]*"/g,`stroke-width="${+$('[data-range="icon-stroke"]',root).value}"`)}</g></symbol>`).join('')}</defs></svg>`;downloadBlob(new Blob([sprite],{type:'image/svg+xml'}),'curioid-icon-sprite.svg');});
    $('[data-action="icons-copy"]',root).addEventListener('click',async()=>{const text=names.map(n=>`<svg viewBox="0 0 24 24"><use href="icons.svg#curioid-${n}" /></svg>`).join('\n');try{await curioidClipboard.writeText(text);toast(null,'Symbol usage copied.');}catch(_){downloadBlob(new Blob([text],{type:'text/plain'}),'curioid-icon-usage.html');}});build();return()=>{};
  }


  // Additional digital-art projects
  function faultlinePortraitMarkup(){
    return projectFrame('Digital art / 04','Faultline Portrait','Build a face from displaced mineral bands, mismatched features and a few details that refuse to line up. The portrait stays recognizable while its structure drifts.',`<div class="tool-canvas-wrap art-canvas-wrap"><canvas class="tool-canvas" data-faultline-canvas width="900" height="650" aria-label="Generated fractured portrait"></canvas></div><div class="tool-button-row">${action('Mutate portrait','faultline-mutate',true)}${action('Push it too far','faultline-extreme')}${action('Export portrait','faultline-export')}</div><p class="tool-small" data-faultline-seed>PORTRAIT / 000001</p>`,panel('Portrait anatomy',range('Contour bands','faultline-bands',4,32,17)+range('Asymmetry','faultline-asym',0,100,68)+range('Fracture','faultline-fracture',0,100,58)+range('Feature displacement','faultline-shift',0,100,63)+select('Material','faultline-material',[['mineral','Mineral / bone'],['porcelain','Old porcelain'],['oxide','Oxidized metal'],['velvet','Velvet / shadow'],['signal','Signal residue']])+select('Palette','faultline-palette',[['mineral','Mineral'],['bruise','Bruise'],['dusk','Dusk'],['sterile','Sterile'],['signal','Signal']])),'A deterministic portrait seed is used for each mutation. Export creates a full-size PNG locally; nothing is uploaded.');
  }
  function bindFaultlinePortrait(root){
    const canvas=$('[data-faultline-canvas]',root);let seed=Math.floor(Math.random()*999999)+1;
    function draw(target=canvas){const c=target.getContext('2d');const w=target.width,h=target.height,bands=+$('[data-range="faultline-bands"]',root).value,asym=+$('[data-range="faultline-asym"]',root).value/100,fract=+$('[data-range="faultline-fracture"]',root).value/100,shift=+$('[data-range="faultline-shift"]',root).value/100,material=$('[data-select="faultline-material"]',root).value,pal=palettes[$('[data-select="faultline-palette"]',root).value]||palettes.mineral;let s=seed;const r=()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};
      c.fillStyle='#11131a';c.fillRect(0,0,w,h);const bg=c.createLinearGradient(0,0,w,h);bg.addColorStop(0,pal[0]+'22');bg.addColorStop(.5,'#171820');bg.addColorStop(1,pal[2]+'33');c.fillStyle=bg;c.fillRect(0,0,w,h);
      c.save();c.translate(w*.5,h*.52);const faceW=w*.235,faceH=h*.405;const skew=(r()-.5)*asym*.35;
      const face=c.createLinearGradient(-faceW,-faceH,faceW,faceH);face.addColorStop(0,material==='porcelain'?'#d9c7bd':material==='oxide'?'#77847e':material==='velvet'?'#312936':pal[1]);face.addColorStop(.48,material==='mineral'?'#938b80':pal[3]);face.addColorStop(1,material==='signal'?'#6a7e79':pal[0]);
      c.beginPath();c.moveTo(-faceW*.58+skew,-faceH);c.bezierCurveTo(faceW*.72,-faceH*1.08,faceW*1.04,-faceH*.44,faceW*.9,faceH*.08);c.bezierCurveTo(faceW*.87,faceH*.74,faceW*.4,faceH*1.02,0,faceH);c.bezierCurveTo(-faceW*.62,faceH*.97,-faceW*1.05,faceH*.42,-faceW*.92,-faceH*.08);c.bezierCurveTo(-faceW*.86,-faceH*.78,-faceW*.3,-faceH*1.07,-faceW*.58+skew,-faceH);c.closePath();c.fillStyle=face;c.fill();c.strokeStyle=pal[4];c.lineWidth=3;c.stroke();
      // Contour bands are offset independently, like slices of a face remembered incorrectly.
      c.save();c.clip();for(let i=0;i<bands;i++){const y=-faceH+(i/(bands-1))*faceH*2;const wobble=(r()-.5)*fract*faceW*.62;const offset=(r()-.5)*shift*faceW*.55;const bandH=faceH*2/bands*(.6+r()*.85);c.beginPath();c.moveTo(-faceW*1.2,y);c.bezierCurveTo(-faceW*.5+wobble,y-bandH*.4,faceW*.1+offset,y+bandH*.6,faceW*1.2,y+bandH*.2);c.lineTo(faceW*1.2,y+bandH);c.bezierCurveTo(faceW*.2+offset,y+bandH*.3,-faceW*.7+wobble,y+bandH*1.5,-faceW*1.2,y+bandH);c.closePath();c.fillStyle=pal[Math.floor(r()*pal.length)];c.globalAlpha=.16+r()*.33;c.fill();c.globalAlpha=1;c.strokeStyle=pal[4];c.globalAlpha=.12+r()*.24;c.lineWidth=1+r()*4;c.stroke();c.globalAlpha=1;}
      // Features intentionally do not share a common centreline.
      const eyeY=-faceH*.17,eyeSep=faceW*.52;for(let i=0;i<2;i++){const ex=(i?1:-1)*eyeSep+(r()-.5)*shift*faceW*.45,ey=eyeY+(r()-.5)*asym*faceH*.45,ew=faceW*(.16+r()*.12),eh=faceH*(.025+r()*.045);c.save();c.translate(ex,ey);c.rotate((r()-.5)*fract*.75);c.fillStyle='#111016';c.beginPath();c.ellipse(0,0,ew,eh,0,0,Math.PI*2);c.fill();c.fillStyle=pal[4];c.beginPath();c.ellipse((r()-.5)*ew*.45,0,eh*.9,eh*.9,0,0,Math.PI*2);c.fill();c.fillStyle='#101015';c.beginPath();c.arc((r()-.5)*ew*.5,0,eh*.35,0,Math.PI*2);c.fill();c.restore();}
      c.beginPath();c.moveTo((r()-.5)*faceW*.22,-faceH*.08);c.lineTo((r()-.5)*faceW*.35,faceH*.34);c.lineTo((r()-.5)*faceW*.16,faceH*.4);c.strokeStyle=pal[4];c.lineWidth=6;c.stroke();
      c.beginPath();const mouthY=faceH*.61+(r()-.5)*shift*faceH*.22;c.moveTo(-faceW*.23,mouthY);c.quadraticCurveTo((r()-.5)*faceW*.45,mouthY+faceH*(.01+fract*.12),faceW*.22,mouthY+(r()-.5)*fract*faceH*.08);c.strokeStyle='#120e15';c.lineWidth=4+fract*9;c.stroke();
      for(let i=0;i<Math.floor(fract*22);i++){const x=(r()-.5)*faceW*1.6,y=(r()-.5)*faceH*1.6;c.beginPath();c.moveTo(x,y);c.lineTo(x+(r()-.5)*faceW*.65,y+(r()-.5)*faceH*.8);c.strokeStyle=pal[Math.floor(r()*pal.length)];c.globalAlpha=.28;c.lineWidth=1+r()*3;c.stroke();c.globalAlpha=1;}
      c.restore();c.restore();
      c.fillStyle='rgba(242,237,224,.5)';c.font='12px monospace';c.fillText(`FIELD STUDY   ${String(seed).padStart(6,'0')}`,28,h-25);c.fillStyle='rgba(214,255,105,.55)';c.textAlign='right';c.fillText('PORTRAIT / INCOMPLETE',w-28,h-25);c.textAlign='left';}
    const redraw=()=>draw();$$('[data-range^="faultline-"]',root).forEach(el=>el.addEventListener('input',redraw));$$('[data-select^="faultline-"]',root).forEach(el=>el.addEventListener('change',redraw));$('[data-action="faultline-mutate"]',root).addEventListener('click',()=>{seed=Math.floor(Math.random()*999999)+1;$('[data-faultline-seed]',root).textContent=`PORTRAIT / ${String(seed).padStart(6,'0')}`;draw();});$('[data-action="faultline-extreme"]',root).addEventListener('click',()=>{for(const [name,value] of [['faultline-bands',30],['faultline-asym',100],['faultline-fracture',100],['faultline-shift',100]])$(`[data-range="${name}"]`,root).value=String(value);$('[data-select="faultline-material"]',root).value='oxide';$('[data-select="faultline-palette"]',root).value='bruise';seed=Math.floor(Math.random()*999999)+1;draw();});$('[data-action="faultline-export"]',root).addEventListener('click',()=>{const out=document.createElement('canvas');out.width=1800;out.height=1300;draw(out);saveCanvas(out,'curioid-faultline-portrait.png');});draw();return()=>{};
  }

  function velvetWeatherMarkup(){return projectFrame('Digital art / 05','Velvet Weather','A slow forecast for a sky that almost follows familiar rules. Change the pressure, the horizon and the weather system; the landscape keeps moving.',`<div class="tool-canvas-wrap"><canvas class="tool-canvas" data-velvet-canvas width="900" height="520" aria-label="Animated imaginary weather landscape"></canvas></div><div class="tool-button-row">${action('New forecast','velvet-new',true)}${action('Make it impossible','velvet-impossible')}${action('Export forecast','velvet-export')}</div><p class="tool-small" data-velvet-code>FORECAST / 0001</p>`,panel('Atmospheric controls',select('Weather system','velvet-weather',[['overcast','Soft overcast'],['electric','Electrical rain'],['dry','Dry aurora'],['snow','Warm snowfall'],['eclipse','False eclipse'],['glass','Glass mist']])+range('Wind drift','velvet-wind',0,100,42)+range('Horizon height','velvet-horizon',20,80,54,'%')+range('Atmospheric pressure','velvet-pressure',0,100,63)+range('Unnatural light','velvet-light',0,100,46)),'The sky is animated only while visible. Export a still frame as a large PNG; all rendering is local.');}
  function bindVelvetWeather(root){
    const canvas=$('[data-velvet-canvas]',root);let seed=Math.floor(Math.random()*100000),clouds=[],bolts=[],boltClock=.4;
    function makeClouds(){clouds=Array.from({length:15},(_,i)=>({x:((i*73+seed%97)%100)/100,y:.08+((i*31+seed%53)%57)/100,scale:.35+((i*13+seed%19)%70)/100,alpha:.025+((i*7+seed%13)%24)/100}));}
    function makeBolt(){
      const x=rand(.08,.92),start=.09+Math.random()*.13,end=.78+Math.random()*.16,segments=13+Math.floor(Math.random()*10),points=[[x,start]];let px=x,py=start;
      for(let i=1;i<=segments;i++){py=start+(end-start)*i/segments;px=clamp(px+rand(-.055,.055),.025,.975);points.push([px,py]);}
      const branches=[];for(let j=0;j<3+Math.floor(Math.random()*5);j++){const from=Math.floor(rand(2,points.length-2)),origin=points[from],dir=Math.random()<.5?-1:1,len=rand(.055,.16),branch=[[origin[0],origin[1]]];let bx=origin[0],by=origin[1];for(let k=1;k<=3;k++){bx=clamp(bx+dir*len/3+rand(-.018,.018),.01,.99);by+=rand(.025,.055);branch.push([bx,by]);}branches.push(branch);}
      return {points,branches,life:rand(.17,.32),duration:.32,flash:rand(.6,1)};
    }
    function drawBoltPath(ctx,points,w,h,width,color,blur){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0]*w,p[1]*h):ctx.moveTo(p[0]*w,p[1]*h));ctx.lineWidth=width;ctx.strokeStyle=color;ctx.shadowColor='#b8d9ff';ctx.shadowBlur=blur;ctx.lineJoin='round';ctx.lineCap='round';ctx.stroke();}
    makeClouds();
    function paint(ctx,w,h,time,dt,initial){
      const mode=$('[data-select="velvet-weather"]',root).value,wind=+$('[data-range="velvet-wind"]',root).value/100,hor=+$('[data-range="velvet-horizon"]',root).value/100,pressure=+$('[data-range="velvet-pressure"]',root).value/100,light=+$('[data-range="velvet-light"]',root).value/100;
      const palettesByMode={overcast:['#303a49','#8b7d8c','#d3aa92'],electric:['#101a32','#425b83','#b2c9e7'],dry:['#202a38','#5b657b','#e0ac74'],snow:['#344353','#9b9eaa','#e6b9ad'],eclipse:['#080d18','#302945','#b49bad'],glass:['#263b43','#8bb0a9','#d6d5c1']},p=palettesByMode[mode]||palettesByMode.overcast;
      if(mode==='electric'&&!initial){boltClock-=dt||0;if(boltClock<=0){const count=1+Math.floor(Math.random()*2)+(pressure>.66&&Math.random()<.55?1:0);for(let i=0;i<count;i++)bolts.push(makeBolt());boltClock=rand(.16,.48)*(1.12-pressure*.46)*(1.12-light*.2);}bolts.forEach(b=>b.life-=dt||0);bolts=bolts.filter(b=>b.life>0);}
      else if(mode!=='electric'){bolts=[];boltClock=.35;}
      const g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,p[0]);g.addColorStop(.58,p[1]);g.addColorStop(1,p[2]);ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
      const glow=ctx.createRadialGradient(w*(.25+light*.5),h*(.16+pressure*.2),2,w*(.25+light*.5),h*(.16+pressure*.2),w*.55);glow.addColorStop(0,mode==='eclipse'?'rgba(18,13,25,.9)':mode==='electric'?'rgba(142,188,255,.22)':'rgba(242,200,160,.26)');glow.addColorStop(1,'rgba(10,13,24,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);
      clouds.forEach((cl,i)=>{const x=((cl.x*w+time*(wind*11+1.2)*((i%3)+1))%(w+240))-120,y=cl.y*h;ctx.save();ctx.translate(x,y);ctx.scale(cl.scale*1.7,cl.scale*.64);ctx.fillStyle=mode==='snow'?'rgba(230,238,240,.18)':mode==='electric'?`rgba(9,13,25,${.18+pressure*.32})`:`rgba(20,22,34,${cl.alpha+pressure*.13})`;ctx.beginPath();ctx.ellipse(-28,0,54,22,0,0,Math.PI*2);ctx.ellipse(8,-12,48,30,0,0,Math.PI*2);ctx.ellipse(44,2,49,20,0,0,Math.PI*2);ctx.fill();ctx.restore();});
      const horizon=h*hor;for(let layer=0;layer<4;layer++){ctx.beginPath();ctx.moveTo(0,h);const base=horizon+layer*32;for(let x=0;x<=w+8;x+=8){const y=base+Math.sin(x*.008+layer*1.9+seed*.01)*18+Math.sin(x*.021+layer*.8)*7;ctx.lineTo(x,y);}ctx.lineTo(w,h);ctx.closePath();ctx.fillStyle=['rgba(14,20,29,.22)','rgba(16,23,31,.38)','rgba(13,18,26,.62)','rgba(9,13,19,.88)'][layer];ctx.fill();}
      if(mode==='electric'){
        // Charged rain: hundreds of fast, wind-slanted streaks below the storm shelf.
        ctx.save();ctx.strokeStyle='rgba(175,211,255,.48)';ctx.lineWidth=1;
        for(let i=0;i<125;i++){const x=((i*83.7+Math.sin(time*1.7+i*.4)*22+time*(wind*95+18))%(w+35))-15,y=((i*47.3+time*(230+(i%7)*29))%(Math.max(80,horizon*h*.98))),len=5+(i%5)*2;ctx.globalAlpha=.16+(i%6)*.075;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-wind*12,y+len);ctx.stroke();}ctx.globalAlpha=1;
        // Each discharge is a jagged stepped leader with branching side channels.
        bolts.forEach(b=>{const pulse=clamp(b.life/b.duration,0,1),flicker=(Math.sin(time*92+b.flash*17)>.24?1:.42)*pulse;ctx.save();ctx.globalAlpha=flicker; b.branches.forEach(branch=>{drawBoltPath(ctx,branch,w,h,6,'rgba(107,166,255,.16)',17);drawBoltPath(ctx,branch,w,h,1.7,'rgba(175,217,255,.9)',7);});drawBoltPath(ctx,b.points,w,h,13,'rgba(102,150,255,.2)',28);drawBoltPath(ctx,b.points,w,h,5,'rgba(112,182,255,.75)',15);drawBoltPath(ctx,b.points,w,h,2.15,'#f3f8ff',8);ctx.restore();});
        if(bolts.some(b=>b.life/b.duration>.78)){ctx.fillStyle='rgba(176,205,255,.045)';ctx.fillRect(0,0,w,h);}
      }
      if(mode==='snow'||mode==='glass'){for(let i=0;i<75;i++){const x=(i*137.5+time*(wind*25+4))%(w+20),y=(i*79.3+time*(8+(i%5)*3))%(h*.78);ctx.fillStyle=mode==='snow'?'rgba(240,239,232,.48)':'rgba(194,235,232,.32)';ctx.beginPath();ctx.arc(x,y,mode==='snow'?1.5:2.2,0,Math.PI*2);ctx.fill();}}
      if(mode==='eclipse'){ctx.fillStyle='rgba(7,9,17,.92)';ctx.beginPath();ctx.arc(w*.74,h*.23,54,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(182,153,168,.22)';ctx.beginPath();ctx.arc(w*.74-14,h*.23-6,48,0,Math.PI*2);ctx.fill();}
      if(mode==='dry'){ctx.strokeStyle='rgba(214,255,176,.3)';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(0,h*.28);ctx.bezierCurveTo(w*.27,h*.08,w*.55,h*.48,w,h*.18);ctx.stroke();}
      ctx.fillStyle='rgba(238,231,214,.72)';ctx.font='10px monospace';ctx.fillText(`${mode.toUpperCase()} / PRESSURE ${(pressure*100).toFixed(0)}%`,20,26);
    }
    const renderer=fitCanvas(canvas,paint,true),redraw=()=>renderer.redraw();$$('[data-range^="velvet-"]',root).forEach(el=>el.addEventListener('input',redraw));$('[data-select="velvet-weather"]',root).addEventListener('change',redraw);$('[data-action="velvet-new"]',root).addEventListener('click',()=>{seed=Math.floor(Math.random()*100000);makeClouds();bolts=[];boltClock=.15;$('[data-velvet-code]',root).textContent=`FORECAST / ${String(seed).padStart(6,'0')}`;redraw();});$('[data-action="velvet-impossible"]',root).addEventListener('click',()=>{$('[data-select="velvet-weather"]',root).value='electric';$('[data-range="velvet-wind"]',root).value='88';$('[data-range="velvet-pressure"]',root).value='100';$('[data-range="velvet-light"]',root).value='86';bolts=[];boltClock=0;redraw();});$('[data-action="velvet-export"]',root).addEventListener('click',()=>{const out=document.createElement('canvas');out.width=1800;out.height=1040;const c=out.getContext('2d');paint(c,out.width,out.height,performance.now()/1000,0,true);saveCanvas(out,'curioid-velvet-weather.png');});redraw();return()=>renderer.stop();
  }

  // Tiny games
  function borrowedGravityMarkup(){return projectFrame('Tiny game / 04','Borrowed Gravity','A courier has one small advantage: gravity can be moved. Cross the chamber, collect the signal fragments and reach the door before the room changes its mind.',`<div class="tool-canvas-wrap"><canvas class="tool-canvas" data-borrowed-canvas width="900" height="500" tabindex="0" aria-label="Borrowed Gravity game arena"></canvas></div><div class="tool-button-row">${action('Start / restart run','borrowed-start',true)}${action('Flip gravity','borrowed-flip')}</div><div class="game-touch-pad"><button type="button" class="tool-button" data-action="borrowed-left">← Move left</button><button type="button" class="tool-button" data-action="borrowed-right">Move right →</button></div><p class="tool-small" data-borrowed-status>Collect 5 fragments. Use ← → or A / D to move. Space flips gravity.</p>`,panel('Run record',`<div class="tool-readout"><span>FRAGMENTS</span><strong data-borrowed-score>0 / 5</strong></div><div class="tool-readout"><span>BEST RUN</span><strong data-borrowed-best>0</strong></div><p class="tool-small">The room has two safe surfaces. The middle is not one of them.</p>`),'Keyboard: A / D or arrow keys to move. Space flips gravity. The canvas can also be controlled with the buttons for touch devices.');}
  function bindBorrowedGravity(root){const canvas=$('[data-borrowed-canvas]',root);let running=false,keys={left:false,right:false},player,fragments,gravity=1,score=0,best=0,won=false,renderer=null;try{best=Number(localStorage.getItem('curioid-borrowed-gravity-best')||0)}catch(_){}$('[data-borrowed-best]',root).textContent=String(best);function reset(){player={x:54,y:430,vy:0,r:13};gravity=1;score=0;won=false;fragments=[{x:175,y:90},{x:315,y:410},{x:470,y:95},{x:630,y:410},{x:770,y:100}];$('[data-borrowed-score]',root).textContent='0 / 5';$('[data-borrowed-status]',root).textContent='Find all five fragments, then reach the door.';}
    function flip(){gravity*=-1;player.vy=gravity*90;$('[data-borrowed-status]',root).textContent=gravity>0?'Gravity: floor':'Gravity: ceiling';}
    function paint(c,w,h,t,dt){c.fillStyle='#10151c';c.fillRect(0,0,w,h);const g=c.createLinearGradient(0,0,w,h);g.addColorStop(0,'#1c2533');g.addColorStop(1,'#12151d');c.fillStyle=g;c.fillRect(0,0,w,h);c.strokeStyle='rgba(214,255,105,.12)';c.lineWidth=1;for(let x=0;x<w;x+=32){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke();}for(let y=0;y<h;y+=32){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke();}
      c.fillStyle='#313c48';c.fillRect(0,14,w,18);c.fillRect(0,h-32,w,18);c.fillStyle='#d6ff69';c.fillRect(w-57,h*.34,11,h*.32);c.fillStyle='rgba(255,156,186,.18)';const beamY=h*.5+Math.sin(t*1.2)*h*.08;c.fillRect(0,beamY-3,w,6);c.fillStyle='rgba(255,156,186,.8)';c.fillRect((t*92)%(w+80)-40,beamY-7,80,14);
      if(running&&dt>0){const speed=230;player.x+=(keys.right?1:0)*speed*dt;player.x-=(keys.left?1:0)*speed*dt;player.x=clamp(player.x,player.r+12,w-player.r-16);player.vy+=gravity*690*dt;player.y+=player.vy*dt;if(gravity>0&&player.y>h-45-player.r){player.y=h-45-player.r;player.vy=0;}if(gravity<0&&player.y<45+player.r){player.y=45+player.r;player.vy=0;}if(Math.abs(player.y-beamY)<22&&Math.abs(player.x-((t*92)%(w+80)-40))<42){player.x=54;player.y=gravity>0?h-50:50;score=Math.max(0,score-1);$('[data-borrowed-score]',root).textContent=`${score} / 5`;$('[data-borrowed-status]',root).textContent='The scanner caught the courier. One fragment slipped away.';}
        fragments=fragments.filter(f=>{if(Math.hypot(player.x-f.x,player.y-f.y)<player.r+13){score++;$('[data-borrowed-score]',root).textContent=`${score} / 5`;return false;}return true;});if(score>=5&&player.x>w-78){running=false;won=true;best=Math.max(best,score);try{localStorage.setItem('curioid-borrowed-gravity-best',String(best))}catch(_){}$('[data-borrowed-best]',root).textContent=String(best);$('[data-borrowed-status]',root).textContent='The door opened. The courier was not listed on the manifest.';}}
      fragments.forEach(f=>{c.fillStyle='#d6ff69';c.shadowColor='#d6ff69';c.shadowBlur=16;c.beginPath();c.arc(f.x,f.y,7+Math.sin(t*3+f.x)*1.6,0,Math.PI*2);c.fill();c.shadowBlur=0;});c.fillStyle=gravity>0?'#85e6da':'#baa7ff';c.beginPath();c.arc(player.x,player.y,player.r,0,Math.PI*2);c.fill();c.strokeStyle='#f4f0e8';c.lineWidth=2;c.stroke();c.fillStyle='#11151b';c.beginPath();c.arc(player.x+4,player.y-2,3,0,Math.PI*2);c.fill();if(!running){c.fillStyle='rgba(5,8,13,.52)';c.fillRect(0,0,w,h);c.fillStyle='#e8e7e1';c.textAlign='center';c.font='bold 20px system-ui';c.fillText(won?'DOOR OPEN':'BORROWED GRAVITY',w/2,h/2-10);c.fillStyle='#a7a4b0';c.font='12px monospace';c.fillText(won?'The courier is gone.':'Press Start / restart run',w/2,h/2+18);c.textAlign='left';}}
    reset();renderer=fitCanvas(canvas,paint,true);function start(){reset();running=true;canvas.focus({preventScroll:true});renderer.redraw();}$('[data-action="borrowed-start"]',root).addEventListener('click',start);$('[data-action="borrowed-flip"]',root).addEventListener('click',()=>{if(running)flip();});function onKeyDown(e){if(!root.contains(document.activeElement))return;if(['ArrowLeft','ArrowRight',' ','a','A','d','D'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft'||e.key.toLowerCase()==='a')keys.left=true;if(e.key==='ArrowRight'||e.key.toLowerCase()==='d')keys.right=true;if(e.key===' '&&running)flip();}function onKeyUp(e){if(e.key==='ArrowLeft'||e.key.toLowerCase()==='a')keys.left=false;if(e.key==='ArrowRight'||e.key.toLowerCase()==='d')keys.right=false;}document.addEventListener('keydown',onKeyDown);document.addEventListener('keyup',onKeyUp);[['borrowed-left','left'],['borrowed-right','right']].forEach(([actionName,direction])=>{const b=$(`[data-action="${actionName}"]`,root);b.addEventListener('pointerdown',e=>{e.preventDefault();keys[direction]=true;});['pointerup','pointerleave','pointercancel'].forEach(type=>b.addEventListener(type,()=>keys[direction]=false));});reset();renderer.redraw();return()=>{renderer.stop();document.removeEventListener('keydown',onKeyDown);document.removeEventListener('keyup',onKeyUp);keys.left=keys.right=false;};}

  function roomRemembersMarkup(){return projectFrame('Tiny game / 05','The Room Remembers','A sequence of rooms lights up. Repeat the order. Each round adds another room, and the floor plan begins to disagree with the sequence you remember.',`<div class="memory-game-wrap"><div class="memory-game-top"><span data-memory-status>WAITING FOR THE FIRST ROOM</span><strong data-memory-round>ROUND 0</strong></div><div class="memory-game-grid" data-memory-grid>${Array.from({length:16},(_,i)=>`<button type="button" class="memory-tile" data-memory-tile="${i}" aria-label="Room ${i+1}"><span>${String(i+1).padStart(2,'0')}</span></button>`).join('')}</div><div class="tool-button-row">${action('Begin sequence','memory-start',true)}${action('Replay sequence','memory-replay')}${action('Reset rooms','memory-reset')}</div></div>`,panel('Room notes',`<div class="tool-readout"><span>BEST ROUND</span><strong data-memory-best>0</strong></div><div class="tool-readout"><span>REMAINING ERRORS</span><strong data-memory-lives>3</strong></div><p class="tool-small">Watch first. Then tap the rooms in the exact order. Three errors are permitted before the building closes.</p>`),'The sequence is generated locally and the best round is saved on this device. Use a mouse, touch or keyboard focus to select a room.');}
  function bindRoomRemembers(root,api){const grid=$('[data-memory-grid]',root),tiles=$$('[data-memory-tile]',root),status=$('[data-memory-status]',root),roundOut=$('[data-memory-round]',root),bestOut=$('[data-memory-best]',root),livesOut=$('[data-memory-lives]',root);let sequence=[],input=[],round=0,lives=3,locked=true,timers=new Set(),best=0,disposed=false;try{best=Number(localStorage.getItem('curioid-room-remembers-best')||0)}catch(_){}bestOut.textContent=String(best);const later=(fn,ms)=>{const t=setTimeout(()=>{timers.delete(t);if(!disposed)fn();},ms);timers.add(t);};function clearTimers(){timers.forEach(clearTimeout);timers.clear();}function light(index,on){tiles[index].classList.toggle('lit',on);}function setStatus(text){status.textContent=text;}function showSequence(){clearTimers();locked=true;input=[];setStatus('WATCH THE ROOMS');let at=0;const flash=()=>{if(disposed)return;if(at>0)light(sequence[at-1],false);if(at>=sequence.length){locked=false;setStatus('YOUR TURN - REPEAT THE ORDER');return;}light(sequence[at],true);at++;later(flash,at===1?400:500);};later(flash,320);}function nextRound(){round++;roundOut.textContent=`ROUND ${round}`;sequence.push(Math.floor(Math.random()*16));showSequence();}function begin(){sequence=[];round=0;lives=3;livesOut.textContent='3';roundOut.textContent='ROUND 0';nextRound();}function fail(){lives--;livesOut.textContent=String(lives);locked=true;setStatus('THE ROOM CHANGED ITS MIND');tiles.forEach(t=>t.classList.add('wrong'));later(()=>tiles.forEach(t=>t.classList.remove('wrong')),280);if(lives<=0){setStatus(`BUILDING CLOSED AT ROUND ${round}`);if(round>best){best=round;bestOut.textContent=String(best);try{localStorage.setItem('curioid-room-remembers-best',String(best))}catch(_){}}return;}later(showSequence,620);}function press(index){if(locked||disposed)return;light(index,true);later(()=>light(index,false),130);if(sequence[input.length]!==index){fail();return;}input.push(index);if(input.length===sequence.length){locked=true;setStatus('THAT IS CORRECT. FOR NOW.');if(round>best){best=round;bestOut.textContent=String(best);try{localStorage.setItem('curioid-room-remembers-best',String(best))}catch(_){}}later(nextRound,780);}}tiles.forEach((tile,i)=>tile.addEventListener('click',()=>press(i)));$('[data-action="memory-start"]',root).addEventListener('click',begin);$('[data-action="memory-replay"]',root).addEventListener('click',()=>{if(sequence.length)showSequence();else begin();});$('[data-action="memory-reset"]',root).addEventListener('click',()=>{clearTimers();sequence=[];round=0;lives=3;locked=true;tiles.forEach(t=>{t.classList.remove('lit','wrong')});roundOut.textContent='ROUND 0';livesOut.textContent='3';setStatus('WAITING FOR THE FIRST ROOM');});return()=>{disposed=true;clearTimers();};}

  // Sound and motion
  function listeningRoomMarkup(){return projectFrame('Sound & motion / 04','The Listening Room','Turn a generated signal into a moving structure. This instrument is self-contained and does not use microphone input or any external device.',`<div class="tool-canvas-wrap"><canvas class="tool-canvas" data-listening-canvas width="900" height="500" aria-label="Synthetic signal visualizer"></canvas></div><div class="tool-button-row">${action('Start signal','listening-start',true)}${action('Stop signal','listening-stop')}${action('New signal','listening-demo')}</div><p class="tool-small" data-listening-status>Ready. The display uses an internally generated signal.</p>`,panel('Response',range('Sensitivity','listening-sensitivity',1,100,55)+range('Smoothing','listening-smoothing',0,100,72)+select('Form','listening-form',[['ribbon','Ribbon'],['radial','Radial field'],['bars','Frequency bars'],['rings','Concentric rings']])),'All waveforms are generated inside this project. No microphone permission or external device is used.');}
  function bindListeningRoom(root){const canvas=$('[data-listening-canvas]',root);let demo=true,renderer=null,level=0,disposed=false;const analyser=null;const startButton=$('[data-action="listening-start"]',root);function paint(c,w,h,t){c.fillStyle='#11151b';c.fillRect(0,0,w,h);const form=$('[data-select="listening-form"]',root).value,sensitivity=+$('[data-range="listening-sensitivity"]',root).value/55,smooth=+$('[data-range="listening-smoothing"]',root).value/100;let data=new Uint8Array(analyser?analyser.fftSize:512);if(analyser){analyser.getByteTimeDomainData(data);let total=0;for(const v of data)total+=Math.abs(v-128);level=level*(smooth*.92)+(total/data.length/128)*(1-smooth*.7);}else level=level*.96+.018+Math.sin(t*1.8)*.009;const amp=clamp(level*sensitivity,0,1);c.strokeStyle='#d6ff69';c.fillStyle='rgba(214,255,105,.14)';c.lineWidth=2;if(form==='bars'){const count=64;for(let i=0;i<count;i++){const v=analyser?Math.abs(data[Math.floor(i*data.length/count)]-128)/128:Math.abs(Math.sin(i*.42+t))*0.2;const bh=(12+v*amp*h*1.3);c.fillStyle=`rgba(214,255,105,${.15+v*.6})`;c.fillRect(i*w/count+2,h*.5-bh/2,w/count-4,bh);}}else if(form==='radial'){c.save();c.translate(w/2,h/2);for(let i=0;i<140;i++){const a=i/140*Math.PI*2,v=analyser?Math.abs(data[Math.floor(i*data.length/140)]-128)/128:Math.abs(Math.sin(i*.14+t))*.12,r=h*.13+v*amp*h*.55;c.beginPath();c.moveTo(Math.cos(a)*r,Math.sin(a)*r);c.lineTo(Math.cos(a)*(r+8+v*25),Math.sin(a)*(r+8+v*25));c.strokeStyle=`rgba(186,167,255,${.18+v*.6})`;c.stroke();}c.restore();}else if(form==='rings'){for(let i=0;i<8;i++){c.beginPath();c.ellipse(w/2,h/2,h*.12+i*h*.045,h*.12+i*h*.045*(.6+amp),Math.sin(t*.1+i)*.2,0,Math.PI*2);c.strokeStyle=`rgba(133,230,218,${.16+i*.06})`;c.lineWidth=1+i*.2;c.stroke();}}else{c.beginPath();for(let i=0;i<Math.max(2,data.length);i++){const x=i/(data.length-1)*w;const v=analyser?(data[i]-128)/128:Math.sin(i*.025+t*2)*.06;const y=h/2+v*amp*h*.95;i?c.lineTo(x,y):c.moveTo(x,y);}c.stroke();}c.fillStyle='#8c8995';c.font='10px monospace';c.fillText(demo?'SYNTHETIC SIGNAL / LOCAL':'INPUT / IDLE',18,24);c.fillStyle='#d6ff69';c.fillText(`LEVEL ${(amp*100).toFixed(0)}%`,w-115,24);}
    renderer=fitCanvas(canvas,paint,true);function start(){demo=true;level=.16;$('[data-listening-status]',root).textContent='Synthetic signal active. All sound is generated inside CURIOID.';renderer.redraw();}
    function stop(){demo=false;if(!disposed){$('[data-listening-status]',root).textContent='Signal stopped. No external input was used.';renderer.redraw();}}function useDemo(){demo=true;level=.08;$('[data-listening-status]',root).textContent='New synthetic signal generated locally.';renderer.redraw();}
    startButton.addEventListener('click',start);$('[data-action="listening-stop"]',root).addEventListener('click',stop);$('[data-action="listening-demo"]',root).addEventListener('click',useDemo);['listening-sensitivity','listening-smoothing'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',()=>renderer.redraw()));$('[data-select="listening-form"]',root).addEventListener('change',()=>renderer.redraw());return()=>{disposed=true;renderer.stop();};}

  function orbitChoirMarkup(){return projectFrame('Sound & motion / 05','Orbit Choir','Three voices travel around one centre without quite arriving together. Build a slow, shifting chord and let the visual orbit follow the tuning.',`<div class="tool-canvas-wrap"><canvas class="tool-canvas" data-orbitchoir-canvas width="900" height="500" aria-label="Three-voice orbit visualization"></canvas></div><div class="tool-button-row">${action('Start choir','orbitchoir-start',true)}${action('Silence','orbitchoir-stop')}${action('New arrangement','orbitchoir-new')}</div><p class="tool-small" data-orbitchoir-status>Silent arrangement. Start choir to hear it.</p>`,panel('Tuning',range('Root frequency','orbitchoir-root',55,220,110,' Hz')+range('Interval drift','orbitchoir-drift',0,100,48)+range('Orbit speed','orbitchoir-speed',1,100,32)+range('Voice level','orbitchoir-volume',0,100,24,'%')+select('Voice texture','orbitchoir-wave',[['sine','Soft sine'],['triangle','Glass triangle'],['sawtooth','Bent reed'],['square','Digital pulse']])),'Audio begins only after Start choir. The site-wide master volume controls the final output; this setting balances the three voices.');}
  function bindOrbitChoir(root){const canvas=$('[data-orbitchoir-canvas]',root);let ctx=null,master=null,voices=[],playing=false,renderer=null,phase=0;function settings(){return{root:+$('[data-range="orbitchoir-root"]',root).value,drift:+$('[data-range="orbitchoir-drift"]',root).value/100,speed:+$('[data-range="orbitchoir-speed"]',root).value/100,volume:+$('[data-range="orbitchoir-volume"]',root).value/100,wave:$('[data-select="orbitchoir-wave"]',root).value};}function updateAudio(){if(!ctx)return;const p=settings(),ratios=[1,1.25+p.drift*.08,1.5+p.drift*.22];voices.forEach((v,i)=>{v.osc.type=p.wave;v.osc.frequency.setTargetAtTime(p.root*ratios[i],ctx.currentTime,.12);v.pan.pan.setTargetAtTime((i-1)*(.55+p.drift*.35),ctx.currentTime,.18);v.gain.gain.setTargetAtTime(p.volume*(i===0?.13:.085),ctx.currentTime,.15);});}
    function paint(c,w,h,t,dt){const p=settings();phase+=dt*p.speed*1.35;c.fillStyle='#11141d';c.fillRect(0,0,w,h);c.strokeStyle='rgba(186,167,255,.15)';c.lineWidth=1;for(let r=50;r<Math.min(w,h)*.48;r+=36){c.beginPath();c.ellipse(w/2,h/2,r,r*.7,0,0,Math.PI*2);c.stroke();}const colors=['#d6ff69','#baa7ff','#85e6da'];for(let i=0;i<3;i++){const a=phase*(i%2?-.78:1)+(i*2.094),rad=Math.min(w,h)*(.16+i*.1);const x=w/2+Math.cos(a)*rad,y=h/2+Math.sin(a)*rad*.7;c.beginPath();c.arc(x,y,12+i*4,0,Math.PI*2);c.fillStyle=colors[i];c.shadowColor=colors[i];c.shadowBlur=playing?18:5;c.fill();c.shadowBlur=0;c.beginPath();c.moveTo(w/2,h/2);c.lineTo(x,y);c.strokeStyle=colors[i]+'66';c.stroke();}c.fillStyle='#e8e4e0';c.textAlign='center';c.font='bold 18px system-ui';c.fillText(`${p.root} Hz`,w/2,h*.88);c.fillStyle='#8b8896';c.font='10px monospace';c.fillText(playing?'THREE VOICES / ACTIVE':'THREE VOICES / RESTING',w/2,h*.93);c.textAlign='left';}
    renderer=fitCanvas(canvas,paint,true);async function start(){const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx){toast(null,'Web Audio is not available in this browser.');return;}try{if(!ctx){ctx=new AudioCtx();master=ctx.createGain();master.gain.value=1;master.connect(ctx.destination);registerAudioMaster(master);voices=[0,1,2].map(i=>{const osc=ctx.createOscillator(),gain=ctx.createGain(),pan=ctx.createStereoPanner?ctx.createStereoPanner():{pan:{setTargetAtTime(){}},connect(){},};osc.type=i===1?'triangle':'sine';osc.frequency.value=110*(1+i*.25);gain.gain.value=0;osc.connect(gain);gain.connect(pan);pan.connect(master);osc.start();return{osc,gain,pan};});}await ctx.resume();playing=true;updateAudio();$('[data-orbitchoir-status]',root).textContent='Choir active. Three voices are circling.';renderer.redraw();}catch(error){toast(null,'The audio engine could not start.');}}
    function stop(){playing=false;voices.forEach(v=>v.gain.gain.setTargetAtTime(0,ctx?.currentTime||0,.08));$('[data-orbitchoir-status]',root).textContent='Silence. The arrangement is kept.';renderer?.redraw();}
    $('[data-action="orbitchoir-start"]',root).addEventListener('click',start);$('[data-action="orbitchoir-stop"]',root).addEventListener('click',stop);$('[data-action="orbitchoir-new"]',root).addEventListener('click',()=>{const a=$('[data-range="orbitchoir-root"]',root);a.value=String(Math.round(rand(68,180)));$('[data-range="orbitchoir-drift"]',root).value=String(Math.round(rand(22,96)));updateAudio();renderer.redraw();});['orbitchoir-root','orbitchoir-drift','orbitchoir-speed','orbitchoir-volume'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',()=>{updateAudio();renderer.redraw();}));$('[data-select="orbitchoir-wave"]',root).addEventListener('change',updateAudio);return()=>{stop();renderer.stop();voices.forEach(v=>{try{v.osc.stop();}catch(_){} });ctx?.close().catch(()=>{});ctx=null;voices=[];};}

  // Strange archives
  const missingMinuteRecords=[
    ['07:12','4 minutes','North stairwell','A visitor reached the landing before leaving the floor below.','The clock in the stairwell advanced normally. The visitor arrived with dust on both shoes, though the landing had not been used that morning.'],
    ['11:46','19 minutes','Public library / map desk','A folded map returned with a coastline that was not printed.','The missing interval was reported by a librarian who had been sorting maps of the same county for twenty-three years.'],
    ['16:03','2 minutes','Bus route 8','Every passenger remembered the bus stopping. The driver did not.','The ticket machine issued one ticket with a timestamp two minutes in the future.'],
    ['02:21','31 minutes','Apartment 4C','A kettle cooled before it was switched off.','The resident insists the tea was already poured. The kitchen clock has no battery compartment.'],
    ['09:09','8 minutes','Dental waiting room','The same magazine appeared open to the same page in two different visits.','The page contains an advertisement for a product discontinued before the magazine was printed.'],
    ['13:55','12 minutes','Greenhouse 2','A plant produced a shadow shaped like a window.','No window is present on the greenhouse wall. The shadow disappeared when the plant was moved.'],
    ['18:40','6 minutes','Railway platform','A train announcement described a station that was removed in 1987.','Several people wrote down the station name. Their spellings differ by one letter.'],
    ['05:17','43 seconds','Kitchen / west wall','A wall clock ticked once for each person asleep in the house.','The house was empty. The owner was staying elsewhere and heard the same ticking over the phone.'],
    ['12:30','15 minutes','Municipal pool','A swimmer reached the other end without crossing the water.','The lifeguard recorded a dry footprint at the bottom of the pool. The pool was full.'],
    ['20:06','9 minutes','Cinema 3','The closing credits began before the final scene.','The projectionist checked the reel. The final scene was still physically attached to the film.'],
    ['08:02','3 minutes','Corner shop','A customer paid with coins dated next year.','The coins were accepted, counted and returned as change. No coin with that date is currently in circulation.'],
    ['14:14','27 minutes','Archive basement','A filing cabinet was heard opening inside a sealed room.','The sound repeated every fourteen minutes until the room was opened. The cabinet was empty and cold.'],
    ['10:38','5 minutes','Hotel lift','The lift stopped between floors and opened onto a corridor with carpet.','The hotel has no carpeted corridors. The guest returned to the lift carrying a room key from another floor.'],
    ['23:01','11 minutes','Riverside path','A person saw their own bicycle travelling ahead without a rider.','The bicycle was later found locked at home. The person had walked to the river.'],
    ['06:44','1 minute','Bakery','The oven timer rang before the dough was mixed.','The baker followed the timer and found the loaf already cooling on the rack.'],
    ['15:22','22 minutes','School gym','A basketball bounced once after being placed in a locked cupboard.','The cupboard was inspected. The ball was still on the shelf, with a fresh mark on the floor beneath it.'],
    ['03:33','13 minutes','Night bus depot','A route map gained an extra stop named after the depot.','The stop was removed from the map the following morning. The timetable still includes it on Tuesdays.'],
    ['17:17','7 minutes','Garden shed','A radio announced tomorrow’s local weather in yesterday’s voice.','The forecast was accurate. The voice belonged to a person who had not yet joined the station.'],
    ['12:02','38 minutes','Public garden','A bench was warm in the rain and cold in direct sun.','The temperature difference remained after the bench was moved to a storage room.'],
    ['19:28','4 minutes','Laundry room','A washing machine finished a cycle that had not started.','The drum was dry. The clothes inside belonged to a resident who moved away years earlier.'],
    ['04:50','16 minutes','Apartment roof','A weather vane pointed toward the building.','It turned slowly whenever somebody on the top floor said their own name.'],
    ['21:11','10 minutes','Museum cloakroom','A coat was checked in and returned with a second sleeve.','The new sleeve has the correct museum label and the wrong owner’s initials.'],
    ['09:27','52 seconds','Crossing signal','The pedestrian light displayed a walking figure facing backwards.','The crossing completed normally. One pedestrian arrived on the opposite pavement with wet shoes.'],
    ['16:49','18 minutes','Office kitchenette','A cup was found full of tea that nobody remembered making.','The tea was still warm. The cup had been washed and put away before the interval began.']
  ];
  function missingMinutesMarkup(){return projectFrame('Strange archive / 04','The Office of Missing Minutes','A public records desk for time that appears to have gone missing. Search the case files, inspect the witness notes and claim a record for your own cabinet.',`<div class="minute-archive"><div class="minute-toolbar"><input type="search" data-minute-search placeholder="Search cases, places, details…" aria-label="Search missing minute records"><select data-minute-filter aria-label="Filter records"><option value="all">All records</option><option value="short">Under 5 minutes</option><option value="medium">5–15 minutes</option><option value="long">Over 15 minutes</option></select></div><div class="minute-list" data-minute-list></div></div>`,panel('Case file',`<div class="minute-detail" data-minute-detail><p class="tool-eyebrow">SELECT A RECORD</p><h4>Nothing has been opened yet.</h4><p class="tool-small">Choose a case from the register to inspect the witness statement.</p></div><div class="tool-button-row">${action('Claim this record','minute-claim',true)}${action('Open a random case','minute-random')}</div><p class="tool-small" data-minute-claimed>0 records in your personal cabinet.</p>`),'The case register is fictional. Claimed records are stored only in this browser.');}
  function bindMissingMinutes(root){const list=$('[data-minute-list]',root),detail=$('[data-minute-detail]',root),search=$('[data-minute-search]',root),filter=$('[data-minute-filter]',root);const records=missingMinuteRecords.map((r,i)=>({id:i+1,time:r[0],duration:r[1],place:r[2],subject:r[3],note:r[4]}));let selected=records[0];let claimed=[];try{claimed=JSON.parse(localStorage.getItem('curioid-missing-minutes')||'[]')}catch(_){}if(!Array.isArray(claimed))claimed=[];function durationClass(text){const value=String(text).toLowerCase();if(value.includes('second'))return 'short';const num=parseFloat(value);return num<5?'short':num<=15?'medium':'long';}function renderList(){const q=search.value.trim().toLowerCase(),f=filter.value;const found=records.filter(r=>(f==='all'||durationClass(r.duration)===f)&&[r.time,r.duration,r.place,r.subject,r.note].join(' ').toLowerCase().includes(q));list.innerHTML=found.map(r=>`<button type="button" class="minute-record${selected?.id===r.id?' selected':''}" data-minute-id="${r.id}" aria-pressed="${selected?.id===r.id}"><span class="minute-time">${esc(r.time)}</span><span class="minute-record-copy"><strong>${esc(r.place)}</strong><small>${esc(r.subject)}</small></span><span class="minute-duration">${esc(r.duration)}</span></button>`).join('')||'<p class="tool-small">No matching records. The empty result has been filed.</p>';}
    function renderDetail(){if(!selected)return;detail.innerHTML=`<p class="tool-eyebrow">CASE MM-${String(selected.id).padStart(4,'0')} / ${esc(selected.time)}</p><h4>${esc(selected.place)}</h4><p class="minute-subject">${esc(selected.subject)}</p><p>${esc(selected.note)}</p><div class="minute-stamp">${claimed.includes(selected.id)?'CLAIMED BY VISITOR':'UNCLAIMED / VERIFIED'}</div>`;$('[data-action="minute-claim"]',root).textContent=claimed.includes(selected.id)?'Return record':'Claim this record';$('[data-minute-claimed]',root).textContent=`${claimed.length} records in your personal cabinet.`;renderList();}
    list.addEventListener('click',e=>{const b=e.target.closest('[data-minute-id]');if(!b)return;selected=records.find(r=>r.id===Number(b.dataset.minuteId));renderDetail();});search.addEventListener('input',renderList);filter.addEventListener('change',renderList);$('[data-action="minute-claim"]',root).addEventListener('click',()=>{if(!selected)return;if(claimed.includes(selected.id))claimed=claimed.filter(id=>id!==selected.id);else claimed.push(selected.id);try{localStorage.setItem('curioid-missing-minutes',JSON.stringify(claimed))}catch(_){}renderDetail();});$('[data-action="minute-random"]',root).addEventListener('click',()=>{selected=pick(records);renderDetail();});renderDetail();return()=>{};}

  const doorRegistry=[
    ['A / 01','The Room With the Unused Light','A clean room with a single lamp. The bulb is warm, but no electricity reaches this wing.','A small envelope is on the sill. It contains a photograph of the room from outside.'],
    ['A / 02','The Staircase That Ends Upstairs','The stairs rise toward a ceiling. Somewhere above it, a door closes softly.','The handrail is polished only on the side facing the wall.'],
    ['A / 03','The Borrowed Kitchen','A kitchen arranged for a family whose names appear on no local register.','Four cups are set out. One is still warm.'],
    ['B / 01','The Waiting Room for Arrivals','There are six chairs and a number dispenser. The display is already showing your number.','A paper ticket rests under the chair. Its timestamp is tomorrow morning.'],
    ['B / 02','The Windowless Conservatory','Plants grow toward a source of light that is not present in the room.','A leaf carries a tiny printed address. It belongs to this building.'],
    ['B / 03','The Hall of Spare Doors','The walls are covered with doors of different sizes. Each one opens into the same hallway.','A maintenance note says the hallway is expected to be shorter next week.'],
    ['C / 01','The Dry Aquarium','A long glass tank holds a room instead of water. Something moves behind the furniture.','The filter is running. Its label says it removes memories from the water.'],
    ['C / 02','The Bedroom With Two Mornings','A pale window shows sunrise. A second sunrise is visible in the mirror.','The alarm clock is set for both. Only one alarm is plugged in.'],
    ['C / 03','The Records Room of Unwritten Names','Shelves contain folders with blank labels. One folder has your initials, but no name.','The newest entry is written in ink that has not dried yet.'],
    ['D / 01','The Lift That Skips One Floor','The panel has buttons for every floor except the one the lift announces.','The floor indicator briefly displays a small house.'],
    ['D / 02','The Quiet Boiler Room','The pipes are warm and make a sound like distant applause.','The pressure gauge is labelled with a date instead of a unit.'],
    ['D / 03','The Office of Returned Keys','Every key is tagged with a room number that does not exist.','A key on the desk is still turning, though it is not in a lock.'],
    ['E / 01','The Hallway Behind the Wallpaper','A narrow corridor is visible through a loose edge of wallpaper.','The wallpaper pattern continues along the corridor and onto its floor.'],
    ['E / 02','The Room That Is Already Empty','A moving crew has finished clearing a room before the building was constructed.','A single box remains. It is labelled with the building’s current address.'],
    ['E / 03','The Door With the Inside Handle','The handle is on the wrong side. Opening it reveals a familiar hallway.','A note asks the visitor to close the door from the other side.'],
    ['F / 01','The Weather Cupboard','A small cupboard contains a different kind of weather for each day of the week.','Today’s shelf is empty, but the room smells of wet pavement.'],
    ['F / 02','The Guest Room for Previous Tenants','The bed is made. The wardrobe contains a coat in your size.','The guest book contains a note thanking you for staying last year.'],
    ['F / 03','The Door That Opens Inward Twice','The first opening reveals a short hall. The second opening reveals the first door, from the other side.','The hinge has no screws and no visible pin.']
  ];
  function unreturnedDoorsMarkup(){return projectFrame('Strange archive / 05','The Registry of Unreturned Doors','A building directory that records rooms even when the building denies having them. Select a door, open the entry and inspect what the registry has kept.',`<div class="door-registry-grid" data-door-grid></div>`,panel('Selected door',`<div class="door-detail" data-door-detail><div class="door-visual" data-door-visual><span>?</span></div><p class="tool-eyebrow">NO DOOR SELECTED</p><h4>Choose a door from the registry.</h4><p class="tool-small">The registry keeps a record of every opening.</p></div><div class="tool-button-row">${action('Open selected door','door-open',true)}${action('Close door','door-close')}</div><p class="tool-small" data-door-visited>0 doors visited on this device.</p>`),'Visited doors are remembered locally. The descriptions are fictional; the registry is not connected to a real building.');}
  function bindUnreturnedDoors(root){const grid=$('[data-door-grid]',root),detail=$('[data-door-detail]',root),visual=$('[data-door-visual]',root);let visited=[],selected=0,opened=false;try{visited=JSON.parse(localStorage.getItem('curioid-unreturned-doors')||'[]')}catch(_){}if(!Array.isArray(visited))visited=[];function renderGrid(){grid.innerHTML=doorRegistry.map((d,i)=>`<button type="button" class="door-registry-card${selected===i?' selected':''}" data-door-index="${i}" aria-pressed="${selected===i}"><span class="registry-door${opened&&selected===i?' open':''}"><i></i></span><span><strong>${esc(d[1])}</strong><small>${esc(d[0])} · ${visited.includes(i)?'VISITED':'UNOPENED'}</small></span></button>`).join('');}
    function showDoor(){const d=doorRegistry[selected];detail.innerHTML=`<p class="tool-eyebrow">REGISTER ${esc(d[0])}</p><h4>${esc(d[1])}</h4><p>${esc(d[2])}</p><div class="door-note">${esc(d[3])}</div><div class="minute-stamp">${opened?'DOOR OPEN / ENTRY CONFIRMED':'DOOR CLOSED / ENTRY NOT CONFIRMED'}</div>`;visual.classList.toggle('is-open',opened);visual.querySelector('span').textContent=opened?'↗':'?';$('[data-door-visited]',root).textContent=`${visited.length} doors visited on this device.`;renderGrid();}
    grid.addEventListener('click',e=>{const b=e.target.closest('[data-door-index]');if(!b)return;selected=Number(b.dataset.doorIndex);opened=false;showDoor();});$('[data-action="door-open"]',root).addEventListener('click',()=>{if(!visited.includes(selected)){visited.push(selected);try{localStorage.setItem('curioid-unreturned-doors',JSON.stringify(visited))}catch(_){}}opened=true;showDoor();});$('[data-action="door-close"]',root).addEventListener('click',()=>{opened=false;showDoor();});showDoor();return()=>{};}


  // 41 - Rule Garden: a local cellular automaton with several rule families.
  function ruleGardenMarkup(){return projectFrame('Web experiment / 08','Rule Garden','A living grid governed by a few local rules. Change the rule, disturb the cells and watch patterns appear, die out or refuse to settle.',`<div class="tool-canvas-wrap"><canvas class="tool-canvas rule-garden-canvas" aria-label="Cellular automaton grid"></canvas><div class="canvas-overlay"><span>CLICK TO SEED CELLS</span><span data-rule-generation>GENERATION 0000</span></div></div><div class="tool-button-row">${action('Ⅱ Pause','rule-run',true)}${action('Step once','rule-step')}${action('Randomize','rule-random')}${action('Clear grid','rule-clear')}${action('Save PNG to Vault','rule-export')}</div>`,panel('Local rules',select('Rule family','rule-family',[['life','Conway / Life'],['brain','Excitable matter'],['maze','Growing maze'],['crystal','Crystal growth'],['strange','Unstable field']])+range('Population','rule-population',5,85,34,'%')+range('Speed','rule-speed',1,24,8,' steps/s')+range('Mutation','rule-mutation',0,100,24,'%')+select('Ink','rule-ink',[['acid','Signal green'],['mineral','Mineral'],['heat','Heat map'],['mono','Monochrome']])),'The grid runs entirely in your browser. Try painting a few cells into the field while it is running.');}
  function bindRuleGarden(root){
    const canvas=$('.rule-garden-canvas',root),cols=72,rows=42;let cells=new Uint8Array(cols*rows),next=new Uint8Array(cols*rows),generation=0,running=true,acc=0,renderer=null;
    const family=()=> $('[data-select="rule-family"]',root).value;
    const ix=(x,y)=>y*cols+x;
    function randomize(){const density=+$('[data-range="rule-population"]',root).value/100;for(let i=0;i<cells.length;i++)cells[i]=Math.random()<density?1:0;generation=0;updateLabel();renderer?.redraw();}
    function clear(){cells.fill(0);generation=0;updateLabel();renderer?.redraw();}
    function step(){const mode=family(),mutation=+$('[data-range="rule-mutation"]',root).value/100;for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){let n=0,active=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dy)continue;const xx=(x+dx+cols)%cols,yy=(y+dy+rows)%rows,v=cells[ix(xx,yy)];if(v===1)n++;if(v===2)active++;}const i=ix(x,y),v=cells[i];let out=0;if(mode==='life')out=v===1?(n===2||n===3?1:0):(n===3?1:0);else if(mode==='brain')out=v===1?2:v===2?0:(n===2?1:0);else if(mode==='maze')out=v===1?(n>=1&&n<=5?1:0):(n===3||n===4||n===5?1:0);else if(mode==='crystal')out=v===1?(n>=1&&n<=4?1:0):(n===2||n===3||n===6?1:0);else out=v===1?(n===2||n===3||n===4?1:0):(n===2||n===3||n===5?1:0);if(mutation&&Math.random()<mutation*.006)out=out?0:1;next[i]=out;}const tmp=cells;cells=next;next=tmp;generation++;updateLabel();}
    function updateLabel(){const el=$('[data-rule-generation]',root);if(el)el.textContent='GENERATION '+String(generation).padStart(4,'0');}
    function paint(ctx,w,h,t,dt,initial){if(running&&!initial){acc+=dt;const stepEvery=1/(+$('[data-range="rule-speed"]',root).value);let guard=0;while(acc>=stepEvery&&guard++<5){step();acc-=stepEvery;}}ctx.fillStyle='#10131a';ctx.fillRect(0,0,w,h);const cw=w/cols,ch=h/rows,mode=family(),ink=$('[data-select="rule-ink"]',root).value;for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const v=cells[ix(x,y)];if(!v)continue;let color;if(ink==='mono')color=v===1?'#e9e6df':'#777481';else if(ink==='heat')color=v===1?`hsl(${115-generation%100},88%,${48+((x+y)%5)*5}%)`:'#ff9cba';else if(ink==='mineral')color=v===1?['#d6ff69','#baa7ff','#85e6da','#f0d7a8'][(x*7+y*3+generation)%4]:'#ff9cba';else color=v===1?'#d6ff69':mode==='brain'?'#baa7ff':'#85e6da';ctx.globalAlpha=v===1?.9:.55;ctx.fillStyle=color;ctx.fillRect(x*cw+1,y*ch+1,Math.max(1,cw-2),Math.max(1,ch-2));}ctx.globalAlpha=1;ctx.strokeStyle='rgba(255,255,255,.035)';ctx.lineWidth=1;for(let x=0;x<=cols;x+=6){ctx.beginPath();ctx.moveTo(x*cw,0);ctx.lineTo(x*cw,h);ctx.stroke();}}
    renderer=fitCanvas(canvas,paint,true);function setRun(on){running=on;const button=$('[data-action="rule-run"]',root);if(button)button.textContent=on?'Ⅱ Pause':'▶ Run';}
    $('[data-action="rule-run"]',root).addEventListener('click',()=>setRun(!running));$('[data-action="rule-step"]',root).addEventListener('click',()=>{setRun(false);step();renderer.redraw();});$('[data-action="rule-random"]',root).addEventListener('click',randomize);$('[data-action="rule-clear"]',root).addEventListener('click',()=>{setRun(false);clear();});$('[data-action="rule-export"]',root).addEventListener('click',()=>saveCanvas(canvas,'curioid-rule-garden.png'));['rule-family','rule-ink'].forEach(k=>$(`[data-select="${k}"]`,root).addEventListener('change',()=>renderer.redraw()));['rule-population','rule-mutation'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',()=>{if(k==='rule-population')randomize();else renderer.redraw();}));
    let painting=false;function paintCell(e){const r=canvas.getBoundingClientRect(),x=clamp(Math.floor((e.clientX-r.left)/r.width*cols),0,cols-1),y=clamp(Math.floor((e.clientY-r.top)/r.height*rows),0,rows-1);cells[ix(x,y)]=1;renderer.redraw();}canvas.addEventListener('pointerdown',e=>{painting=true;canvas.setPointerCapture(e.pointerId);paintCell(e);});canvas.addEventListener('pointermove',e=>{if(painting&&e.buttons)paintCell(e);});canvas.addEventListener('pointerup',()=>painting=false);canvas.addEventListener('pointercancel',()=>painting=false);randomize();setRun(true);
    return()=>{running=false;renderer.stop();};
  }

  // 42 - Pendulum Choir: phase drift visualized as a field of moving pendulums.
  function pendulumChoirMarkup(){return projectFrame('Web experiment / 09','Pendulum Choir','A row of pendulums starts together, then quietly loses agreement. Change the coupling and listen to the shape of the movement with your eyes.',`<div class="tool-canvas-wrap"><canvas class="tool-canvas pendulum-choir-canvas" aria-label="Animated pendulum field"></canvas><div class="canvas-overlay"><span>PHASE / FIELD STUDY</span><span data-pendulum-status>IN AGREEMENT</span></div></div><div class="tool-button-row">${action('Pause field','pendulum-pause',true)}${action('Reset phase','pendulum-reset')}${action('Export trace','pendulum-export')}</div>`,panel('Oscillation',range('Pendulum count','pendulum-count',5,36,19)+range('Tempo','pendulum-tempo',10,100,48,'%')+range('Divergence','pendulum-drift',0,100,64,'%')+range('Coupling','pendulum-coupling',0,100,17,'%')+range('Trail length','pendulum-trail',0,100,62,'%')+select('Trace color','pendulum-color',[['mineral','Mineral'],['signal','Signal'],['violet','Violet dusk'],['mono','Monochrome']])),'The motion is deterministic for each reset but small differences accumulate. Watch the whole row rather than one pendulum.');}
  function bindPendulumChoir(root){const canvas=$('.pendulum-choir-canvas',root);let paused=false,elapsedBeforePause=0,startTime=performance.now()/1000,renderer;const trails=Array.from({length:40},()=>[]);function paint(ctx,w,h,t,dt,initial){ctx.fillStyle='#10131a';ctx.fillRect(0,0,w,h);const count=+$('[data-range="pendulum-count"]',root).value,speed=+$('[data-range="pendulum-tempo"]',root).value/100,drift=+$('[data-range="pendulum-drift"]',root).value/100,coupling=+$('[data-range="pendulum-coupling"]',root).value/100,trail=+$('[data-range="pendulum-trail"]',root).value/100,col=$('[data-select="pendulum-color"]',root).value,colors=col==='signal'?['#d6ff69','#ff9cba','#65d4ff']:col==='violet'?['#baa7ff','#9f8dc7','#e6b8d7']:col==='mono'?['#e8e6df']:['#d6ff69','#baa7ff','#85e6da','#f0d7a8'];const elapsed=elapsedBeforePause+(paused?0:t-startTime),spacing=w/(count+1),length=Math.min(h*.67,180);ctx.strokeStyle='rgba(255,255,255,.1)';ctx.beginPath();ctx.moveTo(0,30);ctx.lineTo(w,30);ctx.stroke();for(let i=0;i<count;i++){const base=i*.29,phaseDrift=Math.sin(i*1.37)*drift*1.4,angle=Math.sin(elapsed*(.55+speed*2.8)+base+phaseDrift+Math.sin(elapsed*.21+i*.17)*coupling)*(.22+drift*.58),x=(i+1)*spacing,y=42,bx=x+Math.sin(angle)*length,by=y+Math.cos(angle)*length;const list=trails[i];if(!paused&&trail>0){list.push([bx,by]);if(list.length>Math.round(8+trail*1.5))list.shift();}else if(!trail)list.length=0;if(list.length>1){ctx.beginPath();list.forEach((p,j)=>j?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.strokeStyle=colors[i%colors.length]+'88';ctx.lineWidth=1.4;ctx.stroke();}ctx.strokeStyle='#8e8a9a';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(bx,by);ctx.stroke();ctx.fillStyle='#d6ff69';ctx.beginPath();ctx.arc(x,y,2.2,0,Math.PI*2);ctx.fill();ctx.fillStyle=colors[i%colors.length];ctx.beginPath();ctx.arc(bx,by,Math.max(3,5+(i%4)),0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ffffff88';ctx.stroke();}const status=$('[data-pendulum-status]',root);if(status)status.textContent=paused?'FIELD HELD':drift>0.7?'PHASES DISAGREE':'IN AGREEMENT';}
    renderer=fitCanvas(canvas,paint,true);$('[data-action="pendulum-pause"]',root).addEventListener('click',e=>{const now=performance.now()/1000;if(!paused)elapsedBeforePause+=now-startTime;else startTime=now;paused=!paused;e.currentTarget.textContent=paused?'Resume field':'Pause field';renderer.redraw();});$('[data-action="pendulum-reset"]',root).addEventListener('click',()=>{elapsedBeforePause=0;startTime=performance.now()/1000;trails.forEach(a=>a.length=0);renderer.redraw();});$('[data-action="pendulum-export"]',root).addEventListener('click',()=>saveCanvas(canvas,'curioid-pendulum-choir.png'));['pendulum-count','pendulum-tempo','pendulum-drift','pendulum-coupling','pendulum-trail'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',()=>renderer.redraw()));$('[data-select="pendulum-color"]',root).addEventListener('change',()=>renderer.redraw());return()=>renderer.stop();}

  // 43 - Strata Loom: procedural layered weave and geological fiber materials.
  function strataLoomMarkup(){return projectFrame('Digital art / 06','Strata Loom','Weave a surface from threads, bands, knots and imperfect tension. The clean pattern is only the beginning; let the material slip.',`<div class="tool-canvas-wrap art-canvas-wrap"><canvas class="tool-canvas strata-loom-canvas" aria-label="Generated woven material"></canvas></div><div class="tool-button-row">${action('New weave','strata-new',true)}${action('Misalign it','strata-extreme')}${action('Export tile','strata-export')}</div><p class="tool-small" data-strata-seed>WEAVE / 000001</p>`,panel('Material',select('Thread character','strata-material',[['silk','Silk and wire'],['mineral','Mineral fibers'],['organic','Rooted fibers'],['industrial','Industrial braid'],['soft','Soft textile']])+select('Palette','strata-palette',[['mineral','Mineral'],['bruise','Bruised velvet'],['dusk','Last light'],['signal','Signal'],['sterile','Pale laboratory']])+range('Warp density','strata-warp',12,90,42)+range('Weft density','strata-weft',8,70,29)+range('Slippage','strata-slip',0,100,32,'%')+range('Knots','strata-knots',0,100,24,'%')+range('Material age','strata-age',0,100,46,'%')),'Generate seamless-looking surface studies for artwork, backgrounds or game materials.');}
  function bindStrataLoom(root){const canvas=$('.strata-loom-canvas',root);let seed=47;function paint(ctx,w,h){const pal=palettes[$('[data-select="strata-palette"]',root).value]||palettes.mineral,material=$('[data-select="strata-material"]',root).value,warp=+$('[data-range="strata-warp"]',root).value,weft=+$('[data-range="strata-weft"]',root).value,slip=+$('[data-range="strata-slip"]',root).value/100,knots=+$('[data-range="strata-knots"]',root).value/100,age=+$('[data-range="strata-age"]',root).value/100;let s=seed;const rnd=()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};ctx.fillStyle='#11131a';ctx.fillRect(0,0,w,h);const bg=ctx.createLinearGradient(0,0,w,h);bg.addColorStop(0,pal[0]);bg.addColorStop(1,pal[1]);ctx.globalAlpha=.26;ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);ctx.globalAlpha=1;const sx=w/warp,sy=h/weft;for(let y=0;y<weft;y++){for(let x=0;x<warp;x++){const offset=(rnd()-.5)*slip*sx*.95,fold=Math.sin(x*.23+y*.14+seed)*slip*sy*.8,ci=(x*3+y*5+Math.floor(rnd()*pal.length))%pal.length,c=pal[ci],xx=x*sx+offset,yy=y*sy+fold;ctx.fillStyle=c;ctx.globalAlpha=.42+rnd()*.5;ctx.fillRect(xx,yy,sx*1.06,sy*.58);ctx.fillStyle=material==='industrial'?'#e4e2d9':material==='mineral'?'#f4e7cb':'#08090d';ctx.globalAlpha=.13+age*.18;ctx.fillRect(xx,yy+sy*.56,sx*1.06,Math.max(1,sy*.11));if(rnd()<knots*.18){ctx.fillStyle=pal[(ci+2)%pal.length];ctx.globalAlpha=.95;ctx.beginPath();ctx.ellipse(xx+sx*.5,yy+sy*.3,sx*.28,sy*.19,rnd()*3,0,Math.PI*2);ctx.fill();}}}ctx.globalAlpha=1;const lines=Math.round(weft*knots*.32);for(let i=0;i<lines;i++){let y=rnd()*h;ctx.beginPath();ctx.moveTo(0,y);ctx.bezierCurveTo(w*.2,y+(rnd()-.5)*h*.1,w*.6,y+(rnd()-.5)*h*.15,w,y+(rnd()-.5)*h*.2);ctx.strokeStyle=pal[i%pal.length];ctx.globalAlpha=.3;ctx.lineWidth=1+rnd()*4;ctx.stroke();}ctx.globalAlpha=1;ctx.fillStyle=`rgba(7,8,13,${age*.2})`;ctx.fillRect(0,0,w,h);}
    const renderer=fitCanvas(canvas,paint,false);function redraw(){renderer.redraw();}$('[data-action="strata-new"]',root).addEventListener('click',()=>{seed=Math.floor(rand(1,999999));$('[data-strata-seed]',root).textContent='WEAVE / '+String(seed).padStart(6,'0');redraw();});$('[data-action="strata-extreme"]',root).addEventListener('click',()=>{seed=Math.floor(rand(1,999999));$('[data-range="strata-slip"]',root).value=100;$('[data-range="strata-knots"]',root).value=100;$('[data-range="strata-age"]',root).value=88;$('[data-select="strata-material"]',root).value=pick(['industrial','mineral','organic']);redraw();});['strata-warp','strata-weft','strata-slip','strata-knots','strata-age'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',redraw));['strata-material','strata-palette'].forEach(k=>$(`[data-select="${k}"]`,root).addEventListener('change',redraw));$('[data-action="strata-export"]',root).addEventListener('click',()=>saveCanvas(canvas,'curioid-strata-loom.png'));redraw();return()=>renderer.stop();}

  // 44 - Negative Space Department: poster art built by subtracting shapes.
  function negativeSpaceMarkup(){return projectFrame('Digital art / 07','Negative Space Department','Build an image from what is missing. Cut windows, tunnels and silhouettes out of a dense field, then decide which side is the figure.',`<div class="tool-canvas-wrap art-canvas-wrap"><canvas class="tool-canvas negative-space-canvas" aria-label="Negative space composition"></canvas></div><div class="tool-button-row">${action('New arrangement','negative-new',true)}${action('Invert field','negative-invert')}${action('Save PNG to Vault','negative-export')}</div><p class="tool-small" data-negative-seed>ABSENCE STUDY / 001</p>`,panel('Cutting rules',select('Cutout language','negative-shape',[['arch','Arches'],['eyes','Eye windows'],['stairs','Stair cuts'],['organic','Organic cavities'],['letters','Letter-like voids'],['fracture','Fractures']])+select('Material','negative-material',[['paper','Black paper'],['mineral','Mineral slab'],['signal','Signal paint'],['velvet','Velvet']])+range('Number of voids','negative-count',2,42,15)+range('Distortion','negative-distortion',0,100,58,'%')+range('Depth layers','negative-depth',1,12,6)+range('Edge wear','negative-wear',0,100,24,'%')),'The composition is drawn as a layered cut-paper study. Export the exact arrangement as a PNG.');}
  function bindNegativeSpace(root){const canvas=$('.negative-space-canvas',root);let seed=91,inverted=false;function paint(ctx,w,h){let s=seed;const rnd=()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};const count=+$('[data-range="negative-count"]',root).value,dist=+$('[data-range="negative-distortion"]',root).value/100,depth=+$('[data-range="negative-depth"]',root).value,wear=+$('[data-range="negative-wear"]',root).value/100,shape=$('[data-select="negative-shape"]',root).value,mat=$('[data-select="negative-material"]',root).value;const bg=mat==='paper'?'#e9e4d9':mat==='mineral'?'#b8a9bd':mat==='signal'?'#d6ff69':'#4d394c',ink=mat==='paper'?'#17171e':mat==='mineral'?'#353344':mat==='signal'?'#17171e':'#d5b2c4';ctx.fillStyle=inverted?ink:'#10131a';ctx.fillRect(0,0,w,h);ctx.fillStyle=inverted?bg:ink;ctx.fillRect(w*.04,h*.05,w*.92,h*.9);ctx.save();ctx.globalCompositeOperation='destination-out';for(let i=0;i<count;i++){const x=w*(.08+rnd()*.84),y=h*(.08+rnd()*.84),size=Math.min(w,h)*(.025+rnd()*.14)*(1+dist*.8),rot=rnd()*Math.PI*2;ctx.save();ctx.translate(x,y);ctx.rotate(rot);if(shape==='arch'){ctx.beginPath();ctx.roundRect(-size*.55,-size*.75,size*1.1,size*1.5,size*.55);ctx.fill();ctx.fillStyle='#10131a';ctx.fillRect(-size*.32,size*.2,size*.64,size*.62);}else if(shape==='eyes'){ctx.beginPath();ctx.ellipse(0,0,size,size*.34,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(0,0,size*.16,0,Math.PI*2);ctx.fill();}else if(shape==='stairs'){ctx.beginPath();ctx.moveTo(-size,-size);ctx.lineTo(size,-size);ctx.lineTo(size,0);ctx.lineTo(size*.35,0);ctx.lineTo(size*.35,size*.45);ctx.lineTo(-size*.3,size*.45);ctx.lineTo(-size*.3,size);ctx.lineTo(-size,size);ctx.closePath();ctx.fill();}else if(shape==='letters'){ctx.font=`bold ${size*1.6}px Georgia`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(pick(['O','A','R','M','E']),0,0);}else if(shape==='fracture'){ctx.beginPath();ctx.moveTo(-size,-size*.4);for(let k=0;k<7;k++)ctx.lineTo(-size+2*size*rnd(),-size+2*size*rnd());ctx.closePath();ctx.fill();}else{ctx.beginPath();ctx.moveTo(0,-size);for(let k=0;k<9;k++){const a=k*Math.PI*2/9,r=size*(.35+rnd()*.8);ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r);}ctx.closePath();ctx.fill();}ctx.restore();}ctx.restore();ctx.fillStyle=ink;ctx.globalAlpha=.08+wear*.2;for(let i=0;i<depth*7;i++){ctx.fillRect(rnd()*w,rnd()*h,1+rnd()*8,1+rnd()*3);}ctx.globalAlpha=1;ctx.strokeStyle=bg;ctx.lineWidth=Math.max(2,wear*8);ctx.strokeRect(10,10,w-20,h-20);}
    const renderer=fitCanvas(canvas,paint,false);function redraw(){renderer.redraw();}$('[data-action="negative-new"]',root).addEventListener('click',()=>{seed=Math.floor(rand(1,999999));$('[data-negative-seed]',root).textContent='ABSENCE STUDY / '+String(seed).padStart(6,'0');redraw();});$('[data-action="negative-invert"]',root).addEventListener('click',()=>{inverted=!inverted;redraw();});$('[data-action="negative-export"]',root).addEventListener('click',()=>saveCanvas(canvas,'curioid-negative-space.png'));['negative-count','negative-distortion','negative-depth','negative-wear'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',redraw));['negative-shape','negative-material'].forEach(k=>$(`[data-select="${k}"]`,root).addEventListener('change',redraw));redraw();return()=>renderer.stop();}

  // 45 - Unreliable Lift: a timed floor-routing game with a shifting building.
  function unreliableLiftMarkup(){return projectFrame('Tiny game / 06','Unreliable Lift','A small lift serves thirteen floors. The building is mostly ordinary, except the floor display occasionally remembers a different arrangement.',`<div class="lift-board"><div class="lift-screen"><span>CAR / 01</span><strong data-lift-current>00</strong><small data-lift-state>WAITING</small></div><div class="lift-mission"><span>PASSENGER REQUEST</span><strong data-lift-request>-</strong><small data-lift-message>Start the shift to receive a call.</small></div><div class="lift-stats"><span>DELIVERED <b data-lift-score>0</b></span><span>TIME <b data-lift-time>90</b></span></div><div class="lift-floor-grid" data-lift-floors></div></div><div class="tool-button-row">${action('Start shift','lift-start',true)}${action('Reset shift','lift-reset')}${action('Open / close doors','lift-doors')}</div>`,panel('Building notes',select('Shift length','lift-duration',[['60','One minute'],['90','Ninety seconds'],['150','Extended shift']])+select('Building behaviour','lift-behaviour',[['normal','Mostly normal'],['drift','Floor drift'],['unhelpful','Unhelpful signage']])+`<p class="tool-small">Go to the requested pickup floor first. When the passenger boards, choose their destination. The doors only open when the lift is stopped.</p>`),'A small route-management game. Passenger requests are generated locally and each completed delivery increases your score.');}
  function bindUnreliableLift(root){const floors=$('[data-lift-floors]',root),currentOut=$('[data-lift-current]',root),stateOut=$('[data-lift-state]',root),requestOut=$('[data-lift-request]',root),message=$('[data-lift-message]',root),scoreOut=$('[data-lift-score]',root),timeOut=$('[data-lift-time]',root);let current=0,score=0,time=90,request=null,onboard=false,running=false,moving=false,moveTimer=0,clockTimer=0,arrivalTimer=0;const floorNames=['BASEMENT','LOBBY','ARCHIVE','OFFICE','STORAGE','CLINIC','CAFETERIA','ROOF','OBSERVATORY','QUIET FLOOR','SEALED FLOOR','RETURN FLOOR','UNKNOWN'];function newRequest(){let from=Math.floor(Math.random()*13),to=Math.floor(Math.random()*12);if(to>=from)to++;request={from,to};onboard=false;requestOut.textContent=`${String(from).padStart(2,'0')}  →  ${String(to).padStart(2,'0')}`;message.textContent=`Someone is waiting at ${floorNames[from]}.`;}
    function render(){currentOut.textContent=String(current).padStart(2,'0');scoreOut.textContent=score;timeOut.textContent=time;stateOut.textContent=moving?'IN TRANSIT':onboard?'PASSENGER ON BOARD':running?'READY':'WAITING';$$('[data-floor]',floors).forEach(b=>{b.classList.toggle('current',+b.dataset.floor===current);b.disabled=!running||moving;});}
    function arrive(){moving=false;if(!request){render();return;}if(!onboard&&current===request.from){onboard=true;message.textContent=`Passenger aboard. Destination: ${floorNames[request.to]}.`;requestOut.textContent=`DESTINATION ${String(request.to).padStart(2,'0')}`;}else if(onboard&&current===request.to){score++;message.textContent=pick(['Delivered. The passenger left without looking back.','Trip complete. The floor indicator pauses for a moment.','Passenger delivered. Another request is waiting.']);newRequest();}else{message.textContent=`The doors open onto ${floorNames[current]}. Nobody is waiting.`;}render();}
    function go(f){if(!running||moving||f===current)return;const target=f;moving=true;render();let steps=0;moveTimer=setInterval(()=>{current+=Math.sign(target-current);steps++;render();if(current===target){clearInterval(moveTimer);moveTimer=0;clearTimeout(arrivalTimer);arrivalTimer=setTimeout(arrive,260);}},180);}
    floors.innerHTML=Array.from({length:13},(_,i)=>`<button type="button" data-floor="${12-i}" aria-label="Go to floor ${12-i}">${String(12-i).padStart(2,'0')}</button>`).join('');floors.addEventListener('click',e=>{const b=e.target.closest('[data-floor]');if(b)go(+b.dataset.floor);});
    function start(){clearInterval(clockTimer);clearInterval(moveTimer);current=0;score=0;time=+$('[data-select="lift-duration"]',root).value;running=true;moving=false;newRequest();message.textContent='Shift started. Collect the waiting passenger.';render();clockTimer=setInterval(()=>{if(!running)return;time--;render();if(time<=0){running=false;clearInterval(clockTimer);message.textContent=`Shift ended. ${score} passenger${score===1?'':'s'} delivered.`;stateOut.textContent='SHIFT COMPLETE';render();}},1000);}
    $('[data-action="lift-start"]',root).addEventListener('click',start);$('[data-action="lift-reset"]',root).addEventListener('click',()=>{running=false;clearInterval(clockTimer);clearInterval(moveTimer);clearTimeout(arrivalTimer);current=0;score=0;time=90;request=null;onboard=false;moving=false;message.textContent='The shift has been reset.';requestOut.textContent='-';render();});$('[data-action="lift-doors"]',root).addEventListener('click',()=>{if(!running||moving)return;if(request&&!onboard&&current===request.from){onboard=true;message.textContent=`Passenger aboard. Destination: ${floorNames[request.to]}.`;requestOut.textContent=`DESTINATION ${String(request.to).padStart(2,'0')}`;}else if(request&&onboard&&current===request.to){score++;newRequest();}else message.textContent='The doors open. The car is empty.';render();});$('[data-select="lift-duration"]',root).addEventListener('change',()=>{if(!running)time=+$('[data-select="lift-duration"]',root).value;render();});render();return()=>{clearInterval(clockTimer);clearInterval(moveTimer);clearTimeout(arrivalTimer);};}

  // 46 - Moth Census: a timed observational game with moving silhouettes and decoys.
  function mothCensusMarkup(){return projectFrame('Tiny game / 07','Moth Census','Count the visitors around a lamp. Some are moths. Some are folded scraps of something that learned the shape from a distance.',`<div class="tool-canvas-wrap"><canvas class="tool-canvas moth-census-canvas" aria-label="Moving moths and decoys"></canvas><div class="canvas-overlay"><span data-moth-status>THE LAMP IS WARM</span><span>SIGNAL / NIGHT 01</span></div></div><div class="moth-stats"><span>COUNTED <b data-moth-score>0</b></span><span>FALSE COUNTS <b data-moth-misses>0</b></span><span>TIME <b data-moth-time>30</b></span></div><div class="tool-button-row">${action('Begin census','moth-start',true)}${action('Reset','moth-reset')}${action('Show decoys','moth-hint')}</div>`,panel('Observation settings',select('Night conditions','moth-night',[['calm','Calm'],['wind','Side wind'],['wrong','Unusual migration']])+range('Population','moth-population',8,36,22)+range('Movement','moth-movement',10,100,62,'%')+`<p class="tool-small">Click the winged visitors. Avoid the decoys. The lamp changes its brightness near the end of the census.</p>`),'A short local observation game. Your best count is saved in this browser.');}
  function bindMothCensus(root){const canvas=$('.moth-census-canvas',root),ctx=canvas.getContext('2d');let moths=[],running=false,score=0,misses=0,time=30,last=0,renderer=null,showDecoys=false,best=0;try{best=Number(localStorage.getItem('curioid-moth-census-best')||0)}catch(_){}const scoreOut=$('[data-moth-score]',root),missOut=$('[data-moth-misses]',root),timeOut=$('[data-moth-time]',root),status=$('[data-moth-status]',root);function reset(){const pop=+$('[data-range="moth-population"]',root).value;moths=Array.from({length:pop+Math.round(pop*.45)},(_,i)=>({x:rand(.08,.92),y:rand(.12,.88),vx:rand(-.12,.12),vy:rand(-.12,.12),size:rand(5,12),phase:rand(0,6.28),moth:i<pop,hit:false}));score=0;misses=0;time=30;running=false;last=0;update();renderer?.redraw();}
    function update(){scoreOut.textContent=score;missOut.textContent=misses;timeOut.textContent=Math.max(0,Math.ceil(time));}
    function paint(c,w,h,t,dt,initial){c.fillStyle='#10141d';c.fillRect(0,0,w,h);const g=c.createRadialGradient(w*.5,h*.42,3,w*.5,h*.42,Math.min(w,h)*.46);g.addColorStop(0,'rgba(255,224,158,.24)');g.addColorStop(1,'rgba(255,224,158,0)');c.fillStyle=g;c.fillRect(0,0,w,h);c.fillStyle='#ecd9ad';c.beginPath();c.arc(w*.5,h*.42,13,0,Math.PI*2);c.fill();c.fillStyle='#b89a70';c.fillRect(w*.5-3,h*.42+12,6,h*.16);if(running&&!initial){time-=dt;if(time<=0){time=0;running=false;status.textContent='CENSUS CLOSED';if(score>best){best=score;try{localStorage.setItem('curioid-moth-census-best',String(best))}catch(_){}}}update();}const move=+$('[data-range="moth-movement"]',root).value/100,night=$('[data-select="moth-night"]',root).value; moths.forEach((m,i)=>{if(running&&!m.hit){m.x+=m.vx*dt*move;m.y+=m.vy*dt*move;const wind=night==='wind'?.08:night==='wrong'?.15:0;m.vx+=Math.sin(t*.7+m.phase)*dt*.025+wind*dt*.02;m.vy+=Math.cos(t*.55+m.phase)*dt*.02;if(m.x<.04||m.x>.96)m.vx*=-1;if(m.y<.08||m.y>.94)m.vy*=-1;m.x=clamp(m.x,.04,.96);m.y=clamp(m.y,.08,.94);}const x=m.x*w,y=m.y*h,a=Math.sin(t*2+m.phase)*.5,sz=m.size; c.save();c.translate(x,y);c.rotate(a);if(m.moth){c.fillStyle=m.hit?'#6c6870':'#d6c6a7';c.beginPath();c.ellipse(-sz*.55,0,sz*.72,sz*.42,-.5,0,Math.PI*2);c.ellipse(sz*.55,0,sz*.72,sz*.42,.5,0,Math.PI*2);c.fill();c.strokeStyle='#e9ddc7';c.lineWidth=1;c.beginPath();c.moveTo(0,-2);c.lineTo(0,sz*.7);c.stroke();}else{c.fillStyle=showDecoys?'#ff9cba':'#6f7781';c.beginPath();c.moveTo(0,-sz);c.lineTo(sz*.85,sz*.4);c.lineTo(-sz*.8,sz*.3);c.closePath();c.fill();}c.restore();});if(time<8&&running){c.fillStyle=`rgba(255,156,186,${.08+Math.sin(t*4)*.04})`;c.fillRect(0,0,w,h);}}
    renderer=fitCanvas(canvas,paint,true);canvas.addEventListener('click',e=>{if(!running)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;let nearest=null,dmin=.04;for(const m of moths){if(m.hit)continue;const d=Math.hypot(m.x-x,m.y-y);if(d<dmin){dmin=d;nearest=m;}}if(nearest){nearest.hit=true;if(nearest.moth)score++;else misses++;}else misses++;update();renderer.redraw();});$('[data-action="moth-start"]',root).addEventListener('click',()=>{reset();running=true;status.textContent='COUNT THE VISITORS';});$('[data-action="moth-reset"]',root).addEventListener('click',reset);$('[data-action="moth-hint"]',root).addEventListener('click',()=>{showDecoys=!showDecoys;status.textContent=showDecoys?'DECOYS HIGHLIGHTED':'THE LAMP IS WARM';renderer.redraw();});$('[data-range="moth-population"]',root).addEventListener('change',reset);reset();return()=>renderer.stop();}

  // 47 - Tide Signal: an original ambient instrument, started only by a visitor gesture.
  function tideSignalMarkup(){return projectFrame('Sound & motion / 06','Tide Signal','A small radio tuned to a tide that is not on any chart. Shape the signal, let it drift, and listen for the part that almost repeats.',`<div class="tool-canvas-wrap"><canvas class="tool-canvas tide-signal-canvas" aria-label="Tide signal waveform"></canvas><div class="canvas-overlay"><span data-tide-status>FREQUENCY UNCLAIMED</span><span>LOCAL SYNTHESIS</span></div></div><div class="tool-button-row">${action('▶ Start signal','tide-start',true)}${action('■ Stop signal','tide-stop')}${action('Random tuning','tide-random')}</div>`,panel('Receiver',select('Wave character','tide-wave',[['sine','Soft sine'],['triangle','Distant triangle'],['sawtooth','Rusted saw'],['square','Square pulse']])+range('Root frequency','tide-root',35,220,72,' Hz')+range('Drift','tide-drift',0,100,56,'%')+range('Undertow','tide-undertow',0,100,38,'%')+range('Noise','tide-noise',0,100,19,'%')),'Audio is generated on-device and starts only after pressing Start. Keep the volume low when exploring extreme settings.');}
  function bindTideSignal(root){const canvas=$('.tide-signal-canvas',root);let ac=null,master=null,osc=[],lfo=null,noise=null,noiseGain=null,renderer=null,phase=0,playing=false;function paint(c,w,h,t,dt,initial){phase+=dt*(+$('[data-range="tide-drift"]',root).value/100)*(playing?1.8:.34);c.fillStyle='#10131a';c.fillRect(0,0,w,h);c.strokeStyle='rgba(255,255,255,.07)';c.beginPath();c.moveTo(0,h*.5);c.lineTo(w,h*.5);c.stroke();const rootFreq=+$('[data-range="tide-root"]',root).value,drift=+$('[data-range="tide-drift"]',root).value/100,under=+$('[data-range="tide-undertow"]',root).value/100;c.beginPath();for(let x=0;x<=w;x++){const u=x/w,y=h*.5+Math.sin(u*14+phase)*h*(.08+under*.18)+Math.sin(u*51-phase*.65)*h*drift*.075;if(x===0)c.moveTo(x,y);else c.lineTo(x,y);}c.strokeStyle='#d6ff69';c.lineWidth=2;c.stroke();c.beginPath();for(let x=0;x<=w;x++){const u=x/w,y=h*.5+Math.sin(u*5-phase*.3)*h*.28;if(x===0)c.moveTo(x,y);else c.lineTo(x,y);}c.strokeStyle='#baa7ff88';c.lineWidth=1;c.stroke();c.fillStyle='#858391';c.font='9px monospace';c.fillText(`${rootFreq} HZ  /  ${playing?'SIGNAL LOCKED':'LISTENING POST'}`,12,h-12);}
    renderer=fitCanvas(canvas,paint,true);async function start(){if(playing)return;const AC=window.AudioContext||window.webkitAudioContext;if(!AC){toast(null,'Web Audio is not supported in this browser.');return;}try{ac=new AC();await ac.resume();master=ac.createGain();master.gain.value=.22;const filter=ac.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1800;filter.Q.value=1.2;filter.connect(master);master.connect(ac.destination);registerAudioMaster(master);const wave=$('[data-select="tide-wave"]',root).value,base=+$('[data-range="tide-root"]',root).value;osc=[0,1,2].map((i)=>{const o=ac.createOscillator(),g=ac.createGain();o.type=wave;o.frequency.value=base*(i===0?1:i===1?1.503:2.007);g.gain.value=[.65,.23,.12][i];o.connect(g);g.connect(filter);o.start();return o;});lfo=ac.createOscillator();const lg=ac.createGain();lfo.frequency.value=.04+(+$('[data-range="tide-drift"]',root).value/100)*.23;lg.gain.value=80+(+$('[data-range="tide-undertow"]',root).value);lfo.connect(lg);lg.connect(filter.frequency);lfo.start();const noiseBuffer=ac.createBuffer(1,ac.sampleRate,ac.sampleRate),data=noiseBuffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1);noise=ac.createBufferSource();noise.buffer=noiseBuffer;noise.loop=true;noiseGain=ac.createGain();noiseGain.gain.value=+$('[data-range="tide-noise"]',root).value/100*.025;noise.connect(noiseGain);noiseGain.connect(master);noise.start();playing=true;$('[data-tide-status]',root).textContent='SIGNAL LOCKED';$('[data-action="tide-start"]',root).textContent='● Signal running';}catch(e){toast(null,'The receiver could not start audio.');stop();}}
    function updateAudio(){if(!ac)return;const base=+$('[data-range="tide-root"]',root).value;osc.forEach((o,i)=>o.frequency.setTargetAtTime(base*[1,1.503,2.007][i],ac.currentTime,.1));if(noiseGain)noiseGain.gain.setTargetAtTime(+$('[data-range="tide-noise"]',root).value/100*.025,ac.currentTime,.08);if(lfo)lfo.frequency.setTargetAtTime(.04+(+$('[data-range="tide-drift"]',root).value/100)*.23,ac.currentTime,.1);}
    function stop(){playing=false;[...osc,lfo,noise].filter(Boolean).forEach(n=>{try{n.stop()}catch(_){}});osc=[];lfo=noise=null;if(ac){const old=ac;ac=null;old.close().catch(()=>{});}master=noiseGain=null;$('[data-tide-status]',root).textContent='FREQUENCY UNCLAIMED';$('[data-action="tide-start"]',root).textContent='▶ Start signal';}
    $('[data-action="tide-start"]',root).addEventListener('click',start);$('[data-action="tide-stop"]',root).addEventListener('click',stop);$('[data-action="tide-random"]',root).addEventListener('click',()=>{ $('[data-range="tide-root"]',root).value=Math.round(rand(38,180));$('[data-range="tide-drift"]',root).value=Math.round(rand(10,100));$('[data-range="tide-undertow"]',root).value=Math.round(rand(0,100));$('[data-select="tide-wave"]',root).value=pick(['sine','triangle','sawtooth','square']);updateAudio();renderer.redraw();});['tide-root','tide-drift','tide-undertow','tide-noise'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',()=>{updateAudio();renderer.redraw();}));$('[data-select="tide-wave"]',root).addEventListener('change',()=>{const shouldPlay=playing;stop();if(shouldPlay)start();renderer.redraw();});return()=>{stop();renderer.stop();};}

  // 48 - Atlas of Unclaimed Names: a searchable archive that visitors can annotate.
  const unclaimedRecords=[
    ['Avenfall','A valley where every stream bends toward a house that is not built.','VALLEY / WESTERN SHEET'],['Bellweather Reach','A coast whose lighthouse reports ships before they leave port.','COAST / CHART 04'],['Cinder Mile','A road measured in the distance between two extinguished fires.','ROAD / INLAND'],['Drowned Orchard','An orchard visible only when the water is perfectly still.','LOWLAND / NORTH'],['Elder Static','A settlement recorded as a frequency, not a coordinate.','SIGNAL / UNKNOWN'],['Fallowglass','A field of transparent crops that cast opaque shadows.','FIELD / EAST'],['Gloam Station','A station with a timetable but no arrivals or departures.','TRANSIT / BELOW'],['Hush Meridian','A line where recorded sound loses its final syllable.','BOUNDARY / 12'],['Ivory Current','A river that flows uphill for one minute at dusk.','WATER / SOUTH'],['Juniper Null','A forest whose trees grow in evenly spaced circles.','FOREST / 08'],['Kestrel Room','A room on a map with no building around it.','INTERIOR / UNPLACED'],['Low Lantern','A harbour light that shines downward into the seabed.','PORT / DEEP'],['Morrow Fold','A crease in a plain that shortens the way home.','TERRAIN / FOLD'],['Nacre Mile','A measured route whose distance changes with the weather.','ROAD / COASTAL'],['Orison Vale','A valley where echoes arrive before the original sound.','VALLEY / HIGH'],['Pale Switch','A railway junction with a platform on the wrong side of the track.','RAIL / 02'],['Quiet Number','A district identified by a number residents cannot remember.','DISTRICT / 00'],['Rookwater','A reservoir that reflects a different season from the one above it.','WATER / WEST'],['Salt Index','A flat plain marked by footprints no one has made.','PLAIN / 11'],['Tallow Gate','A gate that appears on local maps only after it is opened.','PASS / BORDER'],['Under September','A village whose calendar remains one month behind.','VILLAGE / INLAND'],['Vellum Bay','A bay that redraws its coastline after every tide.','COAST / 09'],['White Orchard','A grove of trees with pale fruit that never ripens.','ORCHARD / NORTH'],['Xylo Crossing','A crossing where footsteps make a faint wooden note.','CROSSING / 03'],['Yarrow Index','A directory of streets that exist only in handwritten form.','CITY / REGISTER'],['Zero Harbour','A harbour with a depth reading of exactly zero at all times.','PORT / 00'],['Amber Stair','A staircase carved into a cliff that descends into the sea.','CLIFF / EAST'],['Beneath Bell','A tunnel whose bells ring only when nobody is inside.','TUNNEL / SUBLEVEL'],['Copper Sleep','A suburb where every porch light turns on at the same minute.','SUBURB / 17'],['Drift Office','A government office whose address moves one block each year.','CIVIC / TEMPORARY'],['Elsewhere Park','A park with a second set of paths visible in winter.','PARK / NORTH'],['Forgotten Weather','A weather station that records conditions from the previous day.','OBSERVATORY / 05']
  ];
  function atlasUnclaimedMarkup(){return projectFrame('Strange archive / 06','Atlas of Unclaimed Names','A directory of places with names but no confirmed coordinates. Search the register, inspect a record and claim the entries you want to keep.',`<div class="atlas-shell"><div class="atlas-toolbar"><input type="search" data-atlas-search placeholder="Search names, notes or regions…" aria-label="Search atlas"><select data-atlas-filter aria-label="Filter claims"><option value="all">All entries</option><option value="unclaimed">Unclaimed</option><option value="claimed">Claimed by you</option></select></div><div class="atlas-columns"><div class="atlas-list" data-atlas-list></div><article class="atlas-detail" data-atlas-detail><p class="tool-eyebrow">SELECT A RECORD</p><h4>Unclaimed coordinates</h4><p>Choose a name from the register to see its note.</p></article></div></div>`,panel('Your register',`<div class="tool-readout"><span>Known names</span><strong>32</strong></div><div class="tool-readout"><span>Claimed locally</span><strong data-atlas-count>0</strong></div>${action('Claim a random place','atlas-random',true)}${action('Export claimed list','atlas-export')}<p class="tool-small">Claims are private to this browser. They do not reserve a real location.</p>`),'The locations are fictional. Your personal claims are stored only on this device.');}
  function bindAtlasUnclaimed(root){const list=$('[data-atlas-list]',root),detail=$('[data-atlas-detail]',root),search=$('[data-atlas-search]',root),filter=$('[data-atlas-filter]',root),count=$('[data-atlas-count]',root);let claimed=new Set(),selected=0;try{claimed=new Set(JSON.parse(localStorage.getItem('curioid-atlas-claims-v1')||'[]'));}catch(_){}function persist(){try{localStorage.setItem('curioid-atlas-claims-v1',JSON.stringify([...claimed]));}catch(_){}}function renderList(){const q=search.value.trim().toLowerCase(),f=filter.value;const rows=unclaimedRecords.map((r,i)=>({r,i})).filter(({r,i})=>(!q||r.join(' ').toLowerCase().includes(q))&&(f==='all'||(f==='claimed'?claimed.has(i):!claimed.has(i))));list.innerHTML=rows.map(({r,i})=>`<button type="button" class="atlas-entry${selected===i?' active':''}" data-atlas-entry="${i}"><span>${String(i+1).padStart(2,'0')} / ${esc(r[2])}</span><strong>${esc(r[0])}</strong><small>${claimed.has(i)?'CLAIMED':'UNCLAIMED'}</small></button>`).join('')||'<p class="tool-small">No records match that search.</p>';count.textContent=claimed.size;}
    function show(i){selected=i;const r=unclaimedRecords[i];detail.innerHTML=`<p class="tool-eyebrow">RECORD / ${String(i+1).padStart(3,'0')} · ${esc(r[2])}</p><h4>${esc(r[0])}</h4><p>${esc(r[1])}</p><div class="tool-readout"><span>Registry status</span><strong>${claimed.has(i)?'CLAIMED':'UNCLAIMED'}</strong></div><button type="button" class="tool-button primary" data-atlas-claim>${claimed.has(i)?'Release this claim':'Claim this place'}</button><button type="button" class="tool-button" data-atlas-copy>Copy record</button>`; $('[data-atlas-claim]',detail).addEventListener('click',()=>{claimed.has(i)?claimed.delete(i):claimed.add(i);persist();show(i);renderList();});$('[data-atlas-copy]',detail).addEventListener('click',async()=>{const text=`${r[0]} - ${r[1]} (${r[2]})`;try{await curioidClipboard.writeText(text);toast(null,'Record copied.')}catch(_){downloadBlob(new Blob([text],{type:'text/plain'}),'curioid-atlas-record.txt');}});renderList();}
    list.addEventListener('click',e=>{const b=e.target.closest('[data-atlas-entry]');if(b)show(+b.dataset.atlasEntry);});search.addEventListener('input',renderList);filter.addEventListener('change',renderList);$('[data-action="atlas-random"]',root).addEventListener('click',()=>{let choices=unclaimedRecords.map((r,i)=>i).filter(i=>!claimed.has(i));if(!choices.length)choices=unclaimedRecords.map((r,i)=>i);show(pick(choices));});$('[data-action="atlas-export"]',root).addEventListener('click',()=>{const text=[...claimed].sort((a,b)=>a-b).map(i=>unclaimedRecords[i].join(' - ')).join('\n');downloadBlob(new Blob([text||'No places claimed yet.'],{type:'text/plain'}),'curioid-atlas-claims.txt');});renderList();show(0);return()=>{};}

  // 49 - Print Room: local image processing for print-like treatments.
  function printRoomMarkup(){return projectFrame('Creative tool / 14','Print Room','Turn an ordinary image into a print-room experiment. Try layered inks, photocopy grain, halftone dots and misregistered plates. Images stay on your device.',`<div class="tool-canvas-wrap art-canvas-wrap"><canvas class="tool-canvas print-room-canvas" width="960" height="640" aria-label="Print treatment preview"></canvas></div><div class="tool-button-row">${action('Load sample image','print-sample',true)}${action('Export print PNG','print-export')}</div><label class="tool-control"><span>Choose local image</span><input type="file" data-print-file accept="image/*"></label><p class="tool-small" data-print-status>Using a generated sample plate.</p>`,panel('Print process',select('Process','print-process',[['riso','Risograph'],['halftone','Halftone'],['photocopy','Photocopy'],['threshold','Hard threshold'],['offset','Offset registration'],['newsprint','Old newsprint']])+range('Process strength','print-strength',0,100,78,'%')+range('Dot size','print-dot',2,18,7,' px')+range('Plate misalignment','print-offset',0,100,42,'%')+range('Paper wear','print-wear',0,100,35,'%')),'Images are processed locally using Canvas. The selected file is never uploaded.');}
  function bindPrintRoom(root){
    const canvas=$('.print-room-canvas',root),ctx=canvas.getContext('2d',{willReadFrequently:true}),status=$('[data-print-status]',root);let source=null,seed=4,loadToken=0,disposed=false,drawRaf=0;
    function sample(){const c=document.createElement('canvas');c.width=960;c.height=640;const x=c.getContext('2d'),g=x.createLinearGradient(0,0,960,640);g.addColorStop(0,'#d6ff69');g.addColorStop(.48,'#baa7ff');g.addColorStop(1,'#ff9cba');x.fillStyle=g;x.fillRect(0,0,960,640);x.fillStyle='#1a1a22';x.beginPath();x.arc(345,310,160,0,Math.PI*2);x.fill();x.fillStyle='#f0d7a8';x.beginPath();x.arc(620,260,110,0,Math.PI*2);x.fill();x.fillStyle='#11131a';x.font='bold 64px Georgia';x.fillText('SOMEWHERE',65,560);source=c;status.textContent='Generated sample plate.';draw();}
    function draw(){if(disposed||!source)return;const process=$('[data-select="print-process"]',root).value,strength=+$('[data-range="print-strength"]',root).value/100,dot=+$('[data-range="print-dot"]',root).value,offset=+$('[data-range="print-offset"]',root).value/100,wear=+$('[data-range="print-wear"]',root).value/100;ctx.fillStyle='#eee8d9';ctx.fillRect(0,0,canvas.width,canvas.height);const sw=source.width,sh=source.height,scale=Math.min(canvas.width/sw,canvas.height/sh),dw=sw*scale,dh=sh*scale,dx=(canvas.width-dw)/2,dy=(canvas.height-dh)/2;ctx.drawImage(source,dx,dy,dw,dh);let im;try{im=ctx.getImageData(0,0,canvas.width,canvas.height);}catch(_){status.textContent='Image processing is unavailable for this image.';return;}const d=im.data;for(let i=0;i<d.length;i+=4){const r=d[i],g=d[i+1],b=d[i+2],l=.2126*r+.7152*g+.0722*b;if(process==='threshold'){const v=l<128?20:238;d[i]=d[i]*(1-strength)+v*strength;d[i+1]=d[i+1]*(1-strength)+v*strength;d[i+2]=d[i+2]*(1-strength)+v*strength;}else if(process==='photocopy'){const v=clamp((l-128)*(1+strength*3)+128,0,255);d[i]=d[i+1]=d[i+2]=v;}else if(process==='riso'){d[i]=clamp(r*1.12+g*.12,0,255);d[i+1]=clamp(g*.94+b*.1,0,255);d[i+2]=clamp(b*1.15+r*.08,0,255);}else if(process==='newsprint'){const v=Math.round(l/(24+strength*36))*(24+strength*36);d[i]=v*.96;d[i+1]=v*.91;d[i+2]=v*.82;}else if(process==='offset'){d[i]=clamp(r+strength*55,0,255);d[i+1]=clamp(g-strength*30,0,255);d[i+2]=clamp(b+strength*35,0,255);}if(wear&&Math.random()<wear*.0007){d[i]*=.45;d[i+1]*=.45;d[i+2]*=.45;}}ctx.putImageData(im,0,0);if(process==='halftone'||process==='newsprint'||process==='riso'){const sampleData=ctx.getImageData(0,0,canvas.width,canvas.height).data;ctx.fillStyle=process==='riso'?'rgba(18,26,32,.38)':'rgba(15,15,19,.5)';for(let y=0;y<canvas.height;y+=dot*2)for(let x=0;x<canvas.width;x+=dot*2){const i=(y*canvas.width+x)*4,l=(sampleData[i]+sampleData[i+1]+sampleData[i+2])/3,rad=(1-l/255)*dot*(.35+strength);if(rad>.5){ctx.beginPath();ctx.arc(x,y,rad,0,Math.PI*2);ctx.fill();}}}if(process==='offset'&&offset){ctx.save();ctx.globalCompositeOperation='screen';ctx.globalAlpha=offset*.3;ctx.drawImage(canvas,offset*22,-offset*9);ctx.restore();}if(wear){ctx.fillStyle=`rgba(30,22,28,${wear*.08})`;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.strokeStyle=`rgba(40,30,25,${wear*.34})`;ctx.lineWidth=wear*9;ctx.strokeRect(8,8,canvas.width-16,canvas.height-16);}}
    function scheduleDraw(){if(disposed||drawRaf)return;drawRaf=requestAnimationFrame(()=>{drawRaf=0;draw();});}
    $('[data-action="print-sample"]',root).addEventListener('click',()=>{loadToken++;sample();});$('[data-action="print-export"]',root).addEventListener('click',()=>saveCanvas(canvas,'curioid-print-room.png'));
    $('[data-print-file]',root).addEventListener('change',async e=>{const input=e.target,f=input.files?.[0];input.value='';if(!f)return;const token=++loadToken;try{status.textContent='Preparing local image…';const result=await decodeLocalImage(f,1400);if(disposed||token!==loadToken)return;source=result.canvas;status.textContent=`Loaded ${f.name} locally · ${result.width} × ${result.height} · preview optimized.`;scheduleDraw();}catch(error){if(!disposed&&token===loadToken)status.textContent=error.message||'That image could not be opened.';}});
    ['print-strength','print-dot','print-offset','print-wear'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',scheduleDraw));$('[data-select="print-process"]',root).addEventListener('change',scheduleDraw);sample();return()=>{disposed=true;loadToken++;if(drawRaf)cancelAnimationFrame(drawRaf);source=null;};
  }

  // 50 - Poster Press: a flexible poster composition tool with live typography.
  function posterPressMarkup(){return projectFrame('Creative tool / 15','Poster Press','Build a finished poster from a few words, a strong layout and a graphic mark. Keep it restrained or push it until the type nearly loses its footing.',`<div class="tool-canvas-wrap art-canvas-wrap"><canvas class="tool-canvas poster-press-canvas" width="1000" height="1400" aria-label="Poster preview"></canvas></div><div class="tool-button-row">${action('New arrangement','poster-new',true)}${action('Randomize copy','poster-copy')}${action('Export poster PNG','poster-export')}</div>`,panel('Poster copy',`<label class="tool-control"><span>Main title</span><input type="text" data-poster-title maxlength="42" value="THE QUIET MACHINE"></label><label class="tool-control"><span>Secondary line</span><input type="text" data-poster-sub maxlength="70" value="A manual for listening to unfinished things"></label><label class="tool-control"><span>Small print</span><input type="text" data-poster-foot maxlength="70" value="FIELD NOTES · EDITION 08 · 03:17 AM"></label>`)+panel('Composition',select('Layout','poster-layout',[['editorial','Editorial'],['brutal','Brutalist'],['orbit','Orbital'],['gallery','Gallery notice'],['catalogue','Technical catalogue']])+select('Palette','poster-palette',[['mineral','Mineral'],['bruise','Bruise'],['dusk','Dusk'],['signal','Signal'],['paper','Paper and ink'],['ultraviolet','Ultraviolet'],['toxic','Toxic'],['infrared','Infrared'],['archive','Archive'],['abyss','Abyss'],['candy','Candy glass'],['oxidized','Oxidized'],['lunar','Lunar'],['fever','Fever'],['sediment','Sediment']])+select('Typeface mood','poster-type',[['sans','Modern grotesk'],['serif','Editorial serif'],['mono','Technical mono']])+range('Distortion','poster-distortion',0,100,32,'%')+range('Texture','poster-texture',0,100,24,'%')),'Create poster artwork locally, then export a large PNG ready for further editing.');}
  function bindPosterPress(root){const canvas=$('.poster-press-canvas',root);let seed=77;function paint(target=canvas){const c=target.getContext('2d'),w=target.width,h=target.height,layout=$('[data-select="poster-layout"]',root).value,palKey=$('[data-select="poster-palette"]',root).value,pal=palKey==='paper'?['#eee7d8','#181820','#b6a5c7','#9e7bb8']:palettes[palKey]||palettes.mineral,type=$('[data-select="poster-type"]',root).value,dist=+$('[data-range="poster-distortion"]',root).value/100,texture=+$('[data-range="poster-texture"]',root).value/100,title=$('[data-poster-title]',root).value||'UNTITLED',sub=$('[data-poster-sub]',root).value||'',foot=$('[data-poster-foot]',root).value||'';let s=seed;const rnd=()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};c.fillStyle=pal[0];c.fillRect(0,0,w,h);const ink=pal[1],accent=pal[2],accent2=pal[3]||pal[0];c.fillStyle=ink;c.fillRect(w*.055,h*.045,w*.89,h*.91);c.save();c.translate(w*.095,h*.08);const ww=w*.81,hh=h*.84;c.strokeStyle=accent;c.lineWidth=2;c.strokeRect(0,0,ww,hh);if(layout==='orbit'){c.strokeStyle=accent2;c.lineWidth=4;for(let i=0;i<7;i++){c.beginPath();c.ellipse(ww*.56,hh*.42,ww*(.13+i*.055),hh*(.07+i*.033),rnd()*.4,0,Math.PI*2);c.stroke();}c.fillStyle=accent;c.beginPath();c.arc(ww*.56,hh*.42,ww*.055,0,Math.PI*2);c.fill();}else if(layout==='brutal'){c.fillStyle=accent;c.fillRect(ww*.47,hh*.04,ww*.5,hh*.48);c.fillStyle=accent2;c.fillRect(ww*.03,hh*.62,ww*.3,hh*.25);}else if(layout==='gallery'){c.fillStyle=accent2;c.beginPath();c.arc(ww*.55,hh*.39,ww*.22,0,Math.PI*2);c.fill();c.fillStyle=ink;c.fillRect(ww*.48,hh*.12,ww*.12,hh*.54);}else if(layout==='catalogue'){c.strokeStyle=accent2;for(let i=0;i<14;i++){c.beginPath();c.moveTo(ww*.48+i*4,hh*.08);c.lineTo(ww*.48+i*4,hh*.58);c.stroke();}c.fillStyle=accent;c.fillRect(ww*.04,hh*.08,ww*.28,hh*.5);}else{c.fillStyle=accent2;c.beginPath();c.moveTo(ww*.05,hh*.08);c.lineTo(ww*.91,hh*.2);c.lineTo(ww*.75,hh*.56);c.lineTo(ww*.13,hh*.49);c.closePath();c.fill();}
      const font=type==='serif'?'Georgia,serif':type==='mono'?'monospace':'Arial,sans-serif';c.fillStyle=type==='serif'?pal[0]:'#f3f0e8';c.textBaseline='top';let size=Math.min(ww*.14,hh*.12);while(size>25){c.font=`900 ${size}px ${font}`;if(c.measureText(title.toUpperCase()).width<ww*.9)break;size-=2;}const words=title.toUpperCase().split(/\s+/);let lines=[],line='';for(const word of words){const test=line?line+' '+word:word;c.font=`900 ${size}px ${font}`;if(c.measureText(test).width>ww*.9&&line){lines.push(line);line=word;}else line=test;}if(line)lines.push(line);let y=layout==='gallery'?hh*.67:hh*.63;lines.slice(0,3).forEach((l,i)=>{c.save();c.translate((rnd()-.5)*dist*ww*.045,(rnd()-.5)*dist*hh*.02);c.rotate((rnd()-.5)*dist*.035);c.font=`900 ${size}px ${font}`;c.fillText(l,ww*.03,y+i*size*1.02);c.restore();});c.fillStyle=accent2;c.font=`${Math.max(17,size*.24)}px ${type==='mono'?'monospace':'Arial,sans-serif'}`;c.fillText(sub.slice(0,78),ww*.03,hh*.87);c.fillStyle=pal[0];c.font=`${Math.max(12,size*.14)}px monospace`;c.fillText(foot.slice(0,76),ww*.03,hh*.96);if(texture){for(let i=0;i<w*h*texture*.002;i++){c.fillStyle=rnd()>.5?'rgba(255,255,255,.14)':'rgba(0,0,0,.17)';c.fillRect(rnd()*ww,rnd()*hh,1+rnd()*3,1+rnd()*3);}}c.restore();}
    const renderer=fitCanvas(canvas,()=>paint(),false);function redraw(){renderer.redraw();}['poster-title','poster-sub','poster-foot'].forEach(k=>$(`[data-${k}]`,root).addEventListener('input',redraw));['poster-layout','poster-palette','poster-type'].forEach(k=>$(`[data-select="${k}"]`,root).addEventListener('change',redraw));['poster-distortion','poster-texture'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',redraw));$('[data-action="poster-new"]',root).addEventListener('click',()=>{seed=Math.floor(rand(1,999999));redraw();});$('[data-action="poster-copy"]',root).addEventListener('click',()=>{const titles=['A MAP OF QUIET THINGS','THE LAST WEATHER REPORT','NOTHING HAS BEEN MOVED','THE SHAPE OF A RETURN','INSTRUCTIONS FOR AN EMPTY ROOM'];const subs=['A field guide to places just out of reach','Notes from the department of ordinary anomalies','A small catalogue of things that almost happened'];$('[data-poster-title]',root).value=pick(titles);$('[data-poster-sub]',root).value=pick(subs);$('[data-poster-foot]',root).value='CURIOID · FIELD OFFICE / '+String(Math.floor(rand(1,99))).padStart(2,'0');redraw();});$('[data-action="poster-export"]',root).addEventListener('click',()=>{const out=document.createElement('canvas');out.width=2000;out.height=2800;paint(out);saveCanvas(out,'curioid-poster.png');});redraw();return()=>renderer.stop();}



  // 51 - The Recipe Foundry: pairwise food discovery, draggable inventory and a persistent cookbook.
  const foodIngredients = [
    ['tomato','Tomato','produce'],['potato','Potato','produce'],['onion','Onion','produce'],['garlic','Garlic','produce'],['carrot','Carrot','produce'],['spinach','Spinach','produce'],['mushroom','Mushroom','produce'],['eggplant','Eggplant','produce'],['zucchini','Zucchini','produce'],['pepper','Bell pepper','produce'],['chilli','Chilli','produce'],['lemon','Lemon','produce'],['orange','Orange','fruit'],['apple','Apple','fruit'],['pear','Pear','fruit'],['cabbage','Cabbage','produce'],['corn','Sweet corn','produce'],['peas','Peas','produce'],['broccoli','Broccoli','produce'],['pumpkin','Pumpkin','produce'],['beet','Beetroot','produce'],['cucumber','Cucumber','produce'],['olive','Olives','produce'],['banana','Banana','fruit'],['herbs','Fresh herbs','produce'],
    ['rice','Rice','grain'],['pasta','Pasta','grain'],['flour','Flour','grain'],['bread','Bread','grain'],['oats','Oats','grain'],['lentil','Lentils','legume'],['chickpea','Chickpeas','legume'],['bean','White beans','legume'],['peasplit','Split peas','legume'],
    ['egg','Egg','protein'],['chicken','Chicken','protein'],['fish','White fish','protein'],['sardine','Sardines','protein'],['tuna','Tuna','protein'],['tofu','Tofu','protein'],['yogurt','Yogurt','dairy'],['cheese','Cheese','dairy'],['butter','Butter','dairy'],
    ['oil','Olive oil','pantry'],['soy','Soy sauce','pantry'],['vinegar','Vinegar','pantry'],['honey','Honey','pantry'],['sugar','Sugar','pantry'],['cocoa','Cocoa','pantry'],['nuts','Nuts','pantry'],['sesame','Sesame','pantry'],['coconut','Coconut','pantry'],['cinnamon','Cinnamon','spice'],['cumin','Cumin','spice'],['paprika','Paprika','spice'],['peppercorn','Black pepper','spice'],['salt','Sea salt','spice'],['ginger','Ginger','spice'],['curry','Curry spices','spice'],['thyme','Thyme','spice'],['oregano','Oregano','spice'],['basil','Basil','spice'],['mint','Mint','spice'],['vanilla','Vanilla','spice'],['water','Water','liquid'],['heat','Heat','process'],['milk','Milk','dairy'],['yeast','Yeast','pantry'],['stock','Vegetable stock','liquid'],['tahini','Tahini','pantry'],
    ['celery','Celery','produce'],['leek','Leek','produce'],['avocado','Avocado','produce'],['strawberry','Strawberries','fruit'],['blueberry','Blueberries','fruit'],['grape','Grapes','fruit'],    ['date','Dates','fruit'],['mango','Mango','fruit'],['pineapple','Pineapple','fruit'],['kale','Kale','produce'],['shallot','Shallot','produce'],['chives','Chives','spice'],['cornstarch','Cornstarch','pantry'],['oat-milk','Oat milk','dairy'],['garlic-powder','Garlic powder','spice'],

    ['dill','Dill','spice'],['parsley','Parsley','spice'],['rosemary','Rosemary','spice'],['bay-leaf','Bay leaf','spice'],
    ['feta','Feta','dairy'],['mozzarella','Mozzarella','dairy'],['parmesan','Parmesan','dairy'],['cream','Cream','dairy'],['ricotta','Ricotta','dairy'],
    ['beef','Beef','protein'],['pork','Pork','protein'],['shrimp','Shrimp','protein'],['bacon','Bacon','protein'],['sausage','Sausage','protein'],
    ['breadcrumbs','Breadcrumbs','grain'],['semolina','Semolina','grain'],['tomato-paste','Tomato paste','pantry'],['baking-powder','Baking powder','pantry'],['baking-soda','Baking soda','pantry'],
    ['mustard','Mustard','pantry'],['maple-syrup','Maple syrup','pantry'],['jam','Fruit jam','pantry'],['chocolate','Dark chocolate','pantry'],    ['almond','Almonds','pantry'],['sweet-potato','Sweet potato','produce'],['cauliflower','Cauliflower','produce'],['asparagus','Asparagus','produce'],['green-bean','Green beans','produce'],['lettuce','Lettuce','produce'],['rocket','Rocket / arugula','produce'],['radish','Radish','produce'],['spring-onion','Spring onion','produce'],['black-bean','Black beans','legume'],['kidney-bean','Kidney beans','legume'],['quinoa','Quinoa','grain'],['couscous','Couscous','grain'],['bulgur','Bulgur wheat','grain'],['cornmeal','Cornmeal','grain'],['salmon','Salmon','protein'],['turkey','Turkey','protein'],['lamb','Lamb','protein'],['ham','Ham','protein'],['walnut','Walnuts','pantry'],['pistachio','Pistachios','pantry'],['peanut-butter','Peanut butter','pantry'],['cream-cheese','Cream cheese','dairy'],['halloumi','Halloumi','dairy'],['sour-cream','Sour cream','dairy'],['tea','Tea leaves','pantry'],['coffee','Ground coffee','pantry'],['lime','Lime','fruit'],['coconut-milk','Coconut milk','dairy'],['balsamic-vinegar','Balsamic vinegar','pantry'],['capers','Capers','pantry'],['miso','Miso paste','pantry'],['nutmeg','Nutmeg','spice']
  ];
  const foodFusionRules = Object.create(null);
  const foodPairKey = (a,b) => [String(a),String(b)].sort().join('::');
  function addFoodRule(a,b,id,name,kind,summary,method,rarity='common') {
    foodFusionRules[foodPairKey(a,b)] = {id,name,kind,summary,method,rarity};
  }
  // A deliberately authored starter graph: useful kitchen transformations and recognizable dishes.
  addFoodRule('flour','water','dough','Dough','component','A simple, workable dough. This is the beginning of breads, pastries and noodles.','Mix flour with water gradually until a shaggy dough forms. Knead briefly until smooth, then rest covered.');
  addFoodRule('dough','heat','flatbread','Flatbread','dish','A simple flatbread cooked on a hot surface.','Divide the dough, roll it thin and cook on a hot dry pan, turning until both sides have browned spots.');
  addFoodRule('dough','yeast','risen-dough','Risen dough','component','A light, airy dough ready for a slower bake.','Work yeast into the dough, cover and leave in a warm place until visibly expanded.');
  addFoodRule('risen-dough','heat','loaf-bread','Fresh loaf','dish','A simple crusty loaf with a soft centre.','Shape the risen dough and bake in a fully preheated oven until deeply golden and hollow-sounding when tapped.');
  addFoodRule('flour','egg','pasta-dough','Fresh pasta dough','component','A rich dough that can become fresh pasta.','Combine flour and egg, knead until smooth, wrap and rest before rolling thinly.');
  addFoodRule('pasta-dough','heat','toasted-pasta-dough','Toasted pasta ribbons','component','A crisp, toasted pasta experiment.','Cut the dough into ribbons and toast gently until dry and lightly coloured.');
  addFoodRule('pasta','water','boiled-pasta','Cooked pasta','component','Pasta softened in simmering water and ready for a sauce.','Cook pasta in plenty of salted boiling water until just tender, then drain.');
  addFoodRule('tomato','garlic','tomato-garlic-sauce','Tomato and garlic sauce','component','A savoury base for pasta, toast and slow-cooked dishes.','Gently cook chopped garlic in olive oil, add tomato and simmer until thick and glossy.');
  addFoodRule('boiled-pasta','tomato-garlic-sauce','tomato-garlic-pasta','Tomato and garlic pasta','dish','A classic quick pasta built from a bright tomato sauce.','Toss the cooked pasta through the sauce with a splash of pasta water. Finish with herbs and black pepper.');
  addFoodRule('rice','water','rinsed-rice','Rinsed rice','component','Clean rice, ready for cooking.','Rinse the rice in cool water until the water is less cloudy, then drain well.');
  addFoodRule('rinsed-rice','heat','steamed-rice','Steamed rice','dish','Fluffy rice with separate grains.','Add the rice and measured water to a covered pot. Simmer gently until tender, then rest off the heat.');
  addFoodRule('tomato','onion','sofrito-base','Tomato and onion base','component','A savoury base for stews, sauces and baked dishes.','Soften chopped onion slowly, add tomato and cook until the mixture is thick and sweet.');
  addFoodRule('sofrito-base','chickpea','chickpea-tomato-stew','Chickpea and tomato stew','dish','A hearty, pantry-friendly stew with a rich tomato base.','Add cooked chickpeas and vegetable stock to the tomato base. Simmer until thick, then finish with herbs and lemon.');
  addFoodRule('chickpea','sesame','sesame-chickpea-mash','Sesame chickpea mash','component','A coarse chickpea and sesame preparation that can be seasoned into a dip.','Mash cooked chickpeas with toasted sesame, olive oil, lemon and a little water. For classic hummus, combine chickpeas with tahini instead.');
  addFoodRule('chickpea','tahini','hummus','Hummus','dish','A smooth chickpea dip enriched with tahini.','Blend cooked chickpeas with tahini, lemon juice, garlic, olive oil and enough cold water to make a creamy texture. Season to taste.');
  addFoodRule('chickpea','garlic','falafel-mix','Falafel mixture','component','A fragrant chickpea mixture ready to shape.','Mash cooked chickpeas with garlic, herbs and cumin. Add a little flour if needed to help the mixture hold together.');
  addFoodRule('falafel-mix','heat','falafel','Falafel patties','dish','Golden chickpea patties with herbs and warm spice.','Shape the mixture into small patties and bake or pan-fry until crisp and hot all the way through.');
  addFoodRule('potato','heat','baked-potato','Baked potato','dish','A fluffy potato with a crisp skin.','Scrub and dry the potato, prick the skin and bake until the centre is completely soft.');
  addFoodRule('potato','oil','crispy-potatoes','Crispy potatoes','dish','Golden potato pieces with crisp edges.','Cut potatoes into even pieces, coat lightly with oil and roast in a hot oven, turning once until crisp and tender.');
  addFoodRule('baked-potato','cheese','cheese-baked-potato','Cheese baked potato','dish','A baked potato finished with melted cheese.','Split the hot baked potato, fluff the centre and add cheese. Return briefly to the oven until melted.');
  addFoodRule('tomato','pepper','shakshuka-base','Shakshuka base','component','A gently spiced tomato and pepper pan sauce.','Soften pepper and onion, add chopped tomato, cumin and paprika, then simmer until thick.');
  addFoodRule('shakshuka-base','egg','shakshuka','Shakshuka','dish','Eggs gently cooked in a spiced tomato and pepper sauce.','Make small wells in the simmering sauce, add eggs, cover and cook until the whites are set.');
