        const saved=iconLayout.positions[id];
        const initial={x:4+(index%columns)*(compact?32:23),y:4+Math.floor(index/columns)*(compact?27:31)};
        const position=saved&&Number.isFinite(Number(saved.x))&&Number.isFinite(Number(saved.y))?{x:clamp(Number(saved.x),0,90),y:clamp(Number(saved.y),0,88)}:initial;
