    root.addEventListener('dragover',e=>{const target=e.target.closest('[data-food-desktop-item]'),canvas=!target?e.target.closest('[data-food-desktop-items]'):null;if(!dragId)return;if(target&&target.dataset.foodDesktopItem===dragId)return;if(!target&&!canvas)return;e.preventDefault();(target||canvas).classList.add('is-drop-target');if(e.dataTransfer)e.dataTransfer.dropEffect='copy';});
