    root.addEventListener('drop',e=>{const target=e.target.closest('[data-food-desktop-item]'),canvas=!target?e.target.closest('[data-food-desktop-items]'):null;if(!dragId||(!target&&!canvas))return;e.preventDefault();(target||canvas).classList.remove('is-drop-target');if(target){if(target.dataset.foodDesktopItem!==dragId)combine(dragId,target.dataset.foodDesktopItem);}else addWorkspaceItem(dragId);dragId=null;});
