    root.addEventListener('contextmenu',e=>{if(e.target.closest('button,input,select,textarea,[data-food-window],.food-os-desktop-toolbar,.food-os-taskbar,.food-os-start-menu,.food-os-clock-panel,.food-os-context-menu'))return;e.preventDefault();foodContextAt(e);});
    root.addEventListener('click',e=>{if(!e.target.closest('[data-food-context-menu]'))$f('[data-food-context-menu]').hidden=true;if(!e.target.closest('[data-food-clock-panel],[data-food-clock-toggle]')){$f('[data-food-clock-panel]').hidden=true;$f('[data-food-clock-toggle]').setAttribute('aria-expanded','false');}});
    root.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='d'){e.preventDefault();$$f('[data-food-window]').forEach(w=>{w.style.display='none';w.classList.add('is-minimized');});updateTaskbar();return;}if(e.altKey&&e.key==='F4'){e.preventDefault();const open=$$f('[data-food-window]').filter(w=>w.isConnected&&w.style.display!=='none').sort((a,b)=>(Number(b.style.zIndex)||0)-(Number(a.style.zIndex)||0))[0];if(open)closeWindow(open);return;}if(e.key!=='Escape')return;const clockPanel=$f('[data-food-clock-panel]');if(clockPanel&&!clockPanel.hidden){clockPanel.hidden=true;$f('[data-food-clock-toggle]')?.setAttribute('aria-expanded','false');return;}const menu=$f('[data-food-start-menu]');if(!$f('[data-food-context-menu]').hidden){$f('[data-food-context-menu]').hidden=true;return;}if(menu&&!menu.hidden){menu.hidden=true;$f('[data-food-start-toggle]').setAttribute('aria-expanded','false');return;}const windows=$$f('[data-food-window]').filter(w=>w.isConnected);if(windows.length){windows.sort((a,b)=>(Number(b.style.zIndex)||0)-(Number(a.style.zIndex)||0));closeWindow(windows[0]);}});
