      for(let n=Math.min(3,phones.length);n>=1;n--){const group=phones.slice(0,n),key=group.map(normalizePhone).join(' '),joined=group.map(normalizePhone).join('');const override=custom[key.toLowerCase()]||custom[joined.toLowerCase()];if(override){const entry=tryAlias(override);if(entry)return{entry,count:n};}for(const candidate of [key,key.toLowerCase(),joined,joined.toLowerCase()]){const entry=tryAlias(candidate);if(entry)return{entry,count:n};}}
