    function transformSelectedLayer(){
      const layer=current();if(!layer){note('Choose a layer to transform.');return;}if(layer.locked){note('Unlock the selected layer before transforming it.');return;}
      const scale=clamp(Number(q('[data-u-transform-scale]').value)||100,10,300)/100,rotation=clamp(Number(q('[data-u-transform-rotation]').value)||0,-180,180)*Math.PI/180,dx=clamp(Number(q('[data-u-transform-x]').value)||0,-4096,4096),dy=clamp(Number(q('[data-u-transform-y]').value)||0,-4096,4096),flipX=q('[data-u-transform-flip-x]').checked,flipY=q('[data-u-transform-flip-y]').checked;
      if(scale===1&&rotation===0&&dx===0&&dy===0&&!flipX&&!flipY){note('No transform changes to apply.');return;}
      const apply=source=>{const out=makeCanvas(),c=out.getContext('2d');c.translate(doc.width/2+dx,doc.height/2+dy);c.rotate(rotation);c.scale(scale*(flipX?-1:1),scale*(flipY?-1:1));c.drawImage(source,-doc.width/2,-doc.height/2);return out;};
      checkpoint('Transform selected layer');layer.canvas=apply(layer.canvas);
      if(layer.mask){const transformed=apply(layer.mask),coverage=makeCanvas(),cc=coverage.getContext('2d');cc.fillStyle='#fff';cc.fillRect(0,0,doc.width,doc.height);const covered=apply(coverage),mc=transformed.getContext('2d'),image=mc.getImageData(0,0,doc.width,doc.height),cover=covered.getContext('2d').getImageData(0,0,doc.width,doc.height).data;for(let i=0;i<image.data.length;i+=4){const a=cover[i+3]/255;image.data[i]=image.data[i+1]=image.data[i+2]=255;image.data[i+3]=Math.round(image.data[i+3]*a+255*(1-a));}mc.putImageData(image,0,0);layer.mask=transformed;}
      if(layer.textInfo)layer.textInfo=null;maskScratch.delete(layer.id);hasArtwork=layers.some(item=>item.visible);updateLayerList();markChanged('Selected layer transformed');
      q('[data-u-transform-scale]').value=100;q('[data-u-transform-rotation]').value=0;q('[data-u-transform-x]').value=0;q('[data-u-transform-y]').value=0;q('[data-u-transform-flip-x]').checked=false;q('[data-u-transform-flip-y]').checked=false;
    }
    function nudgeSelectedLayer(dx,dy){const layer=current();if(!layer||layer.locked)return;layer.canvas=translateLayerSurface(layer.canvas,dx,dy);if(layer.mask)layer.mask=translateLayerSurface(layer.mask,dx,dy);if(layer.textInfo){layer.textInfo.x=clamp(layer.textInfo.x+dx,0,doc.width);layer.textInfo.y=clamp(layer.textInfo.y+dy,0,doc.height);}hasArtwork=true;markChanged(`Layer moved ${dx}, ${dy} px`);}
    function mergeDown(){const i=layers.findIndex(x=>x.id===activeLayerId);if(i<=0){note('Select a layer above another layer to merge down.');return;}const top=layers[i],below=layers[i-1];if(!top.visible||!below.visible){note('Show both layers before merging. Hidden layers are kept separate to avoid changing the result.');return;}if(top.locked||below.locked){note('Unlock both layers before merging.');return;}if(below.opacity<.999||below.blend!=='source-over'||top.blend!=='source-over'){note('For a predictable merge, set the lower layer to 100% Normal and the upper layer to Normal first. The upper layer opacity is preserved in the merged pixels.');return;}checkpoint('Merge layer down');const lower=renderLayerPixels(below),upper=renderLayerPixels(top),ctx=lower.getContext('2d');ctx.save();ctx.globalAlpha=top.opacity;ctx.globalCompositeOperation=top.blend||'source-over';ctx.drawImage(upper,0,0);ctx.restore();below.canvas=lower;below.mask=null;below.textInfo=null;below.name=(below.name+' + '+top.name).slice(0,80);layers.splice(i,1);maskScratch.delete(top.id);activeLayerId=below.id;updateLayerList();markChanged('Merged selected layer down');}
    function renameSelectedLayer(){const l=current();if(!l)return;const name=window.prompt('Layer name',l.name);if(name===null)return;const next=String(name).trim().slice(0,80);if(!next)return;checkpoint('Rename layer');l.name=next;updateLayerList();markChanged('Layer renamed');}
    function reorderLayer(sourceId,targetId){if(sourceId===targetId)return;const from=layers.findIndex(x=>x.id===sourceId),to=layers.findIndex(x=>x.id===targetId);if(from<0||to<0||from===to)return;checkpoint('Reorder layers');const [item]=layers.splice(from,1);layers.splice(to,0,item);activeLayerId=item.id;updateLayerList();markChanged('Layer stack reordered');}
    function copySelection(){const l=current();if(!l){note('No active layer to copy.');return;}const r=selection||{x:0,y:0,w:doc.width,h:doc.height};if(r.w<1||r.h<1)return;const data=renderLayerPixels(l),out=makeCanvas(r.w,r.h);out.getContext('2d').drawImage(data,r.x,r.y,r.w,r.h,0,0,r.w,r.h);selectionClipboard={canvas:out,x:r.x,y:r.y,w:r.w,h:r.h};note(`Copied ${r.w} × ${r.h} pixels from ${l.name}.`);}
    function cutSelection(){if(!selection){note('Create a marquee selection before cutting.');return;}const l=current();if(!l||l.locked){note('Unlock a layer before cutting pixels.');return;}copySelection();checkpoint(maskMode?'Cut selected pixels from layer mask':'Cut selection');const target=maskMode&&l.mask?l.mask:l.canvas;target.getContext('2d').clearRect(selection.x,selection.y,selection.w,selection.h);hasArtwork=layers.some(x=>x.visible);markChanged(maskMode?'Cut visible content by clearing the selected mask area':'Cut selected pixels to the UMBRA clipboard');}
    function pasteSelection(){if(!selectionClipboard){note('The UMBRA clipboard is empty. Copy or cut a selection first.');return;}checkpoint('Paste selection');const layer=createLayer('Pasted pixels');if(!layer)return;layer.canvas.getContext('2d').drawImage(selectionClipboard.canvas,selectionClipboard.x,selectionClipboard.y);selection={x:selectionClipboard.x,y:selectionClipboard.y,w:selectionClipboard.w,h:selectionClipboard.h};drawSelectionOverlay();markChanged('Pasted pixels on a new layer');}
    function deleteSelection(){if(!selection){note('Create a marquee selection first.');return;}const l=current();if(!l||l.locked){note('Unlock a layer before deleting pixels.');return;}checkpoint(maskMode?'Hide selected pixels with the layer mask':'Delete selected pixels');const target=maskMode&&l.mask?l.mask:l.canvas;target.getContext('2d').clearRect(selection.x,selection.y,selection.w,selection.h);markChanged(maskMode?'Selected area hidden by the layer mask':'Deleted selected pixels');}
    function clearSelection(){selection=null;pctx.clearRect(0,0,doc.width,doc.height);note('Selection cleared.');}
    function selectAll(){selection={x:0,y:0,w:doc.width,h:doc.height};drawSelectionOverlay();note('Entire canvas selected.');}
    function flipSelectedPixels(axis){if(!selection){note('Make a marquee selection first to flip selected pixels.');return;}const layer=current();if(!layer||layer.locked){note('Unlock the active layer before transforming pixels.');return;}const r=selection,w=Math.max(1,Math.floor(r.w)),h=Math.max(1,Math.floor(r.h));checkpoint('Flip selected pixels');for(const surface of [layer.canvas,layer.mask].filter(Boolean)){const c=surface.getContext('2d'),tmp=makeCanvas(w,h),tc=tmp.getContext('2d');tc.translate(axis==='horizontal'?w:0,axis==='vertical'?h:0);tc.scale(axis==='horizontal'?-1:1,axis==='vertical'?-1:1);tc.drawImage(surface,r.x,r.y,r.w,r.h,0,0,w,h);c.clearRect(r.x,r.y,r.w,r.h);c.drawImage(tmp,r.x,r.y);}if(layer.textInfo)layer.textInfo=null;markChanged(`Flipped selection ${axis}.`);}
    function transformDocument(mode){checkpoint(mode.replaceAll('-',' ')+' canvas');const oldW=doc.width,oldH=doc.height,newW=mode.startsWith('rotate')?oldH:oldW,newH=mode.startsWith('rotate')?oldW:oldH;const apply=source=>{const out=document.createElement('canvas');out.width=newW;out.height=newH;const c=out.getContext('2d');if(mode==='rotate-right'){c.translate(oldH,0);c.rotate(Math.PI/2);}else if(mode==='rotate-left'){c.translate(0,oldW);c.rotate(-Math.PI/2);}else if(mode==='flip-horizontal'){c.translate(oldW,0);c.scale(-1,1);}else if(mode==='flip-vertical'){c.translate(0,oldH);c.scale(1,-1);}c.drawImage(source,0,0);return out;};for(const layer of layers){layer.canvas=apply(layer.canvas);if(layer.mask)layer.mask=apply(layer.mask);if(layer.textInfo)layer.textInfo=null;}doc.width=newW;doc.height=newH;canvas.width=preview.width=composite.width=newW;canvas.height=preview.height=composite.height=newH;maskScratch.clear();selection=null;fitMode=true;fitZoom();syncUI();markChanged(`Canvas ${mode.replaceAll('-',' ')}.`);}
    function cloneStampAt(point){if(!drawing||!cloneSnapshot||!cloneSource)return;const ctx=drawing.layer.canvas.getContext('2d');ctx.save();if(selection)clipSelection(ctx);ctx.beginPath();ctx.arc(point.x,point.y,Math.max(1,brushSize/2),0,Math.PI*2);ctx.clip();ctx.globalAlpha=brushOpacity;ctx.drawImage(cloneSnapshot,drawing.from.x-cloneSource.x,drawing.from.y-cloneSource.y);ctx.restore();}

    function deleteLayer(){const i=layers.findIndex(l=>l.id===activeLayerId);if(i<0){note('Select a layer before deleting it.');return;}const active=layers[i];if(!window.confirm(`Delete “${active.name||'this layer'}”? You can undo this action.`))return;checkpoint('Delete layer');if(layers.length<=1){getCtx(current()).clearRect(0,0,doc.width,doc.height);if(current()?.mask)getCtx({canvas:current().mask}).clearRect(0,0,doc.width,doc.height);hasArtwork=false;markChanged('Cleared the only layer');return;}maskScratch.delete(active.id);layers.splice(i,1);activeLayerId=layers[Math.max(0,i-1)].id;updateLayerList();markChanged(`Deleted ${active.name||'layer'}`);}
    function moveLayer(delta){const i=layers.findIndex(l=>l.id===activeLayerId),j=clamp(i+delta,0,layers.length-1);if(i<0||i===j)return;checkpoint('Reorder layer');const [l]=layers.splice(i,1);layers.splice(j,0,l);updateLayerList();markChanged('Layer order changed');}
    function duplicateLayer(){const l=current();if(!l)return;if(layers.length>=layerLimit()){note(`Layer limit reached (${layerLimit()}) for this canvas size.`);return;}const n=makeLayer(l.name+' copy');n.canvas.getContext('2d').drawImage(l.canvas,0,0);n.visible=l.visible;n.opacity=l.opacity;n.blend=l.blend;n.textInfo=l.textInfo?{...l.textInfo}:null;if(l.mask){n.mask=makeCanvas();n.mask.getContext('2d').drawImage(l.mask,0,0);}layers.splice(layers.indexOf(l)+1,0,n);activeLayerId=n.id;updateLayerList();markChanged('Duplicated layer');}
    function addMask(){const l=current();if(!l)return;if(l.mask){note('This layer already has a mask.');return;}l.mask=makeCanvas();const m=l.mask.getContext('2d');m.fillStyle='#fff';m.fillRect(0,0,doc.width,doc.height);updateLayerList();markChanged('Added a white layer mask');}
    function download(blob,name){downloadBlob(blob,name);}
    function exportImage(type='image/png'){const out=makeCanvas();const c=out.getContext('2d');if(type==='image/jpeg'){c.fillStyle='#f4f1eb';c.fillRect(0,0,doc.width,doc.height);}c.drawImage(canvas,0,0);out.toBlob(blob=>{if(!blob){note('Export failed. Try a smaller canvas.');return;}download(blob,`${safeName(doc.name)}.${type==='image/jpeg'?'jpg':type==='image/webp'?'webp':'png'}`);note('Export complete.');},type,.92);}
    async function exportProject(){try{const blob=new Blob([JSON.stringify(serialize())],{type:'application/json'});download(blob,`${safeName(doc.name)}.umbra`);note('Editable UMBRA project exported.');}catch(_){note('Could not export the project.');}}
    function openWindow(id){const w=q(`[data-u-window="${id}"]`);if(!w)return;if(id==='new'){w.querySelector('[data-u-new-width]').value=doc.width;w.querySelector('[data-u-new-height]').value=doc.height;}w.hidden=false;w.classList.remove('is-minimized','is-maximized');w.style.zIndex=String(++zCounter);updateTaskTabs();if(id==='layers')updateLayerList();if(id==='filters')syncUI();if(id==='assets')updateAssetList();if(id==='transform'){q('[data-u-transform-scale]').value=100;q('[data-u-transform-rotation]').value=0;q('[data-u-transform-x]').value=0;q('[data-u-transform-y]').value=0;q('[data-u-transform-flip-x]').checked=false;q('[data-u-transform-flip-y]').checked=false;}q('[data-u-start]').hidden=true;}
    function closeWindow(w){w.hidden=true;w.classList.remove('is-minimized','is-maximized');updateTaskTabs();}
    function updateTaskTabs(){const list=q('[data-u-task-tabs]');list.replaceChildren();$$u('[data-u-window]').forEach(w=>{if(w.hidden)return;const id=w.dataset.uWindow,b=document.createElement('button');b.type='button';b.className='umbra-task-tab';b.textContent=appTitles[id]||id;b.dataset.uTaskWindow=id;b.title=appTitles[id]||id;list.appendChild(b);});}
    function handleCanvasDown(e){
      if(e.button!==0)return;
      const p=point(e),l=current();
      if(tool==='select'){drawing={mode:'select',from:p,last:p,pointerId:e.pointerId};try{canvas.setPointerCapture(e.pointerId);}catch(_){}e.preventDefault();return;}
      if(tool==='clone'){
        if(maskMode){note('Switch out of mask mode before using Clone Stamp.');return;}
        if(e.altKey){cloneSource=p;note(`Clone source set at X ${Math.round(p.x)}, Y ${Math.round(p.y)}.`);return;}
        if(!cloneSource){note('Alt-click the canvas to choose a clone source.');return;}
        if(!l||l.locked){note('Unlock the active layer before cloning.');return;}
        checkpoint('Clone stamp');cloneSnapshot=makeCanvas();cloneSnapshot.getContext('2d').drawImage(l.canvas,0,0);drawing={mode:'clone',from:p,last:p,layer:l,pointerId:e.pointerId};cloneStampAt(p);try{canvas.setPointerCapture(e.pointerId);}catch(_){}e.preventDefault();return;
      }
      if(tool==='zoom'){setZoomLevel(zoom*(e.shiftKey ? 0.8 : 1.2));note(`Zoom ${Math.round(zoom*100)}%.`);return;}
      if(tool==='hand'){
        viewportDrag={x:e.clientX,y:e.clientY,left:stage.scrollLeft,top:stage.scrollTop,pointerId:e.pointerId};
        try{canvas.setPointerCapture(e.pointerId);}catch(_){}e.preventDefault();return;
      }
      if(tool==='move'){
        if(!l||l.locked){note('The selected layer is locked.');return;}
        drawing={mode:'move',from:p,last:p,layer:l,ctx:null,pointerId:e.pointerId,moved:false};
        try{canvas.setPointerCapture(e.pointerId);}catch(_){}e.preventDefault();return;
      }
      if(tool==='crop'){drawing={mode:'crop',from:p,last:p,layer:l,ctx:null,pointerId:e.pointerId};try{canvas.setPointerCapture(e.pointerId);}catch(_){}e.preventDefault();return;}
      if(!l||l.locked){note('The selected layer is locked.');return;}
      if(tool==='fill'){checkpoint('Fill region');floodFill(l,p.x|0,p.y|0);hasArtwork=true;markChanged('Filled image region');return;}
      if(tool==='picker'){const d=ctx.getImageData(Math.floor(p.x),Math.floor(p.y),1,1).data;if(d[3]){fg='#'+[d[0],d[1],d[2]].map(v=>v.toString(16).padStart(2,'0')).join('');syncUI();}note('Sampled foreground color.');return;}
      if(tool==='text'){const text=q('[data-u-text-input]').value.trim()||'UMBRA';checkpoint('Add text');addTextAt(p.x,p.y,text,Number(q('[data-u-text-size]').value)||72,q('[data-u-text-font]').value,q('[data-u-text-weight]').value);return;}
      checkpoint(tool==='brush'?'Paint stroke':tool==='eraser'?'Erase stroke':'Shape');
      const ctxDraw=drawTarget();if(!ctxDraw)return;drawing={mode:tool,from:p,last:p,layer:l,ctx:ctxDraw,pointerId:e.pointerId};
      if(tool==='brush'||tool==='eraser'){ctxDraw.save();clipSelection(ctxDraw);ctxDraw.lineCap='round';ctxDraw.lineJoin='round';ctxDraw.lineWidth=brushSize;ctxDraw.globalAlpha=brushOpacity;ctxDraw.strokeStyle=maskMode?(tool==='brush'?'#000':'#fff'):fg;ctxDraw.fillStyle=ctxDraw.strokeStyle;if(maskMode&&tool==='brush')ctxDraw.globalCompositeOperation='destination-out';else if(!maskMode&&tool==='eraser')ctxDraw.globalCompositeOperation='destination-out';const radius=brushSize/2;ctxDraw.shadowColor=ctxDraw.strokeStyle;ctxDraw.shadowBlur=(100-Number(q('[data-u-hardness]').value||85))/100*radius*.7;ctxDraw.beginPath();ctxDraw.arc(p.x,p.y,Math.max(.5,radius),0,Math.PI*2);ctxDraw.fill();ctxDraw.beginPath();ctxDraw.moveTo(p.x,p.y);}
      try{canvas.setPointerCapture(e.pointerId);}catch(_){}e.preventDefault();
    }
    function handleCanvasMove(e){
      const p=point(e);q('[data-u-coordinates]').textContent=`X ${Math.round(p.x)} / Y ${Math.round(p.y)}`;
      if(viewportDrag&&viewportDrag.pointerId===e.pointerId){stage.scrollLeft=viewportDrag.left-(e.clientX-viewportDrag.x);stage.scrollTop=viewportDrag.top-(e.clientY-viewportDrag.y);return;}
      if(!drawing)return;
      if(drawing.mode==='move'){
        const dx=p.x-drawing.from.x,dy=p.y-drawing.from.y;drawing.last=p;drawing.moved=Math.abs(dx)+Math.abs(dy)>1;
        pctx.clearRect(0,0,doc.width,doc.height);pctx.save();pctx.globalAlpha=.68;pctx.drawImage(renderLayerPixels(drawing.layer),dx,dy);pctx.restore();return;
      }
      if(drawing.mode==='clone'){
        const last=drawing.last,dx=p.x-last.x,dy=p.y-last.y,steps=Math.max(1,Math.ceil(Math.hypot(dx,dy)/Math.max(2,brushSize*.24)));for(let i=1;i<=steps;i++)cloneStampAt({x:last.x+dx*i/steps,y:last.y+dy*i/steps});drawing.last=p;scheduleRender();return;
      }
      if(drawing.mode==='brush'||drawing.mode==='eraser'){drawing.ctx.lineTo(p.x,p.y);drawing.ctx.stroke();drawing.ctx.beginPath();drawing.ctx.moveTo(p.x,p.y);scheduleRender();}else drawPreviewShape(drawing.from,p);
    }
    function translateLayerSurface(source,dx,dy){const next=makeCanvas();next.getContext('2d').drawImage(source,dx,dy);return next;}
    function handleCanvasUp(e){
      if(viewportDrag&&viewportDrag.pointerId===e.pointerId){viewportDrag=null;return;}
      if(!drawing)return;const p=point(e),d=drawing,mode=d.mode||tool;
      if(mode==='select'){
        const x=Math.min(d.from.x,p.x),y=Math.min(d.from.y,p.y),w=Math.abs(p.x-d.from.x),h=Math.abs(p.y-d.from.y);selection=w>=1&&h>=1?{x:Math.floor(x),y:Math.floor(y),w:Math.max(1,Math.ceil(w)),h:Math.max(1,Math.ceil(h))}:null;
      }else if(mode==='move'){
        const dx=Math.round(p.x-d.from.x),dy=Math.round(p.y-d.from.y);
        if(dx||dy){checkpoint('Move layer');d.layer.canvas=translateLayerSurface(d.layer.canvas,dx,dy);if(d.layer.mask)d.layer.mask=translateLayerSurface(d.layer.mask,dx,dy);if(d.layer.textInfo){d.layer.textInfo.x=clamp(d.layer.textInfo.x+dx,0,doc.width);d.layer.textInfo.y=clamp(d.layer.textInfo.y+dy,0,doc.height);}hasArtwork=true;markChanged('Moved selected layer');}
      }else if(mode==='brush'||mode==='eraser'){d.ctx.restore();}
      else if(mode==='clone'){hasArtwork=true;markChanged('Clone stamp applied');}
      else if(['line','rect','ellipse'].includes(mode)){drawShape(d.layer,d.from,p);}
      else if(mode==='crop'){cropDocument(d.from,p);}
      else if(mode==='gradient'){d.ctx.save();clipSelection(d.ctx);const g=d.ctx.createLinearGradient(d.from.x,d.from.y,p.x,p.y);if(maskMode){g.addColorStop(0,'rgba(255,255,255,0)');g.addColorStop(1,'rgba(255,255,255,1)');}else{g.addColorStop(0,fg);g.addColorStop(1,bg);}d.ctx.fillStyle=g;d.ctx.fillRect(0,0,doc.width,doc.height);d.ctx.restore();}
      pctx.clearRect(0,0,doc.width,doc.height);drawing=null;cloneSnapshot=null;
      if(mode==='select'){drawSelectionOverlay();note(selection?`Selection ${selection.w} × ${selection.h}.`:'Selection cleared.');}
      else if(mode!=='crop'&&mode!=='move'){hasArtwork=true;markChanged('Canvas updated');}
    }
    async function loadImageFile(file){if(!file)return;if(file.size>35*1024*1024){note('That image is over 35 MB. Try a smaller source file.');return;}let bmp;try{bmp=await createImageBitmap(file);}catch(_){const url=URL.createObjectURL(file);try{bmp=await loadDataImage(url);}finally{URL.revokeObjectURL(url);}}const ratio=Math.min(1,MAX_DIM/bmp.width,MAX_DIM/bmp.height),nextW=Math.max(64,Math.round(bmp.width*ratio)),nextH=Math.max(64,Math.round(bmp.height*ratio));checkpoint('Open image as document');doc.width=nextW;doc.height=nextH;canvas.width=preview.width=doc.width;canvas.height=preview.height=doc.height;composite.width=doc.width;composite.height=doc.height;const l=makeLayer(file.name.replace(/\.[^.]+$/,'').slice(0,64)||'Image');l.canvas.getContext('2d').drawImage(bmp,0,0,doc.width,doc.height);layers=[l];maskScratch.clear();selection=null;cloneSource=null;activeLayerId=l.id;doc.name=safeName(file.name.replace(/\.[^.]+$/,''));hasArtwork=true;adjustments={brightness:100,contrast:100,saturation:100,hue:0,blur:0,grayscale:0,sepia:0,invert:0};fitZoom();syncUI();markChanged('Image opened as a document');try{bmp.close?.();}catch(_){} }
    async function addImageLayerFile(file){if(!file)return;if(file.size>35*1024*1024){note('That image is over 35 MB. Try a smaller source file.');return;}if(layers.length>=layerLimit()){note(`Layer limit reached (${layerLimit()}) for this canvas size.`);return;}let bmp;let objectUrl='';try{bmp=await createImageBitmap(file);}catch(_){objectUrl=URL.createObjectURL(file);try{bmp=await loadDataImage(objectUrl);}finally{URL.revokeObjectURL(objectUrl);}}const scale=Math.min(1,doc.width/bmp.width,doc.height/bmp.height),w=Math.max(1,Math.round(bmp.width*scale)),h=Math.max(1,Math.round(bmp.height*scale)),l=makeLayer(file.name.replace(/\.[^.]+$/,'').slice(0,64)||'Image layer');l.canvas.getContext('2d').drawImage(bmp,(doc.width-w)/2,(doc.height-h)/2,w,h);try{bmp.close?.();}catch(_){}checkpoint('Import image layer');layers.push(l);activeLayerId=l.id;hasArtwork=true;updateLayerList();markChanged('Imported image as a new layer');}
    function newDocument(){checkpoint('New document');doc.width=clamp(Number(q('[data-u-new-width]').value)||1200,64,MAX_DIM);doc.height=clamp(Number(q('[data-u-new-height]').value)||760,64,MAX_DIM);doc.name='Untitled';layers=[makeLayer('Layer 01')];maskScratch.clear();selection=null;cloneSource=null;activeLayerId=layers[0].id;hasArtwork=false;const bgval=q('[data-u-new-bg]').value;if(bgval!=='transparent'){hasArtwork=true;const l=makeLayer('Background');l.canvas.getContext('2d').fillStyle=bgval;l.canvas.getContext('2d').fillRect(0,0,doc.width,doc.height);l.locked=true;layers.unshift(l);activeLayerId=layers[1].id;}canvas.width=preview.width=composite.width=doc.width;canvas.height=preview.height=composite.height=doc.height;adjustments={brightness:100,contrast:100,saturation:100,hue:0,blur:0,grayscale:0,sepia:0,invert:0};fitMode=true;fitZoom();syncUI();markChanged('New canvas created');closeWindow(q('[data-u-window="new"]'));}
    function applyPreset(id){const presets={noir:{brightness:94,contrast:142,saturation:0,hue:0,blur:0,grayscale:100,sepia:0,invert:0},cinema:{brightness:98,contrast:118,saturation:112,hue:-5,blur:0,grayscale:0,sepia:8,invert:0},faded:{brightness:108,contrast:82,saturation:76,hue:5,blur:.2,grayscale:0,sepia:18,invert:0},infrared:{brightness:104,contrast:128,saturation:168,hue:140,blur:0,grayscale:0,sepia:0,invert:0},dream:{brightness:106,contrast:88,saturation:120,hue:-18,blur:1.5,grayscale:0,sepia:6,invert:0},mono:{brightness:100,contrast:110,saturation:0,hue:0,blur:0,grayscale:100,sepia:0,invert:0}};checkpoint('Filter preset: '+id);adjustments={...presets[id]};syncUI();markChanged('Applied '+id.toUpperCase()+' grade');}
    function applyPixelForge(type){checkpoint('Pixel Forge: '+type);const l=createLayer('Forge · '+type);if(!l)return;hasArtwork=true;const c=getCtx(l);const w=doc.width,h=doc.height;c.save();if(type==='gradient'||type==='nebula'){const g=c.createRadialGradient(w*.5,h*.5,1,w*.5,h*.5,Math.max(w,h)*.72);g.addColorStop(0,fg);g.addColorStop(.5,type==='nebula'?'#8c4cff':'#252b4b');g.addColorStop(1,'#070a12');c.fillStyle=g;c.fillRect(0,0,w,h);if(type==='nebula'){c.globalCompositeOperation='screen';for(let i=0;i<26;i++){const x=Math.random()*w,y=Math.random()*h,r=rand(20,Math.max(35,w*.14));const s=c.createRadialGradient(x,y,0,x,y,r);s.addColorStop(0,`hsla(${Math.random()*360},90%,65%,.18)`);s.addColorStop(1,'transparent');c.fillStyle=s;c.fillRect(x-r,y-r,r*2,r*2);}}}else if(type==='noise'){const sw=Math.min(512,w),sh=Math.min(512,h),t=makeCanvas(sw,sh),tc=t.getContext('2d'),im=tc.createImageData(sw,sh);for(let i=0;i<im.data.length;i+=4){const n=Math.random()*255;im.data[i]=n;im.data[i+1]=n;im.data[i+2]=n;im.data[i+3]=Math.random()*105;}tc.putImageData(im,0,0);c.drawImage(t,0,0,w,h);}else if(type==='stars'){c.fillStyle='#070a12';c.fillRect(0,0,w,h);for(let i=0;i<Math.floor(w*h/4200);i++){const r=rand(.4,2.2);c.fillStyle=`rgba(225,235,255,${rand(.15,.9)})`;c.beginPath();c.arc(Math.random()*w,Math.random()*h,r,0,Math.PI*2);c.fill();}}else if(type==='scanlines'){c.fillStyle='rgba(0,0,0,.34)';for(let y=0;y<h;y+=4)c.fillRect(0,y,w,1.5);}else if(type==='halftone'){c.fillStyle=fg;for(let y=0;y<h;y+=12)for(let x=0;x<w;x+=12){const r=Math.random()*4.5;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill();}}c.restore();updateLayerList();markChanged('Generated '+type+' texture');}
    async function generateSoundPalette(){const phrase=q('[data-u-sound-palette-input]')?.value.trim(),status=q('[data-u-sound-palette-status]');if(!phrase){note('Enter a phrase for the sound palette.');return;}try{if(status)status.textContent='Querying Echonoise local phonetic service…';const palette=await CurioidKernel.requestCapability('echonoise.lexicon.palette',{text:phrase},{fromExperienceId:'umbra-os'});const colors=[...new Set((palette.colors||[]).filter(color=>/^#[0-9a-f]{6}$/i.test(String(color))).map(color=>String(color).toLowerCase()))].slice(0,8);if(!colors.length)throw new Error('The sound service returned no usable colors.');checkpoint('Generate phonetic color palette');fg=colors[0];if(colors[1])bg=colors[1];const paletteHost=q('[data-u-palette]');if(paletteHost)paletteHost.innerHTML=colors.map((color,index)=>`<button type="button" data-u-swatch="${color}" style="--swatch:${color}" title="${color} · ${esc(String(palette.swatches?.[index]?.role||'Sound color'))}"><span>${color}</span></button>`).join('');syncUI();if(status)status.textContent=`${colors.length} colors from ${palette.fingerprint?.wordCount||0} words · dominant vowel ${palette.fingerprint?.dominantVowel||' - '} · seed ${palette.seed}.`;note('Echonoise sound palette applied to Color Lab.');}catch(error){if(status)status.textContent=error.message||'Sound palette unavailable. Open Echonoise and retry.';}}
    function extractPalette(){const sample=makeCanvas(64,64),sc=sample.getContext('2d');sc.drawImage(canvas,0,0,64,64);const data=sc.getImageData(0,0,64,64).data,bins=new Map();for(let i=0;i<data.length;i+=16){if(data[i+3]<40)continue;const r=data[i]>>4,g=data[i+1]>>4,b=data[i+2]>>4,key=(r<<8)|(g<<4)|b;bins.set(key,(bins.get(key)||0)+1);}const top=[...bins.entries()].sort((a,b)=>b[1]-a[1]).slice(0,8);const colors=top.map(([k])=>'#'+[((k>>8)&15)*17,((k>>4)&15)*17,(k&15)*17].map(v=>v.toString(16).padStart(2,'0')).join(''));q('[data-u-palette]').innerHTML=colors.map(color=>`<button type="button" data-u-swatch="${color}" style="--swatch:${color}" title="${color}"><span>${color}</span></button>`).join('')||'<p class="umbra-empty-list">No visible colors found on this canvas yet.</p>';note('Extracted '+colors.length+' colors.');}
    function updateTaskTabs(){const list=q('[data-u-task-tabs]');list.replaceChildren();$$u('[data-u-window]').forEach(w=>{if(w.hidden)return;const id=w.dataset.uWindow,b=document.createElement('button');b.type='button';b.className='umbra-task-tab';b.textContent=appTitles[id]||id;b.dataset.uTaskWindow=id;b.title=appTitles[id]||id;list.appendChild(b);});}
    function openDb(){if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{if(!('indexedDB'in window)){resolve(null);return;}const req=indexedDB.open('curioid-umbra-studio-v1',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('documents'))req.result.createObjectStore('documents');};req.onsuccess=()=>resolve(req.result);req.onerror=()=>{dbPromise=null;reject(req.error);};});return dbPromise;}
    const queueAutosave=()=>{if(disposed)return;clearTimeout(autosaveTimer);autosaveTimer=setTimeout(saveAuto,1500);};
    async function saveAuto(){if(disposed)return;try{const db=await openDb();if(disposed)return;if(!db){q('[data-u-save-status]').textContent='EXPORT TO SAVE';return;}const payload=serialize();const bytes=payload.layers.reduce((n,l)=>n+(l.canvas?.length||0)+(l.mask?.length||0),0);if(bytes>48000000){q('[data-u-save-status]').textContent='EXPORT TO SAVE';note('Document is too large for automatic local recovery. Export an editable .umbra copy.');return;}await new Promise((resolve,reject)=>{const tx=db.transaction('documents','readwrite');tx.objectStore('documents').put(payload,'active');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});if(disposed)return;dirty=false;updateTitle();q('[data-u-save-status]').textContent='AUTOSAVED';}catch(_){if(!disposed){const status=q('[data-u-save-status]');if(status)status.textContent='SAVE UNAVAILABLE';}}}
    async function recoverAuto(){try{const db=await openDb();if(disposed||!db)return;const data=await new Promise((resolve,reject)=>{const tx=db.transaction('documents','readonly'),req=tx.objectStore('documents').get('active');req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error);});if(disposed)return;if(data?.app==='UMBRA_STUDIO'&&!userTouched) {await restoreData(data);if(disposed)return;dirty=false;note('Recovered your last local session.');}}catch(_){if(!disposed)note('Could not recover the previous local session.');}}
    function handleAction(act){switch(act){
      case 'new':openWindow('new');break;case 'open':q('[data-u-open-file]').click();break;case 'save':exportProject();break;case 'export-png':exportImage('image/png');break;case 'export-jpg':exportImage('image/jpeg');break;case 'export-webp':exportImage('image/webp');break;case 'export-project':exportProject();break;
      case 'undo':undo();break;case 'redo':redo();break;case 'add-layer':checkpoint('New layer');createLayer('Layer '+String(layers.length+1).padStart(2,'0'));break;case 'move-layer-up':moveLayer(1);break;case 'move-layer-down':moveLayer(-1);break;case 'delete-layer':deleteLayer();break;case 'duplicate-layer':checkpoint('Duplicate layer');duplicateLayer();break;case 'toggle-mask':checkpoint('Add layer mask');addMask();break;case 'merge-down':mergeDown();break;case 'rename-layer':renameSelectedLayer();break;case 'mask-mode':if(!current()?.mask){checkpoint('Add layer mask');addMask();}maskMode=!maskMode;q('[data-u-action="mask-mode"]').setAttribute('aria-pressed',String(maskMode));note(maskMode?'Mask paint mode: brush hides, eraser reveals.':'Normal pixel painting.');break;
      case 'select-all':selectAll();break;case 'deselect':clearSelection();break;case 'copy-selection':copySelection();break;case 'cut-selection':cutSelection();break;case 'paste-selection':pasteSelection();break;case 'delete-selection':deleteSelection();break;case 'rotate-left':transformDocument('rotate-left');break;case 'rotate-right':transformDocument('rotate-right');break;case 'flip-horizontal':flipSelectedPixels('horizontal');break;case 'flip-vertical':flipSelectedPixels('vertical');break;case 'toggle-grid':{const grid=q('[data-u-grid]');grid.hidden=!grid.hidden;$$u('[data-u-action="toggle-grid"]').forEach(b=>b.setAttribute('aria-pressed',String(!grid.hidden)));break;}case 'update-text':updateSelectedText();break;case 'load-text':editSelectedText();break;case 'apply-transform':transformSelectedLayer();break;case 'reset-transform':q('[data-u-transform-scale]').value=100;q('[data-u-transform-rotation]').value=0;q('[data-u-transform-x]').value=0;q('[data-u-transform-y]').value=0;q('[data-u-transform-flip-x]').checked=false;q('[data-u-transform-flip-y]').checked=false;note('Transform values reset.');break;case 'fit':fitMode=true;fitZoom();break;case 'zoom-in':setZoom(zoom*1.15);break;case 'zoom-out':setZoom(zoom/1.15);break;case 'swap-colors':[fg,bg]=[bg,fg];syncUI();break;case 'reset-adjustments':checkpoint('Reset grade');adjustments={brightness:100,contrast:100,saturation:100,hue:0,blur:0,grayscale:0,sepia:0,invert:0};syncUI();markChanged('Grade reset');break;case 'create-document':newDocument();break;case 'extract-palette':extractPalette();break;case 'sound-palette':generateSoundPalette().catch(error=>note(error.message));break;case 'add-text-center':checkpoint('Add text');addTextAt(doc.width*.08,doc.height*.36,q('[data-u-text-input]').value||'UMBRA',Number(q('[data-u-text-size]').value)||72,q('[data-u-text-font]').value,q('[data-u-text-weight]').value);break;case 'flatten':checkpoint('Flatten grade');{const flat=makeCanvas();const fc=flat.getContext('2d');fc.drawImage(canvas,0,0);layers=[{...makeLayer('Flattened image'),canvas:flat}];activeLayerId=layers[0].id;adjustments={brightness:100,contrast:100,saturation:100,hue:0,blur:0,grayscale:0,sepia:0,invert:0};syncUI();markChanged('Flattened current grade');}break;
      case 'fullscreen':break;case 'show-desktop':$$u('[data-u-window]').forEach(w=>w.hidden=true);updateTaskTabs();break;case 'minimize-editor':q('.umbra-editor-window').classList.toggle('is-minimized');break;case 'maximize-editor':q('.umbra-editor-window').classList.toggle('is-maximized');break;
    }}
    function click(e){const t=e.target.closest('button,[data-u-launch],label');if(!t)return;if(t.dataset.uAction){handleAction(t.dataset.uAction);return;}if(t.dataset.uTool){setTool(t.dataset.uTool);return;}if(t.dataset.uLaunch){openWindow(t.dataset.uLaunch);return;}if(t.dataset.uWinClose!==undefined){closeWindow(t.closest('[data-u-window]'));return;}if(t.dataset.uWinMin!==undefined){const w=t.closest('[data-u-window]');w.classList.add('is-minimized');updateTaskTabs();return;}if(t.dataset.uWinMax!==undefined){t.closest('[data-u-window]').classList.toggle('is-maximized');return;}if(t.dataset.uTaskWindow){const w=q(`[data-u-window="${t.dataset.uTaskWindow}"]`);if(w.classList.contains('is-minimized'))w.classList.remove('is-minimized');else w.classList.add('is-minimized');w.style.zIndex=String(++zCounter);updateTaskTabs();return;}if(t.dataset.uHistoryIndex!==undefined){const back=Number(t.dataset.uHistoryIndex);const index=history.length-1-back;if(index>=0&&!historyBusy){const item=history[index],before=makeSnapshot('Redo'),nextHistory=history.slice(0,index);historyBusy=true;restoreData(item.data).then(()=>{future.push(before);trimSnapshots(future);history=nextHistory;dirty=true;note('Restored: '+item.label);queueAutosave();renderHistory();}).catch(err=>note('History restore failed: '+err.message)).finally(()=>{historyBusy=false;});}return;}if(t.dataset.uLayerLock){const l=layers.find(x=>x.id===t.dataset.uLayerLock);if(l){checkpoint('Toggle layer lock');l.locked=!l.locked;updateLayerList();markChanged(l.locked?'Layer locked':'Layer unlocked');}return;}if(t.dataset.uLayerSelect){activeLayerId=t.dataset.uLayerSelect;cloneSource=null;updateLayerList();return;}if(t.dataset.uLayerVisible){const l=layers.find(x=>x.id===t.dataset.uLayerVisible);if(l){checkpoint('Layer visibility');l.visible=!l.visible;updateLayerList();markChanged('Layer visibility changed');}return;}if(t.dataset.uPreset){applyPreset(t.dataset.uPreset);return;}if(t.dataset.uForge){applyPixelForge(t.dataset.uForge);return;}if(t.dataset.uSwatch){fg=t.dataset.uSwatch;syncUI();note('Foreground color updated.');return;}if(t.dataset.uStartToggle!==undefined){const m=q('[data-u-start]');m.hidden=!m.hidden;q('[data-u-start-toggle]').setAttribute('aria-expanded',String(!m.hidden));return;}if(t.dataset.uEditorTab!==undefined){q('.umbra-editor-window').classList.remove('is-minimized');return;}}
    root.addEventListener('dblclick',e=>{const row=e.target.closest('[data-u-layer-row]');if(row){const layer=layers.find(x=>x.id===row.dataset.uLayerRow);if(layer){activeLayerId=layer.id;renameSelectedLayer();}}});
    let draggingLayerId='';
    root.addEventListener('dragstart',e=>{const row=e.target.closest('[data-u-layer-row]');if(!row)return;draggingLayerId=row.dataset.uLayerRow;e.dataTransfer?.setData('text/plain',draggingLayerId);if(e.dataTransfer)e.dataTransfer.effectAllowed='move';row.classList.add('is-dragging');});
