    q('[data-u-navigator]').addEventListener('click',centerNavigatorAt);stage.addEventListener('scroll',updateNavigator,{passive:true});root.addEventListener('click',click);
    root.addEventListener('click',e=>{const menu=q('[data-u-start]');if(!menu.hidden&&!e.target.closest('[data-u-start], [data-u-start-toggle]')){menu.hidden=true;q('[data-u-start-toggle]').setAttribute('aria-expanded','false');}});
