    function addNode(data,position=null){if(workspace.nodes.length>=MAX_NODES){say(`Workspace limit: ${MAX_NODES} nodes.`);return null;}const base=centerPoint(),count=workspace.nodes.length,angle=count*2.399963,ring=150+Math.sqrt(count)*60,p=position||{x:clampA(base.x+Math.cos(angle)*ring,80,WORLD_W-280),y:clampA(base.y+Math.sin(angle)*ring,80,WORLD_H-220)};const n={id:uidA(),type:AETHER_NODE_TYPES.has(data.type)?data.type:'note',title:cleanText(data.title||'Untitled'),content:cleanText(data.content||''),url:data.url||'',tags:Array.isArray(data.tags)?data.tags.slice(0,12):String(data.tags||'').split(',').map(s=>s.trim()).filter(Boolean).slice(0,12),x:clampA(p.x,20,WORLD_W-260),y:clampA(p.y,20,WORLD_H-220),fileName:data.fileName||'',size:Number(data.size)||0,mime:data.mime||'',asset:data.asset||null,done:Boolean(data.done),created:Date.now()};workspace.nodes.push(n);selectedId=n.id;renderNodes();selectNode(n.id);queueGravity();queueSave();return n;}
    function openNodeDialog(type='note'){const d=q('[data-a-node-dialog]');d.querySelector('[data-a-new-type]').value=type;d.querySelector('[data-a-new-title]').value='';d.querySelector('[data-a-new-url]').value='';d.querySelector('[data-a-new-content]').value='';d.querySelector('[data-a-new-tags]').value='';d.querySelector('[data-a-url-wrap]').hidden=!['link','api'].includes(type);d.showModal();d.querySelector('[data-a-new-title]').focus();}
    function selectAetherBatch(files){
      const selectedCount=Math.max(0,Number(files?.length)||0),list=[];let selectedBytes=0,skipped=0;
      for(let i=0;i<Math.min(selectedCount,MAX_BATCH_FILES);i++){
        const file=files[i],size=Number(file?.size);
        if(!file||!Number.isFinite(size)||size<0||size>MAX_FILE_BYTES||selectedBytes+size>MAX_BATCH_BYTES){skipped++;continue;}
        list.push(file);selectedBytes+=size;
      }
      skipped+=Math.max(0,selectedCount-MAX_BATCH_FILES);
      return{list,skipped,selectedBytes};
    }
    async function ingestFiles(files,center){
      const {list,skipped}=selectAetherBatch(files);
      if(!list.length){say(skipped?'No files fit the Aether import limits (64 MB per file, 256 MB per batch, 100 files).':'Choose files to add.');return;}
      let done=0,failed=0,cleanupFailed=0;
      for(const file of list){
        if(workspace.nodes.length>=MAX_NODES){say(`Workspace limit: ${MAX_NODES} nodes.`);break;}
        let storedAsset=null;
        try{
          let fileText='';const ext=String(file.name||'').split('.').pop().toLowerCase();
          if(file.size<200000&&/^(txt|md|js|mjs|ts|tsx|jsx|json|html|css|scss|csv|xml|yaml|yml|py|rs|go|java|c|cpp|h|sh|sql|toml|ini|log|svg)$/i.test(ext))fileText=(await file.text()).slice(0,MAX_TEXT);
          storedAsset=await storeAsset(file);
          const offset=done*32;
          const n=addNode({type:'file',title:file.name,fileName:file.name,size:file.size,mime:file.type,content:fileText||`Local file · ${file.type||'unknown type'} · ${(file.size/1048576).toFixed(2)} MB`,asset:storedAsset},center?{x:center.x+offset,y:center.y+offset}:null);
          if(!n){try{await removeAsset(storedAsset);}catch(_){cleanupFailed++;}storedAsset=null;break;}
          storedAsset=null;done++;
        }catch(error){if(storedAsset){try{await removeAsset(storedAsset);}catch(_){cleanupFailed++;}}failed++;say(`${file.name}: ${error.message||'could not store file'}`);}
      }
      say(`${done} file${done===1?'':'s'} added · ${failed} failed${skipped?` · ${skipped} skipped by batch limits`:''}${cleanupFailed?` · ${cleanupFailed} attachment cleanup(s) need attention`:''}`);
      updateStorageEstimate();
    }
    function encodeBase64Url(text){const bytes=new TextEncoder().encode(text);let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,Math.min(i+0x8000,bytes.length)));return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
    function decodeBase64Url(value){const b64=value.replace(/-/g,'+').replace(/_/g,'/');const binary=atob(b64+'='.repeat((4-b64.length%4)%4));const bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));return new TextDecoder().decode(bytes);}
    async function importSharedHash(){
      const match=String(location.hash||'').match(/(?:^#|&)aether=([A-Za-z0-9_-]+)/);
      if(!match)return false;
      if(match[1].length>12*1024*1024){say('Shared Aether link is too large. Import the .aether file instead.');return false;}
      try{const pack=JSON.parse(decodeBase64Url(match[1]));await restoreRealityPack(pack,'shared.aether');const remainingHash=String(location.hash||'').slice(1).split('&').filter(part=>part&&!part.startsWith('aether=')).join('&');history.replaceState(history.state,'',`${location.pathname}${location.search}${remainingHash?`#${remainingHash}`:''}`);return true;}
      catch(error){say(`Shared Aether link could not be restored: ${String(error?.message||'invalid package').slice(0,180)}`);return false;}
    }
    function portableState(){return{format:'Aether.OS Reality',version:1,exported:new Date().toISOString(),workspace:{id:workspace.id,name:workspace.name,nodes:workspace.nodes.map(n=>({...n,asset:n.asset?{...n.asset,embedded:false}:null})),edges:workspace.edges||[],view:workspace.view}};}
    async function exportReality(){const pack=portableState();let total=0,skipped=[];for(const n of pack.workspace.nodes){if(n.type!=='file'||!n.asset)continue;const file=await getAsset(n.asset).catch(()=>null);if(!file){skipped.push(n.fileName);continue;}if(total+file.size>8*1024*1024){skipped.push(n.fileName);continue;}const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]||'');r.onerror=()=>reject(r.error);r.readAsDataURL(file);});n.asset={...n.asset,embedded:true,data};total+=file.size;}const blob=new Blob([JSON.stringify(pack)],{type:'application/json'});downloadBlob(blob,`${(workspace.name||'aether-reality').replace(/[^a-z0-9_-]+/gi,'-').toLowerCase()}.aether`);say(skipped.length?`Reality exported. ${skipped.length} large attachment(s) remain local.`:'Portable workspace exported with included attachments.');}
    function sanitizeImportedEdges(rawEdges,idMap){const output=[],seen=new Set(),input=Array.isArray(rawEdges)?rawEdges.slice(0,10000):[];for(const edge of input){if(!edge||typeof edge!=='object')continue;const a=idMap.get(String(edge.a||'')),b=idMap.get(String(edge.b||''));if(!a||!b||a===b)continue;const key=[a,b].sort().join('|');if(seen.has(key))continue;seen.add(key);output.push({a,b,created:Number(edge.created)||Date.now()});if(output.length>=2000)break;}return output;}
    async function restoreRealityPack(pack,filename='shared.aether'){
      if(pack?.format!=='Aether.OS Reality'||pack.version!==1||!Array.isArray(pack.workspace?.nodes))throw new Error('Unsupported Aether workspace package.');
      if(pack.workspace.nodes.length>MAX_NODES)throw new Error(`This workspace contains more than ${MAX_NODES} nodes.`);
      if(workspaces.length>=80)throw new Error('This installation has reached its 80-workspace limit. Delete or export an older workspace first.');
      await persistWorkspace();
      const previous={workspace,currentId,selectedId,connectSource,autoEdges,zoom,tx,ty};
      const imported=[],idMap=new Map(),stagedAssets=[];let base=null;
      try{
        for(const raw of pack.workspace.nodes){
          const n=sanitizeImportedNode(raw);idMap.set(String(raw?.id||n.id),n.id);
          if(n.asset?.embedded&&typeof n.asset.data==='string'){
            try{
              if(n.asset.data.length>12000000)throw new Error('Embedded attachment is too large.');
              const binary=atob(n.asset.data),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));
              const blob=new Blob([bytes],{type:n.asset.mime||'application/octet-stream'});
              const fileLike=new File([blob],n.fileName||n.title,{type:n.asset.mime||''});
              n.asset=await storeAsset(fileLike);stagedAssets.push(n.asset);
            }catch(error){n.asset=null;n.content+=`\n[Attachment could not be restored: ${String(error.message||'storage unavailable').slice(0,240)}]`;}
          }else if(n.asset){n.asset=null;n.content+=`\n[Attachment was not included in this transfer; the original remains on its source device.]`;}
          imported.push(n);
        }
        base=makeWorkspace(pack.workspace.name||filename.replace(/\.aether$/i,''));
        base.nodes=imported;base.edges=sanitizeImportedEdges(pack.workspace.edges,idMap);
        workspaces.push(base);workspace=base;currentId=base.id;refreshWorkspaceSelect();zoom=1;tx=0;ty=0;selectedId=null;connectSource=null;autoEdges=[];
        renderNodes();fitMesh();queueGravity();
        await persistWorkspace();
        await updateStorageEstimate();
        return base;
      }catch(error){
        if(base)workspaces=workspaces.filter(item=>item.id!==base.id);
        workspace=previous.workspace;currentId=previous.currentId;selectedId=previous.selectedId;connectSource=previous.connectSource;autoEdges=previous.autoEdges;zoom=previous.zoom;tx=previous.tx;ty=previous.ty;
        for(const asset of stagedAssets){try{await removeAsset(asset);}catch(_){}}
        refreshWorkspaceSelect();renderNodes();updateViewFromSaved();queueGravity();
        throw error;
      }
    }
    async function importReality(file){if(file.size>30*1024*1024)throw new Error('Reality files are limited to 30 MB.');const pack=JSON.parse(await file.text());await restoreRealityPack(pack,file.name);say('Workspace imported into a new local project.');}
    async function copyText(text){try{await curioidClipboard.writeText(text);return true;}catch(_){return false;}}
    function openShare(){q('[data-a-share-note]').textContent=`${workspace.nodes.length} nodes and ${workspace.nodes.reduce((n,x)=>n+(x.type==='file'?1:0),0)} attachment reference(s). Export creates a portable copy; the current workspace is not moved.`;q('[data-a-share-dialog]').showModal();}

    function updateViewFromSaved(){const v=workspace.view||{};if(Number.isFinite(v.scale)){zoom=clampA(v.scale,.25,2.5);tx=Number(v.x)||0;ty=Number(v.y)||0;}else{zoom=1;const r=stage.getBoundingClientRect();tx=r.width/2-WORLD_W/2;ty=r.height/2-WORLD_H/2;}applyView();}
    function addManualEdge(a,b){if(!a||!b||a===b)return;if((workspace.edges||[]).length>=2000){say('Workspace limit: 2,000 pinned threads.');return;}const exists=(workspace.edges||[]).some(e=>(e.a===a&&e.b===b)||(e.a===b&&e.b===a));if(exists){say('These nodes are already connected.');return;}workspace.edges.push({a,b,created:Date.now()});renderEdges();updateStats();queueSave();say('Pinned a manual context thread.');}
