    function setInspector(open){inspector.classList.toggle('is-open',open);root.classList.toggle('aether-inspector-open',open);}
    function openNode(id){const n=workspace.nodes.find(x=>x.id===id);if(!n)return;if(n.type==='link'||n.type==='api'){const match=String(n.url||'').match(/^curioid:\/\/(app|world)\/([a-z0-9-]+)$/i);if(!match){say('This is an external reference. CURIOID keeps it as information and does not open outside websites.');return;}if(match[1].toLowerCase()==='app')window.CurioidDoors98OpenApp?.(match[2]);else window.CurioidNavigateToProject?.(match[2]);return;}if(n.type==='file'){getAsset(n.asset).then(blob=>{if(!blob){say('The original local file is unavailable.');return;}downloadBlob(blob,n.fileName||n.title);}).catch(()=>say('Could not open this local attachment.'));return;}const ok=copyText(n.content||n.title);ok.then?ok.then(v=>say(v?'Saved node context to the CURIOID clipboard.':'CURIOID clipboard unavailable.')):say(ok?'Saved node context to the CURIOID clipboard.':'CURIOID clipboard unavailable.');}
    async function deleteNode(id){
      const n=workspace.nodes.find(x=>x.id===id);if(!n)return;
      if(!window.confirm(`Delete “${n.title||'Untitled'}” from this workspace? Its attachment and connected links will also be removed.`))return;
      const previousNodes=workspace.nodes,previousEdges=workspace.edges,previousSelected=selectedId;
      workspace.nodes=previousNodes.filter(x=>x.id!==id);workspace.edges=(previousEdges||[]).filter(e=>e.a!==id&&e.b!==id);if(selectedId===id)selectedId=null;
      renderNodes();selectNode(null);queueGravity();
      try{await persistWorkspace();}
      catch(error){workspace.nodes=previousNodes;workspace.edges=previousEdges;selectedId=previousSelected;renderNodes();if(previousSelected)selectNode(previousSelected);say('Delete cancelled because the workspace could not be saved. '+(error.message||''));return;}
      let attachmentWarning='';
      if(n.asset&&dbMode==='INDEXEDDB'){try{await removeAsset(n.asset);}catch(_){attachmentWarning=' The node was removed, but its attachment cleanup failed. The remaining file data was not intentionally overwritten.';}}
      else if(n.asset){attachmentWarning=' Attachment cleanup was deferred because the workspace is using fallback storage; keeping the original bytes avoids deleting data still referenced by an older IndexedDB snapshot.';}
      say(`Deleted ${n.title||'node'}.${attachmentWarning}`);
    }
    function importNodeForm(event){event.preventDefault();const type=q('[data-a-new-type]').value,title=q('[data-a-new-title]').value.trim(),url=q('[data-a-new-url]').value.trim(),content=q('[data-a-new-content]').value,tags=q('[data-a-new-tags]').value;if(!title){say('Give this node a title first.');return;}let safeUrl='';if(['link','api'].includes(type)){try{const parsed=new URL(url);if(!['http:','https:'].includes(parsed.protocol))throw new Error();safeUrl=parsed.href;}catch(_){say('Enter a valid http or https URL.');return;}}const n=addNode({type,title,url:safeUrl,content,tags});q('[data-a-node-dialog]').close();if(n)say('Added to the contextual mesh.');}
    function renderWorkspaceList(){refreshWorkspaceSelect();}
    async function createWorkspace(){
      if(workspaces.length>=80){say('Workspace limit: 80 projects. Export an older project and delete it before creating another.');return;}
      await persistWorkspace();
      const previous={workspace,currentId,selectedId,connectSource,autoEdges,zoom,tx,ty};
      const created=makeWorkspace(`Project ${workspaces.length+1}`);
      workspace=created;workspaces.push(created);currentId=created.id;selectedId=null;connectSource=null;autoEdges=[];zoom=1;tx=0;ty=0;
      try{
        await persistWorkspace();
        refreshWorkspaceSelect();renderNodes();fitMesh();selectNode(null);say('New project workspace created.');
      }catch(error){
        workspaces=workspaces.filter(item=>item.id!==created.id);
        workspace=previous.workspace;currentId=previous.currentId;selectedId=previous.selectedId;connectSource=previous.connectSource;autoEdges=previous.autoEdges;zoom=previous.zoom;tx=previous.tx;ty=previous.ty;
        refreshWorkspaceSelect();renderNodes();updateViewFromSaved();
        throw error;
      }
    }
    async function deleteWorkspace(){
      if(workspaces.length<=1){say('Keep at least one workspace. This last project cannot be deleted.');return;}
      const target=workspace;
      if(!window.confirm(`Delete project “${target.name}” and its ${(target.nodes||[]).length} node(s) and attachments? This cannot be undone.`))return;
      clearTimeout(saveTimer);
      // Save the active record first, then commit the index change in the storage
      // mode that currently owns the authoritative workspace snapshot.
      await persistWorkspace();
      const remaining=workspaces.filter(item=>item.id!==target.id);
      try{
        if(dbMode==='LOCAL FALLBACK')writeWorkspaceFallback(remaining);
        else await idbDeleteWorkspaceIfRevision(target.id,Number(target.revision)||0);
      }catch(error){if(error?.name==='AetherRevisionConflict')workspaceConflict=true;say(error.message||'Workspace deletion could not be committed.');return;}
      workspaces=remaining;
      workspace=safeJsonClone(workspaces.slice().sort((a,b)=>(b.updated||0)-(a.updated||0))[0]);
      currentId=workspace.id;selectedId=null;connectSource=null;autoEdges=[];
      refreshWorkspaceSelect();renderNodes();updateViewFromSaved();queueGravity();selectNode(null);
      let attachmentFailures=0;
      for(const node of target.nodes||[])if(node.asset){
        if(dbMode!=='INDEXEDDB'){attachmentFailures++;continue;}
        try{await removeAsset(node.asset);}catch(_){attachmentFailures++;}
      }
      say(`Deleted project ${target.name}. Opened ${workspace.name}.${attachmentFailures?` ${attachmentFailures} attachment(s) were retained for safe cleanup.`:''}`);
    }
    async function switchWorkspace(id){if(!id||id===currentId)return;await persistWorkspace();let item=workspaces.find(w=>w.id===id);if(!item){try{item=await idbGet('workspaces',id);}catch(_){}}if(!item)return;workspace=safeJsonClone(item);currentId=workspace.id;selectedId=null;connectSource=null;autoEdges=[];renderWorkspaceList();renderNodes();updateViewFromSaved();queueGravity();selectNode(null);say(`Opened ${workspace.name}.`);}
