          workspaces.push(base);workspace=base;currentId=base.id;refreshWorkspaceSelect();zoom=1;tx=0;ty=0;renderNodes();fitMesh();queueGravity();await persistWorkspace();return{message:`Imported ${base.nodes.length} nodes into a new Aether workspace. Local attachments were not transferred.`,count:base.nodes.length};
