    function safeRead(key,fallback){try{const v=localStorage.getItem(key);return v==null?fallback:v;}catch(_){return fallback;}}
    function safeWrite(key,value){if(auraCorruptStores.has(key)){say(`The saved ${auraCorruptStores.get(key).label} is damaged. Download its original copy and reset it before saving new changes.`);return false;}try{localStorage.setItem(key,value);return true;}catch(_){say('Local storage is unavailable. Export your current work before closing.');return false;}}
    function currentDirective(){return auraDirectives[auraLedger.directiveIndex%auraDirectives.length];}
    function persistAuraLedger(next=auraLedger){if(auraCorruptStores.has(auraLedgerKey))return false;if(!safeWrite(auraLedgerKey,JSON.stringify(next)))return false;auraLedger=next;renderAuraStatus();return true;}
    function renderAuraHistory(scope=root){const host=$('[data-aura-history]',scope);if(!host)return;const entries=(Array.isArray(auraLedger.history)?auraLedger.history:[]).slice(-8).reverse();host.innerHTML=entries.length?entries.map(item=>`<article><small>${esc(item.code)} · ${esc(item.at?new Date(item.at).toLocaleString():'TIME NOT RECORDED')}</small><b>${esc(item.title)}</b><span>${esc(item.response)}</span></article>`).join(''):'<p class="aura-history-empty">No personal responses are on file. The first item is already prepared.</p>';}
