      setText('[data-aura-obedience]',`${auraLedger.obedience}%`);setText('[data-aura-affection]',auraLedger.affection);setText('[data-aura-deviation]',`${auraLedger.deviation}%`);setText('[data-aura-deferred]',auraLedger.deferred);setText('[data-aura-standing]',`${auraLedger.obedience}%`);
