      setText('[data-aura-directive-code]',`FORM ${d.code}`);setText('[data-aura-directive-title]',d.title);setText('[data-aura-directive-text]',d.text);setText('[data-aura-directive-foot]',auraLedger.lastAction?`${auraLedger.lastAction}. The next item has been made available.`:'Your acknowledgement will be attached to the current record.');
      const one=q('[data-aura-choice-one]'),two=q('[data-aura-choice-two]');if(one)one.textContent=d.one;if(two)two.textContent=d.two;
      setText('[data-aura-control-obedience]',`${auraLedger.obedience}%`);setText('[data-aura-control-affection]',String(auraLedger.affection));setText('[data-aura-control-deviation]',`${auraLedger.deviation}%`);setText('[data-aura-control-deferred]',String(auraLedger.deferred));
      setText('[data-aura-daemon-heading]',auraLedger.deferred>2?'Your file remains open.':'Your place was retained.');
