      required.forEach(([key,label])=>{if(hasSubstance(key,releaseDraft[key]))passed.push(`${label} is present.`);else blockers.push(`${label} is missing or still contains only starter prompts.`);});
      if(/^new (browser application|game release|creative release|publication|research release)$/i.test(String(releaseDraft.title||'').trim())||/^untitled/i.test(String(releaseDraft.title||'')))warnings.push('The project title still uses starter wording. Replace it with the actual release title.');
      if(/^local creator$/i.test(String(releaseDraft.creator||'').trim()))warnings.push('The creator field still uses its default placeholder.');
      if(String(releaseDraft.notes||'').trim()&&String(releaseDraft.notes).split(/\r?\n/).filter(line=>line.trim()).every(line=>/^[A-Z][A-Z0-9 /&()_.-]{1,48}:$/.test(line.trim().toUpperCase())))warnings.push('Release notes contain only blank starter prompts. Add the actual changes or remove unused prompts.');
