      if(!releaseAssets.length)warnings.push('No files are in the asset inventory. Add the intended release files or confirm that this project has no separate assets.');
      const totalBytes=releaseAssets.reduce((sum,item)=>sum+Math.max(0,Number(item.size)||0),0);
      if(releaseAssets.length>100)blockers.push('The asset inventory has more than 100 files. Split the package before building.');
      if(totalBytes>16*1024*1024)blockers.push('The inventoried files exceed the 16 MB portable-package limit.');
