      panel.replaceChildren();const heading=document.createElement('b');heading.textContent='SAVED DATA NEEDS RECOVERY';panel.append(heading);const intro=document.createElement('p');intro.textContent='One or more local records could not be read safely. CURIOID has kept the original data and blocked overwriting it. Download a recovery copy before resetting a damaged record.';panel.append(intro);
